window.SG_INDEX=[{"c":"1-1","n":"最初の2週間","s":"この章が扱う範囲","t":"子犬を迎えてからの健康確認、事故予防、新しい暮らしへの慣らし方を扱います。手続きは 1-2章 、社会化の詳しい進め方は 2-1 ・ 2-2章 で扱います。「2週間」は生活を整えるための目安で、慣れる期限ではありません。","u":"guide/first-weeks/","a":"b1","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"元気な子犬も、迎えてから1週間以内を目安にかかりつけの動物病院で診てもらってください。異変があれば、その日を待たずに連絡します。家でできる慣らしは、体調と反応を見ながら初日から始めてください。","u":"guide/first-weeks/","a":"b2","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"事故、病気の見逃し、怖がりなど、減らしたい問題が異なるため、推奨を分けます。確実性も項目ごとに示します。","u":"guide/first-weeks/","a":"b3","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨1","u":"guide/first-weeks/","a":"b4","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"初診を受け、健康状態と今後のケアを確認する","u":"guide/first-weeks/","a":"b5","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨2","u":"guide/first-weeks/","a":"b6","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"脱走・誤食・転落を防ぐ環境をつくる","u":"guide/first-weeks/","a":"b7","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨3","u":"guide/first-weeks/","a":"b8","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"無理のない社会化で、人・音・手入れに慣らす","u":"guide/first-weeks/","a":"b9","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨4","u":"guide/first-weeks/","a":"b10","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"元気と食欲を毎日見て、異変に気づく","u":"guide/first-weeks/","a":"b11","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨5","u":"guide/first-weeks/","a":"b12","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"体重を定期的に測り、成長や減少の傾向を見る","u":"guide/first-weeks/","a":"b13","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨6","u":"guide/first-weeks/","a":"b14","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"フードの急な変更を避け、食事の変化を小さくする","u":"guide/first-weeks/","a":"b15","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"推奨7","u":"guide/first-weeks/","a":"b16","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"一人で落ち着いて過ごす練習をする","u":"guide/first-weeks/","a":"b17","e":0},{"c":"1-1","n":"最初の2週間","s":"この章の推奨","t":"「シェルティでどれだけ役立つかの確かさが非常に低い」は、効果が小さいという意味ではなく、どの程度役立つかをシェルティで確かめられていないという意味です。 強さの根拠は研究の量ではなく、害の小ささと必要性です。 ただし、怖がる子犬に経験を強いることは、この推奨に含みません。","u":"guide/first-weeks/","a":"b18","e":0},{"c":"1-1","n":"最初の2週間","s":"なぜこれが重要か","t":"迎えた直後は、その子の普段の食欲や動きがまだ分かりません。生活を整えながら観察し、相談先を決めておくことが大切です。","u":"guide/first-weeks/","a":"b19","e":0},{"c":"1-1","n":"最初の2週間","s":"なぜこれが重要か","t":"同時に、 社会化（人・動物・音・場所などに、怖がりすぎず接するための経験） も始める時期です。生後早期は新しい経験に慣れやすい時期ですが、特定の日で学べなくなるわけではありません。休ませる時間と、無理なく経験する機会の両方を用意します。","u":"guide/first-weeks/","a":"b20","e":0},{"c":"1-1","n":"最初の2週間","s":"なぜこれが重要か","t":"本章は犬一般・他犬種の知見をシェルティに当てはめており、この犬種で同じ効果の大きさが確認されたわけではありません。","u":"guide/first-weeks/","a":"b21","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"初診と生活の準備","u":"guide/first-weeks/","a":"b22","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"初診には、それまでの食事、ワクチン・予防薬、治療の記録、手元にある遺伝子検査の結果を持参します。外での活動の始め方も相談してください。「1週間以内」は研究で決まった期限ではなく、相談先を早く確保するための目安です。 これは経験則です 。","u":"guide/first-weeks/","a":"b23","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"フードはまず、それまでの種類・量・回数を引き継ぎます。変更が必要なら急に切り替えず、体調を見て相談します。生活の変更を重ねないこと、眠っている間は構わず休める場所を用意することは、実務上の工夫です。 これは経験則です 。","u":"guide/first-weeks/","a":"b24","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"毎日見るもの","u":"guide/first-weeks/","a":"b25","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"元気と食欲は毎日確認します。便や吐いたもの、飲水・排尿に気になる変化があれば記録します。体重は同じはかりで、食前など条件をそろえて定期的に測ります。","u":"guide/first-weeks/","a":"b26","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"体重は1回の数字だけでなく傾向を見ます。ただし、 食べない、元気がないなどの変化があれば、何日分も記録がそろうのを待たず相談してください。","u":"guide/first-weeks/","a":"b27","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"脱走と事故を防ぐ","u":"guide/first-weeks/","a":"b28","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"部屋の扉を閉めてから玄関を開けるなど、外まで一度に出られない仕切りをつくる。","u":"guide/first-weeks/","a":"b29","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"首輪やハーネス（胴輪）が抜けないか、外に出る前に確認する。","u":"guide/first-weeks/","a":"b30","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"電気コード、小物、薬、観葉植物を届かない場所へ移す。","u":"guide/first-weeks/","a":"b31","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"チョコレート、キシリトール入りの菓子・歯みがき粉、ブドウ・レーズン、ネギ類を届かない場所へ移す。","u":"guide/first-weeks/","a":"b32","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"小さい子どもは床に座り、犬から近づくのを待つ。抱き上げて運ばせない。","u":"guide/first-weeks/","a":"b33","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"先住犬とは互いに離れられる場所を用意し、初日から自由に接触させない。","u":"guide/first-weeks/","a":"b34","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"家でできる慣らし","u":"guide/first-weeks/","a":"b35","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"足先や耳に短く触れる、ブラシを当てる、キャリーに入るなど、日常の手入れや移動に少しずつ慣らします。落ち着いて受け入れられたら、ほめるなどのごほうびを添えます。","u":"guide/first-weeks/","a":"b36","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"来客は大勢で囲んだり抱き上げたりせず、子犬から近づける形にします。生活音にも、怖がらない距離や大きさから触れさせます。 怖がったら中止し、距離や刺激を調整してください。 長く続けることより、その子の反応を優先します。","u":"guide/first-weeks/","a":"b37","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"ワクチン完了まで家での経験も止める必要はありません。ただし、家の中だけで社会化が完結するわけではなく、外の場所や犬との接触は獣医師と相談して進めます。","u":"guide/first-weeks/","a":"b38","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"一人で過ごす練習","u":"guide/first-weeks/","a":"b39","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"安全な場所で、ごく短い時間から始め、不安を強く示さない範囲で延ばします。急に長時間の留守番へ切り替えないでください。","u":"guide/first-weeks/","a":"b40","e":0},{"c":"1-1","n":"最初の2週間","s":"実際にどうするか","t":"鳴かせたまま長時間放置せず、排泄、空腹、暑さ寒さなど、困っていることがないか確かめます。体調の異変があれば受診を相談します。具体的な進め方は経験則で、将来の留守番の問題を確実に防げる方法ではありません。","u":"guide/first-weeks/","a":"b41","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"夜間・休日の連絡先も、迎える前に調べておきます。以下は病名を判断する表ではなく、相談する時期の目安です。","u":"guide/first-weeks/","a":"b42","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"今すぐ連絡（夜間・休日でも）","u":"guide/first-weeks/","a":"b43","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"ぐったりして反応が鈍い、急に立てない、歯ぐきが白い。","u":"guide/first-weeks/","a":"b44","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"呼吸が苦しそう、けいれん、意識がおかしい。","u":"guide/first-weeks/","a":"b45","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"繰り返し吐く、水を飲んでも吐く、血が混じった便や黒い便が出る。","u":"guide/first-weeks/","a":"b46","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"誤食、転落、交通事故や強い衝突のあと。","u":"guide/first-weeks/","a":"b47","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"その日のうちに連絡","u":"guide/first-weeks/","a":"b48","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"食欲が明らかに落ちた、食べない。","u":"guide/first-weeks/","a":"b49","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"下痢が続く、体重が減ってきた。","u":"guide/first-weeks/","a":"b50","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"咳、鼻水、目やに、くしゃみが続く。","u":"guide/first-weeks/","a":"b51","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"歩き方がおかしい、足を痛がる。","u":"guide/first-weeks/","a":"b52","e":0},{"c":"1-1","n":"最初の2週間","s":"こんなときは受診を","t":"上の「今すぐ」にも当てはまる場合は、そちらを優先します。子犬を対象として、 11章 より早めの相談を勧める項目があります。 記録や撮影のために連絡を遅らせないでください。迷ったら電話し、受診時刻は獣医師と決めます。","u":"guide/first-weeks/","a":"b53","e":0},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"1．この章の根拠の位置づけ","u":"guide/first-weeks/","a":"b54","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"本章で用いた資料からは、「迎えた最初の2週間」の過ごし方を一括して比較し、シェルティの健康への効果を測った研究は確認できません。「2週間」「初診は1週間以内」は、生物学的な境界でも、試験で最適とされた日数でもありません。日々の観察と相談先づくりのための運用上の目安です。","u":"guide/first-weeks/","a":"b55","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"初診、事故予防、元気・食欲の観察の評価には、専門家の判断と、危険を減らす仕組みの妥当性を含めています。比較試験だけで付けた格付けではありません。良い方向に働くことの確かさが「中」「高」でも、発病や事故が何割減るかを示せるわけではありません。","u":"guide/first-weeks/","a":"b56","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"2．社会化の時期と犬種","u":"guide/first-weeks/","a":"b57","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"Scott JP, Fuller JL. Genetics and the Social Behavior of the Dog . University of Chicago Press; 1965. この研究計画全体にシェルティが含まれることと、個々の実験でシェルティの社会化の時期が確かめられたことは区別します。","u":"guide/first-weeks/","a":"b58","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"Freedman DG, King JA, Elliot O. Critical period in the social development of dogs. Science . 1961;133:1016–1017. 原著 。元稿で整理したとおり、時期を直接調べた実験はコッカースパニエルとビーグルが対象で、シェルティ固有の期限を決める資料にはなりません。研究施設の飼育条件も家庭とは異なります。今回、この原著の実験条件の詳細は再検証しておらず、新たな数値は加えていません。","u":"guide/first-weeks/","a":"b59","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"米国獣医行動学会（AVSAB）の 子犬の社会化に関する声明 は、ワクチン完了前から、過度な恐怖を与えない社会化を支持しています。これは専門団体の推奨であり、本章の手順全体の効果を検証した試験ではありません。家での慣らしと、感染対策を伴うクラス参加も区別する必要があります。","u":"guide/first-weeks/","a":"b60","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"元稿では、声明にあるクラス参加の開始条件を社会化全体の開始時期として記載していました。今回この混同を解消しました。また、同声明の「若い犬の死因」に関する記述は、本章の推奨を支える一般集団の死因統計として使用しません。","u":"guide/first-weeks/","a":"b61","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"3．社会化と感染症","u":"guide/first-weeks/","a":"b62","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"Stepita ME, Bain MJ, Kass PH. Frequency of CPV infection in vaccinated puppies that attended puppy socialization classes. J Am Anim Hosp Assoc . 2013;49:95–100. 原著情報 。犬パルボウイルス（CPV）は子犬に重い消化器症状などを起こすウイルスです。","u":"guide/first-weeks/","a":"b63","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"この観察研究では、クラス参加の子犬279頭で、感染の疑い・診断が報告されませんでした。著者らは接種済みの参加犬について、非参加犬より感染リスクが高いとは認めなかったと報告しています。今回確認できたのは原著抄録の範囲です。","u":"guide/first-weeks/","a":"b64","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"ただし、無作為に参加を割り付けた研究ではなく、参加する犬や管理方法の違いが影響し得ます。 発生ゼロは、危険ゼロや両群の安全性が同じことの証明ではありません。 日本のすべての地域、シェルティ、犬が集まる公園へはそのまま当てはめられません。この研究だけで「管理された場所なら安全」とは断定せず、本文では外での活動を獣医師との相談に戻しています。","u":"guide/first-weeks/","a":"b65","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"4．食事・観察・一人で過ごす練習","u":"guide/first-weeks/","a":"b66","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"元気・食欲の観察は異変を伝えるため、体重測定は変化を補助的に捉えるための提案です。観察自体が病気を防ぐわけではありません。測定条件による体重の変化もあるため、体重だけで診断したり、症状があるのに記録の蓄積を待ったりする使い方は避けます。","u":"guide/first-weeks/","a":"b67","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"フードの急な変更を避けること、休める環境、一人の時間を短く始める方法は 経験則です 。AVSAB声明も安全な場所で一人で遊ぶ・眠る機会に触れていますが、本章の方法によって将来の問題をどの程度防げるかは分かりません。嫌がる状態を長引かせる負担も考え、弱い推奨のままとしています。","u":"guide/first-weeks/","a":"b68","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"「3日・3週間・3か月で適応する」という一律の予定表は採用しません。本章で確認した資料では、その日数を裏づけられないためです。元稿の「飼い主27名、半数以上が4か月以上」という調査は書誌が特定できず、今回の根拠から外しました。適応に時間がかかることだけで異常とも正常とも判定しません。","u":"guide/first-weeks/","a":"b69","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"5．フェロモン製品：肯定的結果と限界","u":"guide/first-weeks/","a":"b70","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"犬用アピーシングフェロモン（DAP）は、母犬由来の化学的な信号を模した製品です。元稿で引用したGaultierらの試験（ Vet Rec . 2008;163:73–80、 原著情報 ）は、迎えた子犬の夜鳴きなどの軽減を報告しています。一方、Frank D, Beauchamp G, Palestrini C. Systematic review of the use of pheromones for treatment of undesirable behavior in cats and dogs. J Am Vet Med Assoc . 2010;236:1308–1316（ 原著情報 ）は、多くの用途で十分な証拠がないと評価しています。系統的レビューとは、一定の方法で研究を集めて評価する整理です。","u":"guide/first-weeks/","a":"b71","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"元稿にあったTaylor・Millsの試験（ Appl Anim Behav Sci . 2007;105:358–368）の「夜間の粗相に群間差なし」という個別結果と、Gaultier論文への複数の効果の帰属は、今回原著本文を確認できず再確認事項として残します。正確性が未確認の詳細を、肯定・否定いずれの断定にも用いません。肯定的報告だけで推奨を作らず、効果の不確実性を明示し、製品を推奨に含めない方針を維持します。「害はほぼない」という元稿の安全性の断定も、根拠を示せないため削除しました。","u":"guide/first-weeks/","a":"b72","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"6．受診の目安と利益・害","u":"guide/first-weeks/","a":"b73","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"米国動物病院協会（AAHA）の 救急徴候の案内 は、呼吸困難、反応の異常、けいれん、外傷、急な運動機能の喪失などを急ぐ徴候としています。続く嘔吐・下痢による脱水などは、子犬で特に問題になります。","u":"guide/first-weeks/","a":"b74","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"本文の二段階の区分は、この案内と既存の受診章を参照して子犬向けに整理したものです。この表自体の正確さが研究で検証されたわけではなく、 これは経験則です 。「その日のうち」は診断や一律の受診時刻の指定ではなく、電話で緊急度を確認する期限です。","u":"guide/first-weeks/","a":"b75","e":1},{"c":"1-1","n":"最初の2週間","s":"根拠","t":"初診や事故予防を強く勧めるのは、必要性に対して通常の負担が小さいためです。一方、通院には費用・移動の負担があり、観察を増やしすぎれば飼い主の負担になります。社会化も強制すれば害になり得ます。推奨は、記録を完璧にすることや、予定どおりに慣らし終えることを求めていません。","u":"guide/first-weeks/","a":"b76","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"この章が扱う範囲","t":"日本国内で犬を迎えたときの、マイクロチップの名義変更、市区町村への登録、狂犬病予防注射に伴う手続きを扱います。主に、マイクロチップが環境省の制度に登録済みの犬を譲り受ける場合を想定しています。海外からの輸入手続きは対象外です。","u":"guide/registration/","a":"b77","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"この章の推奨","t":"迎えたら登録証明書と接種記録を確認し、マイクロチップの変更登録は譲り受けから30日以内に行ってください。市区町村の登録と狂犬病予防注射は、犬の年齢・登録歴・接種歴に応じて手続きしてください。","u":"guide/registration/","a":"b78","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"この章の推奨","t":"この章は法的義務の案内です。推奨度、良い方向に働くことの確かさ、シェルティでどれだけ役立つかの確かさは、いずれも 評価対象外 とします。法律上必要かどうかと、健康への効果がどれほどかは別の問題だからです。犬種による義務の違いはありません。","u":"guide/registration/","a":"b79","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"なぜこれが重要か","t":"マイクロチップが入っていても、飼い主の情報が自動であなたに変わるわけではありません。 登録が前の飼い主のままだと、迷子で保護されても、あなたへの連絡につながらないおそれがあります。[1]","u":"guide/registration/","a":"b80","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"なぜこれが重要か","t":"また、マイクロチップの情報登録、市区町村への犬の登録、予防注射の記録は別の仕組みです。一つ済ませただけで、すべて完了したと思わないでください。[1–3]","u":"guide/registration/","a":"b81","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"1．受け取る書類を確認する","u":"guide/registration/","a":"b82","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"マイクロチップの「登録証明書」と、これまでのワクチン接種記録を受け取ります。市区町村に登録済みなら、鑑札（かんさつ：犬の登録番号が記された標識）も確認してください。狂犬病予防注射済みなら、注射済票（ちゅうしゃずみひょう：接種を済ませたことを示す標識）と接種日を確認します。","u":"guide/registration/","a":"b83","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"2．マイクロチップの名義を変える","u":"guide/registration/","a":"b84","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"譲り受けから30日以内に、環境省の「犬と猫のマイクロチップ情報登録」で変更登録をします。登録証明書にある番号と暗証記号を使い、手続き後の新しい登録証明書を保管してください。2026年9月確認時の手数料は、オンライン400円、紙の申請1,400円です。[1]","u":"guide/registration/","a":"b85","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"書類がない場合は、譲渡元に確認してください。民間団体への登録は、環境省の登録とは別です。未装着・未登録の場合も同じ手順とは限らないため、登録先と必要書類を確認します。[1]","u":"guide/registration/","a":"b86","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"3．市区町村への登録を確認する","u":"guide/registration/","a":"b87","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"未登録で、生後91日以上","u":"guide/registration/","a":"b88","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"取得から30日以内に、犬の所在地の市区町村へ登録","u":"guide/registration/","a":"b89","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"未登録で、生後90日以内","u":"guide/registration/","a":"b90","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"生後91日になった日から30日以内に登録","u":"guide/registration/","a":"b91","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"すでに登録済み","u":"guide/registration/","a":"b92","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"生涯1回の登録をやり直さず、所有者変更の届出。原則30日以内","u":"guide/registration/","a":"b93","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"「特例制度」は、環境省への登録情報の通知を、市区町村への登録申請などとして扱う仕組みです。 参加自治体では、対象の犬について別途の申請が不要になり、マイクロチップが鑑札の代わりになります。ただし、装着だけでは適用されません。自治体の参加状況と、自分の犬の手続きが完了しているかを確認してください。[1,2]","u":"guide/registration/","a":"b94","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"4．狂犬病予防注射と注射済票を確認する","u":"guide/registration/","a":"b95","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"生後91日以上の犬には毎年1回の接種義務があります。初回は年齢と過去の接種日を伝え、迎えた時点で動物病院に予定を相談してください。生後90日以内に迎えた子犬を、年齢にかかわらず「迎えて30日以内」とは扱いません。[3,4]","u":"guide/registration/","a":"b96","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"2026年の通常の接種期間は4月1日〜6月30日です。生後91日以上で、3月2日以降の接種がない犬や接種歴不明の犬を迎えた場合は、取得から30日以内が原則です。すでに接種済みなら、重複して接種する前に記録を確認します。[4]","u":"guide/registration/","a":"b97","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"接種後は、注射済票の交付まで済ませます。動物病院で交付を受けられる場合と、接種証明書を持って市区町村で申請する場合があります。 マイクロチップの特例制度でも、この手続きは別です。 鑑札（特例適用時を除く）と注射済票は犬に着けてください。[2,3,6]","u":"guide/registration/","a":"b98","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"5．2027年の変更に注意する","u":"guide/registration/","a":"b99","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"通年接種への変更は2027年3月2日からです。 2026年4月1日は公布日であり、施行日ではありません。毎年1回の義務は残り、接種間隔を延ばさず、毎年同じ時期に受けることが求められています。[5]","u":"guide/registration/","a":"b100","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"また、2027年3月2日〜31日の接種には、翌年度ではなく2026年度の注射済票が交付されます。この時期に接種予定なら、次の接種日と年度の扱いを動物病院・市区町村に確認してください。[5]","u":"guide/registration/","a":"b101","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"6．引っ越しなどの後も情報を更新する","u":"guide/registration/","a":"b102","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"実際にどうするか","t":"住所・連絡先の変更や死亡の際は、マイクロチップの登録先へ届け出ます。市区町村にも住所・所有者の変更や死亡の届出が必要で、原則30日以内です。特例制度で省略できる手続きもあるため、転居先などの窓口で確認してください。[1–3]","u":"guide/registration/","a":"b103","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"こんなときは受診を","t":"接種前に体調の問題がある場合や、過去の接種で具合が悪くなった場合は、予約時に獣医師へ伝えてください。期限だけを理由に、接種できるかを自己判断しないでください。","u":"guide/registration/","a":"b104","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"こんなときは受診を","t":"獣医師が接種を見合わせると判断した場合は、猶予証明書（接種を延期する医学的理由を記した書類）の要否・提出先・有効期間を市区町村に確認します。 猶予の扱いを全国一律の「年度ごと」とは決めつけません。 [6]","u":"guide/registration/","a":"b105","e":0},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"1．マイクロチップ登録の根拠と限界","u":"guide/registration/","a":"b106","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"動物の愛護及び管理に関する法律第39条の6は、登録済みの犬猫を登録証明書とともに譲り受けた一般飼い主の変更登録を定めています。環境省の案内で、登録証明書の受け渡し、オンラインの申請方法、手数料、民間登録との違いを確認しました。","u":"guide/registration/","a":"b107","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"マイクロチップは、保護された犬の番号を登録情報と照合するためのものです。登録を更新すれば必ず返還される、という意味ではありません。本章では、返還率の改善幅やシェルティ固有の効果量は評価していません。","u":"guide/registration/","a":"b108","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 環境省「犬と猫のマイクロチップ情報登録について」 、 同Q&A 。法令参照： 動物の愛護及び管理に関する法律 。","u":"guide/registration/","a":"b109","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"2．特例制度の対象","u":"guide/registration/","a":"b110","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"厚生労働省の特例に関する説明と環境省の案内では、指定登録機関から参加市区町村への通知が、犬の登録申請や変更届などに相当します。生後90日以内に登録した犬の情報は、生後91日に達した時点で通知されます。チップを装着しただけで市区町村の登録が完了するわけではなく、注射済票まで代替する制度でもありません。","u":"guide/registration/","a":"b111","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 厚生労働省「マイクロチップの装着等の義務化に係る狂犬病予防法の特例に関する対応について」 。","u":"guide/registration/","a":"b112","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"3．市区町村への登録と標識","u":"guide/registration/","a":"b113","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"狂犬病予防法第4条は登録と変更・死亡の届出、鑑札の装着を、第5条は毎年の予防注射と注射済票の装着を定めています。登録の取得後30日という期限には、生後90日以内の犬についての起算日の例外があります。登録済みの犬の譲渡は新規登録と区別します。","u":"guide/registration/","a":"b114","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"制度の義務を、健康介入の効果を示す研究として評価することはできません。そのため本章では、推奨度と確実性2軸を評価対象外としました。他犬種の治療効果をシェルティへ外挿する章ではありません。","u":"guide/registration/","a":"b115","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 狂犬病予防法 、 厚生労働省「狂犬病に関するQ&A」 。","u":"guide/registration/","a":"b116","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"4．現行の接種時期","u":"guide/registration/","a":"b117","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"厚生労働省の2024年3月12日通知は、施行規則第11条の通常の接種期間と、一定の接種歴がない生後91日以上の犬を取得した場合の30日以内という規定を説明しています。本章では、この通常規定の説明を参照しました。同通知の能登半島地震に伴う2024年限りの特例を、2026年の一般的な猶予として用いてはいません。","u":"guide/registration/","a":"b118","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"接種時期には年齢・接種歴による条件があるため、初回を一律に「取得から30日以内」とする旧版の表を改めました。個々の子犬の接種日は獣医師・自治体への確認に戻しています。","u":"guide/registration/","a":"b119","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 厚生労働省、感発0312第2号、2024年3月12日 。","u":"guide/registration/","a":"b120","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"5．2027年の改正","u":"guide/registration/","a":"b121","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"令和8年厚生労働省令第73号について、2026年4月1日の公布通知（感発0401第1号）を確認しました。施行日は2027年3月2日。接種期間の限定と、3月2日〜31日の接種に翌年度の注射済票を交付する規定が廃止されます。2027年3月中の交付年度と、接種間隔を延ばさない旨も通知に明記されています。","u":"guide/registration/","a":"b122","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"通年化は接種回数を減らせるという意味ではありません。この制約を落とすと、制度変更の利便性だけが強調されるため本文に残しました。","u":"guide/registration/","a":"b123","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 厚生労働省「狂犬病予防法施行規則の一部を改正する省令の公布について」2026年4月1日 。","u":"guide/registration/","a":"b124","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"6．接種を見合わせる場合と自治体差","u":"guide/registration/","a":"b125","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"八尾市は傷病などで接種困難と獣医師が判断した場合、当該年度の猶予証明書の提出を案内しています。一方、泉佐野市は証明書記載の期間に従い、期間の記載がなければ単年度としています。この違いから、旧版の「猶予は年度ごと」という全国一律の記述を外しました。","u":"guide/registration/","a":"b126","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"特例制度への参加、窓口、手数料、猶予の提出方法は自治体ごとに確認が必要です。ここに挙げる自治体の運用を全国に一般化しません。","u":"guide/registration/","a":"b127","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"出典： 八尾市「狂犬病予防注射の手続き」 、 泉佐野市「飼い犬登録と狂犬病予防注射」 。","u":"guide/registration/","a":"b128","e":1},{"c":"1-2","n":"迎えたときの手続き","s":"根拠","t":"資料確認日：2026年9月16日。介入効果を比較した研究は採用しておらず、有効性を示さなかった研究の選別は行っていません。制度の適用条件・例外・限界を上記に記載しました。","u":"guide/registration/","a":"b129","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"この章が扱う範囲","t":"社会化とは、人や犬との出会いを通して、相手がいても安心して過ごせるように学ぶことです。この章は「誰に、どう会わせるか」を扱います。音・道具・体に触れられることに慣らす方法は 2-2章 です。","u":"guide/socialisation/","a":"b130","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"推奨1：人や犬への恐怖を減らすために","u":"guide/socialisation/","a":"b131","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"早い時期から、見知らぬ人や穏やかな犬に、子犬が自分から近づくか離れるかを選べる形で会わせてください。生後16週ごろまでは特に大切ですが、締切ではありません。その後も続けます。","u":"guide/socialisation/","a":"b132","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"推奨2：経験そのものによる苦痛を避けるために","u":"guide/socialisation/","a":"b133","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"怖がったら中止して距離を取り、無理に触れ合わせないでください。叱る、押さえつける、驚かせる方法は避け、褒める・遊ぶなどのごほうびを使います。","u":"guide/socialisation/","a":"b134","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"推奨3：感染を避けながら経験を確保するために","u":"guide/socialisation/","a":"b135","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"ワクチン計画を守り、接触する犬・場所と地域の流行状況を獣医師に確認して社会化を進めてください。接種が完了していないことだけを理由に、すべての経験を先送りしないでください。","u":"guide/socialisation/","a":"b136","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"この章の推奨","t":"将来の恐怖、経験中の苦痛、感染との両立では、評価する結果と根拠が違うため推奨を分けました。 確実性が低い部分も強く推奨する根拠は、研究の量ではなく、適切に行った場合の害の小ささと必要性です。 無理な接触や感染リスクの高い場所への外出を強く勧めるものではありません。","u":"guide/socialisation/","a":"b137","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"なぜこれが重要か","t":"犬には、幼い時期に人や犬との関係を学びやすい期間があります。古い隔離実験は早期の接触の重要性を示しましたが、通常の家庭で育った犬が「16週を過ぎたら学べない」ことを示す研究ではありません。","u":"guide/socialisation/","a":"b138","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"なぜこれが重要か","t":"フィンランドの飼い主調査では、シェルティは人や犬への恐怖が多い犬種群でした。一方、 社会化によってシェルティの恐怖がどれだけ減るかは、その研究から分かりません。 怖がりやすさを飼い主の育て方だけで説明することもできません。","u":"guide/socialisation/","a":"b139","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"なぜこれが重要か","t":"社会化の効果や関わり方の推奨には、複数犬種・他犬種の知見をシェルティへ当てはめています。 犬種差のデータと、社会化の効果のデータは別です。","u":"guide/socialisation/","a":"b140","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"なぜこれが重要か","t":"迎える前の経験をブリーダーに聞き、迎えた後に引き継いでください。親犬の性質も尋ねて構いません。「100日で100人」など、達成すべき回数は設けません。","u":"guide/socialisation/","a":"b141","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"誰に会わせるか","u":"guide/socialisation/","a":"b142","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"人： 帽子や眼鏡の人、子ども、高齢者、杖や車椅子を使う人など。子どもには必ず大人がつき、追いかけさせないでください。","u":"guide/socialisation/","a":"b143","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"犬： 健康状態とワクチン接種を確認できる、穏やかで子犬の扱いが上手な犬を選びます。不特定多数の犬に囲ませたり、一方的に追い回させたりしないでください。","u":"guide/socialisation/","a":"b144","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"回数より、子犬の様子を優先する","u":"guide/socialisation/","a":"b145","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"自分から近づけるようにする。 抱えて相手へ差し出したり、犬の群れに置いたりしません。","u":"guide/socialisation/","a":"b146","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"離れられる場所を用意する。 近づかなければ失敗、とは考えません。","u":"guide/socialisation/","a":"b147","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"短く、落ち着いているうちに終える。 これは経験則です 。時間や回数の一律の目標より、目の前の子犬の様子を優先します。","u":"guide/socialisation/","a":"b148","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"怖がるサインが出たら中止する。 固まる、後ろに下がる、逃げようとする、尻尾を巻く、耳を伏せるなどです。あくびや舌なめずりだけで決めつけず、ほかの変化と一緒に繰り返していないか見ます。","u":"guide/socialisation/","a":"b149","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"怖がったことを叱らない。 その場で耐えさせるのではなく、距離を取って落ち着けるようにします。","u":"guide/socialisation/","a":"b150","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"ワクチンと両立させる","u":"guide/socialisation/","a":"b151","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"世界小動物獣医師会の2024年指針は、ワクチン計画を守りながら早期の社会化を進める立場です。ワクチン接種と社会化は時期が重なります。","u":"guide/socialisation/","a":"b152","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"自宅に人を招く、抱っこやカートから人や犬を見るなど、直接触れ合わせずにできる経験もあります。犬と会わせるときは、相手の健康状態と接種歴、場所の衛生管理を確認します。 抱っこや屋内なら感染しない、という意味ではありません。","u":"guide/socialisation/","a":"b153","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"不特定多数の犬が出入りし、健康状態や接種歴が分からない場所は避けます。獣医師には「散歩は可能か」だけでなく、 「今できる社会化は何か」 を相談してください。","u":"guide/socialisation/","a":"b154","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"パピークラスを選ぶ","u":"guide/socialisation/","a":"b155","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"パピークラス（子犬と飼い主が一緒に学ぶ教室）は、健康確認とワクチン接種を参加条件とし、ごほうびを使う教室を選びます。月齢・体格にも配慮があり、怖がったら休めることを確認してください。隅で固まったまま参加を続ける必要はありません。","u":"guide/socialisation/","a":"b156","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"16週を過ぎたら","u":"guide/socialisation/","a":"b157","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"実際にどうするか","t":"無理のない出会いを続けます。急に怖がり始めても、成長に伴う一時的な変化と決めつけず、下記の目安で相談してください。","u":"guide/socialisation/","a":"b158","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"こんなときは受診を","t":"見知らぬ人を強く避け続ける、来客のたびに隠れて出てこない。","u":"guide/socialisation/","a":"b159","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"こんなときは受診を","t":"特定の人や犬に固まる、震える、パニックになる。","u":"guide/socialisation/","a":"b160","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"こんなときは受診を","t":"人や犬に繰り返し唸る（うなる）、歯を当てる、噛もうとする。人に傷を負わせた場合は一度でも。","u":"guide/socialisation/","a":"b161","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"こんなときは受診を","t":"それまで平気だったことを急に嫌がるようになった。","u":"guide/socialisation/","a":"b162","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"こんなときは受診を","t":"しつけだけの問題と判断せず、かかりつけの獣医師へ相談してください。 行動の変化の背景には痛みなどが関係することもあり、必要に応じて行動診療につなげてもらいます。","u":"guide/socialisation/","a":"b163","e":0},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"主要な研究","u":"guide/socialisation/","a":"b164","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"1. Freedman DG, King JA, Elliot O. Critical period in the social development of dogs. Science. 1961;133:1016-1017.","u":"guide/socialisation/","a":"b165","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"コッカースパニエルとビーグルの子犬を生後2週から14週まで人と接触させずに育て、29頭を生後2〜9週の各時点で1週間だけ人と過ごさせた実験（対照群5頭は社会化なし）。 7週が最も受容性が高く、およそ2.5〜9週が中心期 と結論しています。対照群の1頭は3か月かけても改善がわずかでした。","u":"guide/socialisation/","a":"b166","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"限界。 人との接触条件が極端（完全隔離と1日1.5時間の接触）、1960年代の犬舎環境、2犬種、少数例。 支持されるのは「早い時期が重要であること」であって、「16週で窓が閉じること」でも「量が多いほど良いこと」でもありません。 恐怖回避行動の出現時期には犬種差も報告されています（Morrow M, et al. 2015）。","u":"guide/socialisation/","a":"b167","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"2. Puurunen J, et al. Inadequate socialisation, inactivity, and urban living environment are associated with social fearfulness in pet dogs. Sci Rep. 2020;10:3527. 原著","u":"guide/socialisation/","a":"b168","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"フィンランドの飼い主質問票（初期データ13,715頭）から、他犬への恐怖5,973頭、対人恐怖5,932頭を、複数の要因を考慮する方法で解析しました。社会化スコアは生後7〜16週に見知らぬ人や成犬に会った頻度、人や車の多い場所へ行った頻度などの合計です。 社会化スコアが低い犬ほど両方の恐怖が多い という関連が出ています（対犬・対人とも統計学的に有意）。なお著者らは考察で社会化を「最も強い関連因子」としていますが、結果の記述では犬種・体格と並列です。 本章では「最も強い単一因子」とは書きません。","u":"guide/socialisation/","a":"b169","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"犬種差。 対犬恐怖・対人恐怖のいずれでもシェルティは上位3犬種に入り、最も低い犬種との対比較はオッズ比（恐怖がある確率を、ない確率で割った値の群間比）8.13（対ペンブローク・ウェルシュ・コーギー）と6.40（対ウィートン・テリア）でした。シェルティは事前に「怖がりやすい側」と仮説を立てた4犬種のひとつで、仮説は支持されています。","u":"guide/socialisation/","a":"b170","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"社会化との関連が犬種ごとに違うかを調べる項目は、最終的な解析に入っていません。 つまりこの研究は、 シェルティのもともとの恐怖の多さは直接推定していますが、社会化の効果量はシェルティについて推定していません。 この区別が本章の2軸評価の根拠です。","u":"guide/socialisation/","a":"b171","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"限界が大きい研究です。 一時点の状態を調べた研究で、社会化の頻度は飼い主が後から思い出して答えたもの。 逆向きの因果を排除できません ——もともと怖がりな子犬は連れ出されにくく、記憶も結果に引きずられます。","u":"guide/socialisation/","a":"b172","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"都合の悪い結果。 同じ解析で、 生後8週より遅く「離乳」された犬のほうが対人恐怖が多い という結果が出ています（7〜8週群対8週超群、オッズ比0.80、統計学的に有意）。ただし 離乳年齢という変数全体の効果は多くの比較による偶然の差を調整する補正後には有意ではなく 、この0.80は事前に設定した群間比較のため補正対象外だったものです。解析されたのは離乳年齢であって譲渡時期ではありません。 日本の56日規制は譲渡の規制であり、この変数に対応させることはできません。","u":"guide/socialisation/","a":"b173","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"3. Salonen M, et al. Prevalence, comorbidity, and breed differences in canine anxiety in 13,700 Finnish pet dogs. Sci Rep. 2020;10:2962.","u":"guide/socialisation/","a":"b174","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"同じ調査の全体像で、 恐怖が最も多かったのはスパニッシュ・ウォーター・ドッグ、シェルティ、雑種 でした。 2と3は同じデータセットで、独立した再現ではありません。 仮説自体は先行研究（スウェーデン・オーストラリア・日本の調査）から事前に立てられたものですが、 先行研究の原著は本章では未確認です。","u":"guide/socialisation/","a":"b175","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"4. 行動が死因になること／早期社会化の位置づけ","u":"guide/socialisation/","a":"b176","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"英国VetCompass（一次診療データベース）では、3歳以下で死亡した1,574頭のうち33.7%が望ましくない行動に関連した死亡。オーストラリアでは29.7%。 「行動そのものが死因」ではなく、攻撃性・逸走・交通事故とそれに伴う安楽死を含む集計で、社会化不足の寄与割合は求められません。","u":"guide/socialisation/","a":"b177","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"世界小動物獣医師会の2024年ワクチンガイドラインは、早期社会化を「行動の発達と将来の福祉に不可欠」として強く支持し、ワクチン計画と両立できると明記しています。 同指針は基本となるワクチンの子犬期の接種を16週齢以降まで続けるとしています。米国獣医行動学会も2008年の声明で同じ立場です。 いずれも「安全性は地面の種類で判定できる」とは述べていません。 2024年指針 ／ 2008年声明","u":"guide/socialisation/","a":"b178","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"5. Stepita ME, Bain MJ, Kass PH. J Am Anim Hosp Assoc. 2013;49:95-100.","u":"guide/socialisation/","a":"b179","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"生後16週未満・獣医師による接種を1回以上受けてパピークラスに参加した子犬279頭の調査。 クラス期間中のパルボウイルス発症はなく、不参加の子犬と比べたリスク増加も認められませんでした。限界。 管理されたクラスという条件下での結果で、屋外環境一般の安全性を示したものではありません。","u":"guide/socialisation/","a":"b180","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"6. 訓練方法と苦痛（推奨2）","u":"guide/socialisation/","a":"b181","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"Vieira de Castro AC, et al. Does training method matter? Evidence for the negative impact of aversive-based methods on companion dog welfare. PLoS One. 2020;15:e0225023。 原著","u":"guide/socialisation/","a":"b182","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"家庭犬92頭を訓練施設の方法で比較した研究。罰中心群は報酬中心群よりストレス行動が多く、訓練後の唾液コルチゾール（ストレスに反応するホルモン）の上昇が大きくなりました。 ただし無作為な割り付けではなく、施設や飼い主の違いも残ります。 混合群と罰中心群の間では、ホルモン値や認知課題に有意差がありませんでした。すべての指標で方法の違いが出たわけではありません。","u":"guide/socialisation/","a":"b183","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"米国獣医行動学会の 2021年声明 も報酬を使う方法を勧めています。これらは子犬の社会化だけを検証した研究ではなく、シェルティ固有の効果量も示しません。","u":"guide/socialisation/","a":"b184","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"採用しなかったもの","u":"guide/socialisation/","a":"b185","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"「100日で100人」などの数値目標。 回数と後年の恐怖の関係を検証した研究を確認できません。","u":"guide/socialisation/","a":"b186","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"早期神経刺激（生後3〜16日に行う刺激手技）。 子犬76頭を刺激手技群・体を保持するだけの群・何もしない群で比較した研究で、群間差が出ていません（Boone G, et al. Animals. 2023;13:71）。","u":"guide/socialisation/","a":"b187","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"推奨ごとの確実性と利益・害","u":"guide/socialisation/","a":"b188","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"推奨1：良い方向に働くことの確かさは中、シェルティでどれだけ役立つかの確かさは非常に低。 早期接触を支持する実験と観察研究がありますが、日常の社会化による恐怖の減少量は主に観察研究からの推定です。犬種の怖がりやすさが分かっても、その犬種で社会化が効く大きさは分かりません。強い推奨は、早期の経験の必要性と、無理なく行う場合の害の小ささを重視した判断です。","u":"guide/socialisation/","a":"b189","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"推奨2：良い方向に働くことの確かさは中、シェルティでどれだけ役立つかの確かさは非常に低。 罰を使う方法のストレスとの関連と専門団体の指針が根拠です。子犬の社会化場面への適用には間接性があります。ごほうびを使う方法でも、怖がっている相手に近づけ続けてよいわけではありません。","u":"guide/socialisation/","a":"b190","e":1},{"c":"2-1","n":"社会化（人と犬）","s":"根拠","t":"推奨3：良い方向に働くことの確かさは低、シェルティでどれだけ役立つかの確かさは非常に低。 感染予防と経験確保の両立は専門団体の推奨と限定的な観察研究が中心です。発症がなかったことは感染リスクがゼロである証明ではなく、地域・場所・接種状況で条件が変わります。強さの根拠は研究の量ではなく、リスクに合わせて実施する場合の害の小ささと、感染予防・社会化の両方を行う必要性です。","u":"guide/socialisation/","a":"b191","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章が扱う範囲","t":"この章は、生活音や花火・雷などの大きな音、ブラシ・爪切り・ドライヤーなどの道具、耳・口・足先を触られること、動物病院での診察や保定（ほてい：診察や処置のために体を支えること）に慣らす方法を扱います。人や犬への社会化は 2-1章 です。","u":"guide/sounds-and-handling/","a":"b192","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章が扱う範囲","t":"ここでいう「慣らす」は、怖がる刺激を我慢させることではありません。怖がらない強さ・短さで経験させ、良いことと結びつけることを指します。","u":"guide/sounds-and-handling/","a":"b193","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章の推奨","t":"推奨1：音への恐怖を防ぐ","u":"guide/sounds-and-handling/","a":"b194","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章の推奨","t":"花火、雷、掃除機、チャイムなどの音は、怖がっていない段階から、音の直後に食べ物や遊びなどの良いことが起きる経験と結びつけてください。怖がる強さで音を聞かせ続けないでください。","u":"guide/sounds-and-handling/","a":"b195","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章の推奨","t":"推奨2：手入れや診察への恐怖を減らす","u":"guide/sounds-and-handling/","a":"b196","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章の推奨","t":"ブラシ、爪切り、ドライヤー、耳・口・足先への接触、診察で体を触られることは、短い練習と報酬を組み合わせ、犬が離れようとしたら止める方法で少しずつ経験させてください。","u":"guide/sounds-and-handling/","a":"b197","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"この章の推奨","t":"音への恐怖の予防と、手入れ・診察への恐怖の軽減を分けて評価します。音には予防効果を示す大規模観察研究がある一方、道具や体に触れる練習の研究は少数で、結果も一貫しないためです。 それでも両方を強く推奨します。強さの根拠は研究の量ではなく、害の小ささと必要性です。 ただし、怖がる刺激を続ける方法は害が小さいとは言えず、この推奨には含みません。","u":"guide/sounds-and-handling/","a":"b198","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"なぜこれが重要か","t":"13,715頭のフィンランド調査では、音への感受性は調べた不安に関連する特徴の中で最も多く、32%にみられました。別の1,225頭の調査では52%が花火を少なくとも部分的に怖がり、発症時期が分かった犬の45%は1歳未満で始まっていました。","u":"guide/sounds-and-handling/","a":"b199","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"なぜこれが重要か","t":"予防については、恐怖が出る前に音と良いことを結びつけていた犬ほど、後の花火による苦痛や生活への支障が少なかったという観察研究があります。子犬から始めた群の数値は最も良好でしたが、成犬になってから恐怖が出る前に始めた群との差は統計学的に確認されませんでした。「子犬期を逃したら手遅れ」ではありません。","u":"guide/sounds-and-handling/","a":"b200","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"なぜこれが重要か","t":"シェルティだけで予防効果を測った研究はありません。牧羊犬群で花火への恐怖による苦痛や生活への支障が強かった研究はありますが、群内のシェルティの値は示されていません。この章で述べる練習の効果は、他犬種を含む研究結果をシェルティにも当てはめたものです。","u":"guide/sounds-and-handling/","a":"b201","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"なぜこれが重要か","t":"道具や診察への慣れも、毎日の手入れと医療の受けやすさに関わります。ただし、犬が自分から手入れや診察に協力できるようにする練習の研究では改善が確認された指標と、改善しなかった指標の両方があります。「練習すれば必ず平気になる」とは言えません。","u":"guide/sounds-and-handling/","a":"b202","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"音は「鳴ったら良いこと」にする","u":"guide/sounds-and-handling/","a":"b203","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"チャイムが鳴ったらおやつ、掃除機を動かしたら遊ぶ、遠くで雷が鳴ったら食べ物を出す。音の直後に良いことを置きます。音源を使うなら、小さい音量から始め、普通に食べたり遊んだりできる範囲にします。","u":"guide/sounds-and-handling/","a":"b204","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"固まる、逃げる、震える、食べなくなるなどの反応が出たら強すぎます。音量を下げる、距離を取る、中止する、のいずれかにしてください。「そのうち慣れる」と続けるのは、この章の方法ではありません。","u":"guide/sounds-and-handling/","a":"b205","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"生活音を避けて無音に近い環境で育てる必要もありません。ただし、 音を多く聞かせるだけで将来の恐怖を防げるかは研究結果が一致していません。 怖がらない範囲で、良いこととの結びつけを優先します。","u":"guide/sounds-and-handling/","a":"b206","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"花火や雷が実際に鳴っているとき","u":"guide/sounds-and-handling/","a":"b207","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"犬が自分から出入りできる安全な場所を用意し、窓やカーテンを閉めます。食べられるなら、音のあとに食べ物や遊びを出してかまいません。犬が自分から寄ってきたら応じてください。「怖がっているときに構うと恐怖が強くなる」という考えは支持されていません。 一方、犬が求めていない接触や保定はしません。","u":"guide/sounds-and-handling/","a":"b208","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"強い音への恐怖では逃げ出そうとする行動が報告されています。戸や窓の開放を避け、屋外につないだままにしないなど、逃走できない環境を優先してください。","u":"guide/sounds-and-handling/","a":"b209","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"道具は一工程ずつ","u":"guide/sounds-and-handling/","a":"b210","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"ブラシを見せる→報酬、体に触れる→報酬、1回とかす→報酬、で終えて構いません。爪切りも、足先に触る、爪を持つ、道具を近づける、1本だけ切る、と分けます。ドライヤーは距離と風量を調整します。","u":"guide/sounds-and-handling/","a":"b211","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"犬が離れたらいったん止めることを基本にします。無理に押さえて全部終えるより、「次も受けられる状態」で終えることを優先します。この具体的な手順の一部は、家庭での手入れを比較する試験で確かめられたものではありません。 これは経験則です 。","u":"guide/sounds-and-handling/","a":"b212","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"病院での扱いも練習する","u":"guide/sounds-and-handling/","a":"b213","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"家で耳を見る、唇（くちびる）を持ち上げる、足を持つ、体を軽く触る、といった短い練習ができます。動物病院が対応できるなら、診察のない日に短時間だけ院内に入り、報酬をもらって帰る方法もあります。 これは経験則です 。","u":"guide/sounds-and-handling/","a":"b214","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"実際にどうするか","t":"すでに強く怖がる犬では、家庭だけで反復練習を続けず、獣医師に相談してください。","u":"guide/sounds-and-handling/","a":"b215","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"こんなときは受診を","t":"音に対して強く逃げようとする、長時間落ち着かない、日常生活に支障が出る","u":"guide/sounds-and-handling/","a":"b216","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"こんなときは受診を","t":"花火や雷のあと、翌日になっても普段の行動に戻らない","u":"guide/sounds-and-handling/","a":"b217","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"こんなときは受診を","t":"ブラシ、爪切り、耳・口・足先への接触で、毎回強く抵抗する、うなる、噛もうとする","u":"guide/sounds-and-handling/","a":"b218","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"こんなときは受診を","t":"成犬になってから、それまで平気だった音や接触を急に嫌がるようになった","u":"guide/sounds-and-handling/","a":"b219","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"こんなときは受診を","t":"最後の項目では、行動だけの問題と決めつけないでください。音への恐怖を主訴に受診した少数例の研究では、筋肉・骨・関節などの痛みがあった犬は発症が遅い傾向でした。原因を家庭で判定せず、身体面も含めて獣医師に確認してもらいます。","u":"guide/sounds-and-handling/","a":"b220","e":0},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"音への恐怖の頻度と予防","u":"guide/sounds-and-handling/","a":"b221","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Salonen M, et al. Scientific Reports. 2020;10:2962. フィンランドの13,715頭を対象とした飼い主質問票で、音への感受性は32%と、調べた不安に関連する特徴の中で最も多かった。犬種差も大きかったが、一時点で回答を集めた、自主参加者の調査であり、発症率や介入効果を示す研究ではない。シェットランド・シープドッグは411頭含まれたが、音過敏について犬種固有の介入効果は示されていない。","u":"guide/sounds-and-handling/","a":"b222","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Riemer S. PLoS One. 2019;14:e0218150. 1,225頭のオンライン調査。52.2%が花火恐怖に少なくとも部分的に該当し、発症年齢を特定できた395頭では45%が1歳未満で発症した。予防的訓練を子犬期から行った228頭、成犬期から恐怖出現前に行った82頭、予防訓練なし群の花火による苦痛や生活への支障の点数（福祉障害スコア）の中央値（値を順に並べた中央の値）は1、2、4。子犬期群と成犬・発症前群の差は有意ではなかった（両側検定〔差がどちら向きかを限定しない検定〕、Bonferroni補正〔複数の比較による偶然の差を調整〕後p=0.175）。両群は予防訓練なし群より良好だった。","u":"guide/sounds-and-handling/","a":"b223","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"限界。 犬を偶然に任せて群分けした研究ではなく、訓練した飼い主は環境や犬への関わり方そのものが違う可能性がある。研究内では牧羊犬群の福祉障害スコアがモロシアン群（マスティフなどの犬種群）・レトリーバー群より高かったが、シェルティ単独の値ではない。","u":"guide/sounds-and-handling/","a":"b224","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"van Herwijnen IR, et al. Veterinary and Animal Science. 2024;26:100402. オランダの犬3,009頭の飼い主調査で、子犬期にブリーダーによる音に慣らす経験があったと報告された犬は、成犬時に花火恐怖がない・軽い側に多かった。これも観察研究であり、因果関係を証明しない。","u":"guide/sounds-and-handling/","a":"b225","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"「音を聞かせるだけ」の研究は一貫しない","u":"guide/sounds-and-handling/","a":"b226","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Chaloupková H, et al. PLoS One. 2018;13:e0196553. ジャーマン・シェパード37頭で、生後16〜32日にラジオを1日3回20分、給餌時に聞かせた群は、7週齢の突発音課題で良好な反応を示した。","u":"guide/sounds-and-handling/","a":"b227","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Alves JC, et al. Top Companion Anim Med. 2018;33:100-104. 4犬種・交雑を含む67頭で、3週齢から段階的な聴覚刺激を加えた群に、7週齢の行動検査で利益は認められず、一部では標準社会化群の成績が良かった。対象・刺激・評価法が異なるため直接の矛盾とは言い切れないが、単純に音を聞かせることだけの予防効果は一貫していない。","u":"guide/sounds-and-handling/","a":"b228","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"花火・雷の最中の管理","u":"guide/sounds-and-handling/","a":"b229","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Riemer S. Animals. 2023;13:3664. 音への恐怖についての研究をまとめた総説。花火・雷などの最中は、犬が自発的に出入りできる安全な場所、窓・カーテン等による刺激低減、食べられる場合の食べ物・遊びを管理の中心に置く。犬が自分から接触を求める場合は無視しないことも勧めている。恐怖は感情の反応であり、食べ物や接触によって恐怖そのものが「強化される」とする考えを支持していない。","u":"guide/sounds-and-handling/","a":"b230","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"都合の悪い結果。 Riemer 2020の飼い主調査では、隠れ場所、窓を閉める、音楽などをまとめた「環境調整」成分は恐怖の悪化と関連した。ただしRiemer 2023は、恐怖が重く悪化した犬ほど飼い主が環境調整を行ったという逆向きの因果関係で説明できる可能性が高く、環境調整が無効・有害とは解釈していない。","u":"guide/sounds-and-handling/","a":"b231","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"道具・診察・体への接触","u":"guide/sounds-and-handling/","a":"b232","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Wess L, et al. Applied Animal Behaviour Science. 2022;250:105615. 47頭を一部無作為の方法で、協力ケア（犬の自発的な協力を促す練習）群と比較対象の群へ分け、40頭が完遂。訓練群は8〜12週間、平均10回のグループ訓練と家庭練習を行った。対照群も無訓練ではなく、人と犬の関わり量を揃えるため、診察や処置と無関係の別課題を家庭で練習した。心拍数や心拍変動（拍動の間隔のゆらぎ）では、受診を重ねたときの変化に群間で統計学的に明確な差がなかった。","u":"guide/sounds-and-handling/","a":"b233","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"都合の悪い結果。 第2回受診では、全診察工程を完遂した犬が訓練群で少なかった（p=0.04）。ただし中断はほぼすべて最後の肛門から体温計を入れる体温測定で起き、訓練群の飼い主が休止を求めた例もあった。著者らは、訓練で得た協力する意思を示す合図を実際の診察へ移すことが不十分だったと解釈しており、これを「訓練で診察全体が悪化した」とは読めない。","u":"guide/sounds-and-handling/","a":"b234","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Squair C, et al. Animals. 2023;13:1253; Animal Welfare. 2024;33:e43. 28頭を4回・8週間追跡し、介入群では低ストレスの扱い、犬の反応に応じた中断、報酬などを組み合わせた。4回目の診察で介入群の総エソグラムストレススコア（行動を観察してストレスの程度を点数化したもの）は対照群より低かった（両側検定p=0.030）。一方、心拍数、好中球・リンパ球比（白血球の2種類の比率）、クレアチンキナーゼ（筋肉などに含まれる酵素）には明確な群間差がなく、介入は複合的でどの要素が効いたか分からない。","u":"guide/sounds-and-handling/","a":"b235","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"都合の悪い結果と解釈上重要な所見。 介入群の診察時間は4回目に長かった。静脈採血の行動スコアでは、4回目の群間差は介入群が有意に改善したためではなく、対照群が1回目から悪化したことによって生じており、この解析は片側検定（差の向きを一方向に限定する検定）だった。著者らは、通常の扱いを繰り返した対照群が診察・採血への反応が強くなった可能性を指摘している。総エソグラムスコアの群間差も同じ機序とは断定できない。","u":"guide/sounds-and-handling/","a":"b236","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"成犬で急に始まった音恐怖","u":"guide/sounds-and-handling/","a":"b237","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"Lopes Fagundes AL, et al. Frontiers in Veterinary Science. 2018;5:17. 音への過敏を主訴とした20頭を、筋肉・骨・関節などの痛みがある10頭とない10頭で質的に比較した。痛みのある群では発症年齢が平均で約4年遅く、反応が関連する場所や状況へ広がる傾向があった。20頭の探索的研究で、統計学的に原因と結果の関係を判断できない。受診項目に入れたのは、遅い発症では身体面も確認する理由がある、という限定した使い方である。","u":"guide/sounds-and-handling/","a":"b238","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"確実性の評価","u":"guide/sounds-and-handling/","a":"b239","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"推奨1（音）・良い方向に働くことの確かさ：中。 大規模な観察研究が同じ方向を示し、恐怖成立後の研究・レビューとも整合する。ただし予防について、偶然に任せて群分けする比較試験はない。","u":"guide/sounds-and-handling/","a":"b240","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"推奨2（手入れ・診察）・良い方向に働くことの確かさ：低。 小規模介入研究で行動面の改善はあるが、生理指標や診察完遂では一貫せず、介入も複合的である。","u":"guide/sounds-and-handling/","a":"b241","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"両推奨・シェルティでどれだけ役立つかの確かさ：非常に低。 シェルティ単独で介入効果を測った研究は確認できず、効果の大きさは他犬種を含む研究から当てはめて考えている。","u":"guide/sounds-and-handling/","a":"b242","e":1},{"c":"2-2","n":"音・道具・体に触れられることに慣らす","s":"根拠","t":"利益と害のバランス。 怖がらない範囲で短く行うなら害は小さく、音、被毛管理、爪、口の中、診察はいずれも生涯避けにくい。一方、逃げられない状態で刺激を続ければ恐怖を強めうるため、「慣らす」と「我慢させる」を分けることが中心となる。","u":"guide/sounds-and-handling/","a":"b243","e":1},{"c":"3","n":"成長期の運動と関節","s":"この章が扱う範囲","t":"この章では、子犬から若犬までの床、階段、自由運動、ジャンプ練習を扱います。成長期の運動を一律に制限する章ではありません。跛行（はこう：足を引きずったり、かばったりする歩き方）が出たあとの判断は 10章 、適正体重は 4-1章 で扱います。","u":"guide/growth-and-exercise/","a":"b244","e":0},{"c":"3","n":"成長期の運動と関節","s":"この章の推奨","t":"推奨1：日常の環境と運動","u":"guide/growth-and-exercise/","a":"b245","e":0},{"c":"3","n":"成長期の運動と関節","s":"この章の推奨","t":"生後3か月ごろまでは階段を繰り返し上り下りさせず、安全に自由に動ける時間を作ってください。走る・曲がる・着地する場所では、大きく滑る床をできる範囲で減らしてください。","u":"guide/growth-and-exercise/","a":"b246","e":0},{"c":"3","n":"成長期の運動と関節","s":"この章の推奨","t":"推奨2：高い跳躍や競技練習","u":"guide/growth-and-exercise/","a":"b247","e":0},{"c":"3","n":"成長期の運動と関節","s":"この章の推奨","t":"高い場所からの飛び降りや、肘の高さを繰り返し跳ぶ練習を成長期から急いで始めないでください。低い課題から、回数・高さ・速さを一度に増やさず、段階的に進めてください。","u":"guide/growth-and-exercise/","a":"b248","e":0},{"c":"3","n":"成長期の運動と関節","s":"この章の推奨","t":"推奨を分けたのは、日常生活については前向き追跡研究がある一方、競技練習は飼い主への聞き取りを用いた回顧的研究が中心で、根拠の性質が異なるためです。いずれもシェルティだけで予防効果を測った研究ではなく、他犬種からの外挿です。","u":"guide/growth-and-exercise/","a":"b249","e":0},{"c":"3","n":"成長期の運動と関節","s":"なぜこれが重要か","t":"骨や関節の病気は、遺伝だけでも、飼い方だけでも決まりません。股関節形成不全は遺伝的素因に成長期の環境などが重なって表れます。運動をすべて止めれば防げるわけではなく、むしろ子犬には筋力、身体の使い方、探索行動を育てる機会が必要です。","u":"guide/growth-and-exercise/","a":"b250","e":0},{"c":"3","n":"成長期の運動と関節","s":"なぜこれが重要か","t":"大型4犬種501頭を出生時から追跡した研究では、生後3か月までの階段利用は画像上の股関節形成不全が多い側に、屋外での自由運動は少ない側に関連しました。ただし対象はニューファンドランド、ラブラドール・レトリーバー、レオンベルガー、アイリッシュ・ウルフハウンドで、シェルティに同じ大きさの効果があるとは分かりません。","u":"guide/growth-and-exercise/","a":"b251","e":0},{"c":"3","n":"成長期の運動と関節","s":"なぜこれが重要か","t":"床については研究結果が一致しません。滑る床で育ったボクサーは股関節形成不全による症状が多かったという研究と、生後0〜3週に使った産箱の素材と画像上の股関節形成不全との関連を調べた研究があります。一方、前記501頭の研究では屋内・屋外の床面との関連が認められませんでした。家庭で成長期を通じて床を変える効果を直接確かめた研究でもありません。そのため床対策は、早期の飼育環境の所見と転倒を減らす実務上の判断を組み合わせた提案です。","u":"guide/growth-and-exercise/","a":"b252","e":0},{"c":"3","n":"成長期の運動と関節","s":"なぜこれが重要か","t":"競技犬では、ジャンプ練習を始めた月齢と後のけがとの関連が調べられていますが、結果は単純ではありません。早く始めた群が常に最も危険だったわけではなく、課題やけがの定義によって関係が変わりました。10か月、12か月、16か月など、特定の月齢を安全の境界とすることはできません。","u":"guide/growth-and-exercise/","a":"b253","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"階段","u":"guide/growth-and-exercise/","a":"b254","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"生後3か月ごろまでは、生活のたびに階段を往復する環境を避けます。柵で区切る、抱いて移動する、生活場所を同じ階にまとめる方法があります。一段を偶然上っただけで病気になる、という意味ではありません。","u":"guide/growth-and-exercise/","a":"b255","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"この「3か月」は大型4犬種の研究で用いられた時期で、生物学的に確定した安全境界ではありません。シェルティで制限が最も役立つ時期は確認されていません。","u":"guide/growth-and-exercise/","a":"b256","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"それ以降も、滑る階段を勢いよく反復する遊びにはしません。階段を使う必要があるなら、滑り止めと照明を整え、落ち着いて移動させます。","u":"guide/growth-and-exercise/","a":"b257","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"全面を高価な床材へ替える必要はありません。よく走る廊下、曲がる場所、ソファや段差から着地する場所に、ずれにくいマットを敷きます。爪を適切な長さに保ち、足裏の毛で滑るなら手入れします。","u":"guide/growth-and-exercise/","a":"b258","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"床対策を「成長期なら必ず股関節形成不全を防げる」と考えないでください。研究は主に出生後早期の環境を扱っており、家庭で成長期を通じて行う対策には経験則が含まれます。","u":"guide/growth-and-exercise/","a":"b259","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"運動は「分数」より「内容」","u":"guide/growth-and-exercise/","a":"b260","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"散歩を月齢×何分に制限するなど、すべての子犬に通用する時間式を裏づける根拠はありません。平らな場所だけを一定速度で歩かせるより、安全な範囲で匂いを嗅ぎ、止まり、方向を変え、自分のペースで動ける時間を作ります。疲れて座る、動きが乱れる、遅れるなら終了します。","u":"guide/growth-and-exercise/","a":"b261","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"囲われた自宅の庭や、ロングリードを安全に使える管理された場所が候補です。ワクチン接種が完了するまでは、不特定多数の犬が出入りするドッグランなどを使わず、感染リスクを管理できる場所に限ります。","u":"guide/growth-and-exercise/","a":"b262","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"アジリティをする場合","u":"guide/growth-and-exercise/","a":"b263","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"若いうちは、呼び戻し、左右の動き、低いバーの間を通る、平地でバランスを取るなど、衝撃の小さい基礎を中心にします。 これは経験則です が、骨端線（こつたんせん：骨が長く成長する部分）が閉じるころまでは、肘の高さの反復ジャンプを練習の主軸にしないのが無難です。骨端線が閉じる時期には個体差があり、特定の月齢を安全境界とする根拠はありません。","u":"guide/growth-and-exercise/","a":"b264","e":0},{"c":"3","n":"成長期の運動と関節","s":"実際にどうするか","t":"高さを上げるときは、回数や速度を同時に増やしません。疲労した状態で同じ失敗を繰り返すなら、その日は終えます。","u":"guide/growth-and-exercise/","a":"b265","e":0},{"c":"3","n":"成長期の運動と関節","s":"こんなときは受診を","t":"急に立てない、後肢が動かない、交通事故や転落のあと： 今すぐ（夜間・休日でも）連絡","u":"guide/growth-and-exercise/","a":"b266","e":0},{"c":"3","n":"成長期の運動と関節","s":"こんなときは受診を","t":"足を着かない、強く痛がる、腫れや変形がある： その日のうちに連絡","u":"guide/growth-and-exercise/","a":"b267","e":0},{"c":"3","n":"成長期の運動と関節","s":"こんなときは受診を","t":"跛行を繰り返す、運動を嫌がる、座り方や歩き方が以前と違う： 数日以内を目安に相談","u":"guide/growth-and-exercise/","a":"b268","e":0},{"c":"3","n":"成長期の運動と関節","s":"こんなときは受診を","t":"前足が外へ曲がって見える、左右差が大きくなる： 早めに相談","u":"guide/growth-and-exercise/","a":"b269","e":0},{"c":"3","n":"成長期の運動と関節","s":"こんなときは受診を","t":"外傷や立てない場合は、動画撮影より連絡を優先してください。自己判断で鎮痛薬を与えたり、痛む関節を繰り返し曲げ伸ばししたりしないでください。","u":"guide/growth-and-exercise/","a":"b270","e":0},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"1. 階段、自由運動、床と股関節形成不全","u":"guide/growth-and-exercise/","a":"b271","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Krontveit RI, Nødtvedt A, Sævik BK, Ropstad E, Trangerud C. Am J Vet Res. 2012;73:838-846. doi:10.2460/ajvr.73.6.838.","u":"guide/growth-and-exercise/","a":"b272","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"大型4犬種501頭・103腹を出生時から公式の股関節撮影まで追跡した前向きコホート。生後0〜3か月の階段利用は画像上の股関節形成不全が多い側、同時期の屋外での自由運動は少ない側に関連した。無作為化試験ではなく、質問票による測定と残余交絡がある。屋内・屋外の床面に関する変数は関連しなかったと報告されており、階段や自由運動の所見を床材へそのまま広げることはできない。","u":"guide/growth-and-exercise/","a":"b273","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"van Hagen MAE, Ducro BJ, van den Broek J, Knol BW. Am J Vet Res. 2005;66:307-312.","u":"guide/growth-and-exercise/","a":"b274","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"ボクサーの出生コホートで、滑る材料の床で飼育された犬は、滑らない床の犬より股関節形成不全による後肢の跛行が1.6倍多かった。評価対象は画像上の形成不全そのものではなく臨床症状で、犬種もシェルティではない。床材への曝露は主に母犬と過ごす早期環境であり、家庭で成長期を通じた床対策の効果を測った研究ではない。","u":"guide/growth-and-exercise/","a":"b275","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Feng LC, et al. Animals. 2025;15:152.","u":"guide/growth-and-exercise/","a":"b276","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"盲導犬育成プログラムのラブラドール・レトリーバー、ゴールデン・レトリーバーと両犬種の交雑種5,649頭を対象に、出生後0〜3週に産箱へフリースを敷いたかどうかと、後の画像上の股関節形成不全との関連を調べた後ろ向き研究。フリースの有無を床の「滑りやすさ」そのものとして測定した研究ではない。早期環境の所見であり、譲渡後の家庭内床材へ直接当てはめるには限界がある。Krontveit 2012の床面に関する陰性結果と合わせると、床材について研究の結論は一致していない。","u":"guide/growth-and-exercise/","a":"b277","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Krontveit RI, et al. Prev Vet Med. 2010;97:252-263. doi:10.1016/j.prevetmed.2010.09.015.","u":"guide/growth-and-exercise/","a":"b278","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"同じ大型4犬種の前向き研究で、出生時体重や成長関連指標を検討した。成長率と股関節形成不全に明確な関連はなく、3か月時の体重が重いほどオッズがわずかに低いという、単純な「ゆっくり成長させるほどよい」と逆向きの所見もあった。これは子犬を太らせる利益を示すものではなく、体重管理は 4-1章 の推奨に従う。","u":"guide/growth-and-exercise/","a":"b279","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"2. アジリティとジャンプ開始時期","u":"guide/growth-and-exercise/","a":"b280","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Pechette Markley A, et al. Risk Factors for Injury in Border Collies Competing in Agility. Animals. 2024;14:2081.","u":"guide/growth-and-exercise/","a":"b281","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"競技中のボーダー・コリーを対象に、飼い主が過去の練習と傷害を回答した回顧的調査。肘の高さのジャンプを始めた時期と全傷害・長期傷害には関連があったが、危険度は月齢に沿って単調には変化しなかった。バックサイドジャンプでは13か月未満開始群が最も低い側で、推奨と逆向きの所見もあった。記憶の誤差、因果の逆転、練習量などの交絡が残るため、特定月齢を安全境界にはできない。","u":"guide/growth-and-exercise/","a":"b282","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"3. シェルティの関節検査データ","u":"guide/growth-and-exercise/","a":"b283","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Engdahl K, et al. Vet Rec. 2026;198:e560-e573. doi:10.1002/vetr.70224.","u":"guide/growth-and-exercise/","a":"b284","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"スウェーデン・ケネルクラブで2007〜2016年に検査された114,568頭・72犬種の股関節、78,504頭・46犬種の肘関節を集計した。シェルティでは股関節検査651頭中102頭（15.7%）、肘関節検査433頭中24頭（5.5%）が正常以外の判定だった。これは任意の検査を受けた犬の画像判定分布で、臨床疾患の発生率でも、日本のシェルティの発症率でもない。","u":"guide/growth-and-exercise/","a":"b285","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"4. 前肢の変形","u":"guide/growth-and-exercise/","a":"b286","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"Christopher S. Front Vet Sci. 2022;9:971527. doi:10.3389/fvets.2022.971527.","u":"guide/growth-and-exercise/","a":"b287","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"成長期の前肢変形を治療した23頭31肢の症例集積。対象は4〜10.8か月齢で、全例に目で分かる手根外反（手首から先が外側へ向く変形）と程度の異なる前肢跛行があった。対照群のない紹介症例であり、どの程度の外見なら自然に治るかを決める研究ではない。受診の目安に用いたのは、成長期には評価と治療時期が問題になる病態があるためである。","u":"guide/growth-and-exercise/","a":"b288","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"確実性と利益・害の評価","u":"guide/growth-and-exercise/","a":"b289","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"推奨1の良い方向に働くことの確かさは、階段と自由運動については前向きコホートが同じ時間窓で比較しているため中、床材は研究間で不一致かつ曝露時期の外挿があるため低とした。推奨2は単一の回顧的調査が中心で、結果も非単調なため低とした。シェルティ単独で介入効果を測った研究はなく、両推奨のシェルティでどれだけ役立つかの確かさは非常に低い。","u":"guide/growth-and-exercise/","a":"b290","e":1},{"c":"3","n":"成長期の運動と関節","s":"根拠","t":"階段の反復、高衝撃の反復、極端に滑る場所を避ける負担は比較的小さい。一方、過度な運動制限は正常な身体活動や社会化の機会を奪う。利益が確実とはいえず、制限を強めすぎる害もあるため、いずれも「推奨する」ではなく「提案する」とした。","u":"guide/growth-and-exercise/","a":"b291","e":1},{"c":"4-1","n":"適正体重の維持","s":"この章が扱う範囲","t":"この章は、健康なシェルティを太らせず、痩せさせすぎずに育てるための見方と記録方法を扱います。病気の犬、妊娠・授乳中の犬、成長中の子犬に対する減量法は扱いません。これらの犬の給餌量は、自己判断で大きく減らさず、獣医師に相談してください。","u":"guide/healthy-weight/","a":"b292","e":0},{"c":"4-1","n":"適正体重の維持","s":"この章の推奨","t":"推奨1：寿命と健康全般","u":"guide/healthy-weight/","a":"b293","e":0},{"c":"4-1","n":"適正体重の維持","s":"この章の推奨","t":"BCS（ボディコンディションスコア：犬の脂肪のつき方を1〜9で評価する指標）は4〜5を目標にし、6に入ったら給餌量とおやつを見直してください。","u":"guide/healthy-weight/","a":"b294","e":0},{"c":"4-1","n":"適正体重の維持","s":"この章の推奨","t":"推奨2：関節の健康","u":"guide/healthy-weight/","a":"b295","e":0},{"c":"4-1","n":"適正体重の維持","s":"この章の推奨","t":"成長期から過体重を避けてください。ただし、適正体重を保てばすべての関節病を予防できる、とは考えないでください。","u":"guide/healthy-weight/","a":"b296","e":0},{"c":"4-1","n":"適正体重の維持","s":"この章の推奨","t":"寿命と関節では、研究結果のそろい方が違うため推奨を分けました。どちらも強い推奨とした理由は、シェルティでどれだけ役立つかが分からなくても、適正体重を保つ害は小さく、過体重を避ける必要性が高いからです。強さの根拠は、シェルティの研究量ではなく、利益の一貫した方向と害の小ささです。","u":"guide/healthy-weight/","a":"b297","e":0},{"c":"4-1","n":"適正体重の維持","s":"なぜこれが重要か","t":"中年期に過体重だった飼い犬約5万頭の研究では、調べた12犬種すべてで、標準体型の犬より寿命が短い傾向がありました。また、ラブラドールレトリーバー48頭を生涯追跡した研究では、食べる量を抑えた群は、もう一方の群より体型が細く保たれ、生存期間の中央値が1.8年長くなりました。","u":"guide/healthy-weight/","a":"b298","e":0},{"c":"4-1","n":"適正体重の維持","s":"なぜこれが重要か","t":"関節については、同じ48頭で股関節の変形性関節症（関節の軟骨や骨が徐々に変化する病気）がX線で確認される時期が遅れました。一方、肘では発生頻度の群間差が確認されませんでした。体重管理は重要ですが、関節病をすべて防ぐ方法ではありません。","u":"guide/healthy-weight/","a":"b299","e":0},{"c":"4-1","n":"適正体重の維持","s":"なぜこれが重要か","t":"これらはシェルティの研究ではありません。 他犬種からの外挿ですが、過体重による関節への負担や脂肪組織の働きは犬種をまたいで共通すると考えられるため、方向性はシェルティにも当てはまると判断しました。ただし、寿命が何年延びるか、関節病が何割減るかは分かりません。","u":"guide/healthy-weight/","a":"b300","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"1．毛ではなく、手で確かめる","u":"guide/healthy-weight/","a":"b301","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"シェルティは被毛が厚いため、見た目だけでは判断しにくい犬種です。立った状態で次の3点を確認してください。","u":"guide/healthy-weight/","a":"b302","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"肋骨 ：薄い脂肪の上から、軽く触れて1本ずつ分かる","u":"guide/healthy-weight/","a":"b303","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"上から見た腰 ：肋骨の後ろにくびれがある","u":"guide/healthy-weight/","a":"b304","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"横から見た腹 ：胸から後ろへ向かって引き上がっている","u":"guide/healthy-weight/","a":"b305","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"BCS 4〜5が目標です。BCS 6は一般的な換算で理想体重より約10％多い状態です。ただし、BCSには評価者によるずれがあり、隣り合う点数の境界は明確ではありません。1回の数字だけでなく、同じ人が同じ方法で繰り返し評価してください。","u":"guide/healthy-weight/","a":"b306","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"2．筋肉を別に見る","u":"guide/healthy-weight/","a":"b307","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"BCSは脂肪の指標で、筋肉の量は分かりません。MCS（マッスルコンディションスコア：筋肉のつき方を触って評価する指標）も別に見ます。背骨、肩甲骨、頭、骨盤の骨の周囲を触り、筋肉が薄くなっていないか確認してください。","u":"guide/healthy-weight/","a":"b308","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"体重が変わらなくても、筋肉が減って脂肪が増えることがあります。特に高齢犬では、体重だけを見ているとこの変化を見逃します。","u":"guide/healthy-weight/","a":"b309","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"3．同じ条件で記録する","u":"guide/healthy-weight/","a":"b310","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"健康な成犬は月1回を目安に、できるだけ同じ時間帯、食前・食後など同じ条件で体重を測り、BCSとMCSも記録します。成長期は診察時に成長曲線と体型を確認してください。","u":"guide/healthy-weight/","a":"b311","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"同じシェルティでも骨格の大きさは異なります。他の犬や犬種平均の体重を、その犬の目標体重にしないでください。目標は、個体ごとのBCS、筋肉、体重の推移から決めます。","u":"guide/healthy-weight/","a":"b312","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"4．食べたものを全部数える","u":"guide/healthy-weight/","a":"b313","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"袋に書かれた給餌量は出発点です。主食だけでなく、おやつ、人の食べ物、歯磨き用ガム、投薬に使う食べ物も含めて1日の総量を確認します。おやつなど主食以外は、1日に摂るエネルギーの10％以内を目安にします。トレーニングでフードを使う日は、その分を食事から取り分けると管理しやすくなります。","u":"guide/healthy-weight/","a":"b314","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"BCSが6になったら、まず計量カップではなくキッチンスケールで主食を量り、家族全員が与えたものを記録します。減らしても改善しない場合や、すでに明らかな肥満がある場合は、必要な栄養まで不足させないよう動物病院で減量計画を立ててください。","u":"guide/healthy-weight/","a":"b315","e":0},{"c":"4-1","n":"適正体重の維持","s":"実際にどうするか","t":"ショーや競技のために体型を調整する場合も、BCS 4〜5の範囲にとどめます。 これは経験則です 。 研究で決められたショー犬・競技犬専用の基準ではありません。被毛の見栄えのためにBCS 6を目標にしたり、速さのためにBCS 3以下を目指したりすることは勧めません。","u":"guide/healthy-weight/","a":"b316","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"食べる量を変えていないのに、体重が急に増えた、または減った","u":"guide/healthy-weight/","a":"b317","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"食事を量って調整しても体重が減らない","u":"guide/healthy-weight/","a":"b318","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"筋肉が目に見えて落ちてきた","u":"guide/healthy-weight/","a":"b319","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"水を飲む量や尿の量が増えた","u":"guide/healthy-weight/","a":"b320","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"元気がない、疲れやすい、寒がる、左右対称の脱毛などを伴う","u":"guide/healthy-weight/","a":"b321","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"子犬、妊娠・授乳中、持病のある犬の体重を調整したい","u":"guide/healthy-weight/","a":"b322","e":0},{"c":"4-1","n":"適正体重の維持","s":"こんなときは受診を","t":"体重変化だけで病名は決められません。食事の記録と体重の推移を持参し、獣医師に相談してください。","u":"guide/healthy-weight/","a":"b323","e":0},{"c":"4-1","n":"適正体重の維持","s":"「25％減らす研究」の読み方","t":"ラブラドールの研究では、一方の犬に、同腹の相手が前日に食べた量の75％を与えました。これは、どの犬にも現在の食事を一律25％減らすよう勧める研究ではありません。研究後半には比較相手も定量給餌となり、平均BCSは比較群6.7、制限群4.6でした。この章の目標は、強い食事制限ではなく、BCS 4〜5と筋肉を保つことです。","u":"guide/healthy-weight/","a":"b324","e":0},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"1．寿命","u":"guide/healthy-weight/","a":"b325","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Kealy RD, et al. Effects of diet restriction on life span and age-related changes in dogs. J Am Vet Med Assoc. 2002;220:1315-1320. doi:10.2460/javma.2002.220.1315.","u":"guide/healthy-weight/","a":"b326","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"ラブラドールレトリーバー48頭を、同腹・同性・近い体重で24組に分け、各組の一方を無作為に比較群、もう一方を制限群に割り付け、生涯追跡した。制限群には、比較相手が前日に食べた量の75％を給餌した。3.25歳以降は比較群も定量給餌となった。6〜12歳の平均BCSは比較群6.7、制限群4.6。生存期間中央値は11.2年対13.0年で、制限群が1.8年長かった。単一施設、単一犬種、48頭の研究であり、給餌量そのものと体型の効果は分離できない。資金提供者はペットフード企業で、著者にも同社関係者が含まれる。","u":"guide/healthy-weight/","a":"b327","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Salt C, et al. Association between life span and body condition in neutered client-owned dogs. J Vet Intern Med. 2019;33:89-99. doi:10.1111/jvim.15367.","u":"guide/healthy-weight/","a":"b328","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"北米約900施設の診療記録から、6.5〜8.5歳時点で標準体型または過体重と判定された、避妊・去勢済みの飼い犬50,787頭を解析した後ろ向き研究。12犬種すべてで過体重群の死亡ハザードが高く、ハザード比は1.35〜2.86。推定生存期間中央値の差は犬種により約5か月〜2年6か月だった。シェルティは含まれない。体型は3区分の診療記録を用いており、BCS 6という特定の値の影響を示す研究ではない。観察研究なので、未測定の病気、生活習慣、診療行動などの交絡を完全には除けない。","u":"guide/healthy-weight/","a":"b329","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"この2研究は設計と対象が異なるが、過体重を避ける方向で一致する。したがって良い方向に働くことの確かさは中〜高とした。一方、シェルティの直接データがなく、犬種間で観察された差も大きいため、シェルティでどれだけ役立つかの確かさは低とした。「1.8年長くなる」という数値をシェルティへ当てはめることはできない。","u":"guide/healthy-weight/","a":"b330","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"2．関節","u":"guide/healthy-weight/","a":"b331","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Smith GK, et al. Lifelong diet restriction and radiographic evidence of osteoarthritis of the hip joint in dogs. J Am Vet Med Assoc. 2006;229:690-693. doi:10.2460/javma.229.5.690.","u":"guide/healthy-weight/","a":"b332","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Kealy研究と同じ48頭を追跡した解析。股関節の変形性関節症がX線で初めて確認された年齢の中央値は比較群6歳、制限群12歳。生涯の累積発生は83％対50％だった。過体重を避けることが股関節の変化を遅らせる可能性を示すが、臨床症状ではなくX線所見であり、シェルティへの外挿である。","u":"guide/healthy-weight/","a":"b333","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Huck JL, et al. A longitudinal study of the influence of lifetime food restriction on development of osteoarthritis in the canine elbow. Vet Surg. 2009;38:192-198. doi:10.1111/j.1532-950X.2008.00487.x.","u":"guide/healthy-weight/","a":"b334","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"同じ犬群の肘を評価した研究。X線上の変形性関節症の発生頻度は6歳、8歳、死亡時のいずれも群間差がなく、肉眼・組織所見にも差がなかった。X線上の重症度に差があったのは6歳時のみ。死亡時の組織所見は制限群のほうが数値上多かったが、制限群が長生きした影響が考えられ、有意差はなかった。体重管理の効果を「すべての関節病の予防」へ広げられない重要な結果である。","u":"guide/healthy-weight/","a":"b335","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"股関節では明確な差がみられた一方、肘では主要な群間差が確認されていないため、良い方向に働くことの確かさは中とした。研究は小規模なラブラドール集団だけで、シェルティ固有の効果量は低とした。","u":"guide/healthy-weight/","a":"b336","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"3．BCSとMCS","u":"guide/healthy-weight/","a":"b337","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"Cline MG, et al. 2021 AAHA Nutrition and Weight Management Guidelines for Dogs and Cats. J Am Anim Hosp Assoc. 2021;57:153-178. doi:10.5326/JAAHA-MS-7232.","u":"guide/healthy-weight/","a":"b338","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"米国動物病院協会（AAHA）のガイドラインは、診察ごとに食事歴、活動性、体重、BCS、MCSを評価するよう勧めている。9段階BCSでは4〜5を理想範囲とし、6を理想体重より約10％多い目安としている。MCSは背骨、肩甲骨、頭蓋骨、骨盤周囲を視診・触診し、正常、軽度、中等度、重度の筋肉減少で評価する。BCSとMCSは別の指標で、過体重でも筋肉減少は起こりうる。","u":"guide/healthy-weight/","a":"b339","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"BCSは体脂肪率と相関するが半定量的な尺度であり、犬種、被毛、評価者による違いがある。4〜5は広く採用された臨床上の目標だが、シェルティで寿命や疾患から逆算された境界ではない。このため、単回の点数より、同じ人が同じ方法で測った変化を重視した。","u":"guide/healthy-weight/","a":"b340","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"4．利益と害のバランス","u":"guide/healthy-weight/","a":"b341","e":1},{"c":"4-1","n":"適正体重の維持","s":"根拠","t":"適正体重を保ち、記録すること自体の害は小さい。一方、過度な食事制限は、必要な栄養の不足、筋肉減少、子犬の成長への悪影響を起こしうる。Kealy研究の「75％」を家庭で一律に用いることはできない。子犬、妊娠・授乳中、病気の犬、すでに肥満の犬では、獣医師と個別に給餌計画を立てる必要がある。","u":"guide/healthy-weight/","a":"b342","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"この章が扱う範囲","t":"この章は、成犬で 4-1章 の見直し後もBCS（ボディコンディションスコア。犬の体型を1〜9で評価し、数字が大きいほど脂肪が多い指標）6が続く場合、またはBCS 7以上になった場合に、安全に体重を戻す方法を扱います。成長期、妊娠・授乳中、病気による体重変化は対象外です。","u":"guide/weight-management/","a":"b343","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章が扱う範囲","t":"この章の主要な減量研究はシェルティ単独の研究ではありません。 食事制限、関節症状、運動の効果量は他犬種からの外挿です。一方、減量を始める前に病気を考える理由については、シェルティ自身の甲状腺機能低下症の疫学データがあります。","u":"guide/weight-management/","a":"b344","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨1：減量を始める前に受診する","u":"guide/weight-management/","a":"b345","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"この章の減量を始める前に一度、動物病院で診察を受け、体重・BCS・MCS（マッスルコンディションスコア。筋肉のつき方を触って評価する指標）と、食事・運動の計画を確認してください。","u":"guide/weight-management/","a":"b346","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"この受診自体を比較した研究はありません。強さの根拠は研究の量ではなく、害の小ささと必要性です。シェルティは英国の一次診療データで、甲状腺機能低下症と診断されやすさが雑種より高かった犬種です。食事量を変えていないのに太った、元気がない、寒がる、脱毛や皮膚の変化があるときは、食事を減らす前に受診してください。","u":"guide/weight-management/","a":"b347","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨2：計画的に体重を落とす","u":"guide/weight-management/","a":"b348","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"BCS 4〜5を目標に給餌量を調整し、体重・BCS・MCSを記録してください。","u":"guide/weight-management/","a":"b349","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"強さの根拠は研究の量だけではなく、過体重を放置しない必要性と、監視しながら行う減量の害が小さいことです。","u":"guide/weight-management/","a":"b350","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨3：最初の区切りを作る","u":"guide/weight-management/","a":"b351","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"肥満が強い犬では、最初から理想体重だけをゴールにせず、開始時体重の約6〜9%減を最初の区切りにすることを提案します。","u":"guide/weight-management/","a":"b352","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"6〜9%は一般犬の「治療の効き目が現れる境目」ではありません。肥満して変形性関節症（関節の軟骨などが傷み、痛みや動きにくさが出る病気。以下OA）のある犬14頭で、この範囲の減量から跛行（はこう：足を引きずったり、かばったりする歩き方）の改善が観察されたことを、中間目標に使っています。","u":"guide/weight-management/","a":"b353","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨4：大きく制限するときは食事の質を落とさない","u":"guide/weight-management/","a":"b354","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"大きなカロリー制限が必要なときは、普段の維持食を単純に大幅減量するより、減量用に栄養設計された食事を使うことを提案します。","u":"guide/weight-management/","a":"b355","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨5：筋肉を守る","u":"guide/weight-management/","a":"b356","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"関節や心肺の状態に問題がなければ、食事制限だけでなく無理のない運動を組み合わせることを提案します。","u":"guide/weight-management/","a":"b357","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"この章の推奨","t":"推奨を分けたのは、体重、関節症状、栄養、筋肉量が別の結果であり、一つの研究で全部が確かめられていないからです。","u":"guide/weight-management/","a":"b358","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"なぜこれが重要か","t":"減量は、理想体重まで達しないと意味がない介入ではありません。OAのある肥満犬14頭では、人が見て判定した跛行は体重6.10%減から改善しました。前肢に跛行があった7頭では、床にかかる力の測定も8.85%減から改善を支持しましたが、後肢に跛行があった7頭では有意な変化がありませんでした。","u":"guide/weight-management/","a":"b359","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"なぜこれが重要か","t":"一方、 すでに太った犬を減量させると寿命が延びる、と直接示した研究はありません。 第4-1章 の寿命データは「太らせないこと」の根拠であり、すでに太った犬を痩せさせた試験ではありません。この章で期待する利益は、主に体重そのものの改善、活動性、関節症状、生活の質です。","u":"guide/weight-management/","a":"b360","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"1. 最初に記録する","u":"guide/weight-management/","a":"b361","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"開始時の体重、BCS、MCSと、1日に口へ入るものを記録します。主食、おやつ、歯みがき用食品、投薬に使う食品を含めます。","u":"guide/weight-management/","a":"b362","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"2. 速度は「安心材料」ではなく「見直しの指標」にする","u":"guide/weight-management/","a":"b363","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"米国動物病院協会（AAHA）の2014年ガイドラインは、犬で週1〜2%を目標として示しています。しかし専門クリニック143頭の実績では、全体の中央値は0.6%/週でした。同じ研究で、目標体重まで完遂した犬は0.7%/週、途中で中断した犬は0.4%/週で、速い減量速度は完遂と独立して関連しました。","u":"guide/weight-management/","a":"b364","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"これは「速いほどよい」という意味ではありません。観察研究なので、速さが成功の原因か、計画を続けられた結果かは決められません。予定より遅い状態が続くときは、食事量・間食・活動量・病気の影響を獣医師と見直してください。","u":"guide/weight-management/","a":"b365","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"3. 普段のフードを減らしすぎない","u":"guide/weight-management/","a":"b366","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"維持用フードを大きく減らすと、カロリーだけでなく必須栄養素も減ります。理論計算では複数の栄養素が推奨量を下回りうることが示されています。大きな制限が必要なら、食事の種類と量を獣医師と決めます。","u":"guide/weight-management/","a":"b367","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"4. おやつも計画に入れる","u":"guide/weight-management/","a":"b368","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"1日分の主食から一部を取り分け、トレーニング報酬に回す方法は管理しやすいです。 これは経験則です 。 家族全員で給餌量を共有してください。","u":"guide/weight-management/","a":"b369","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"5. 運動は「多ければよい」ではない","u":"guide/weight-management/","a":"b370","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"小規模な研究では、管理された運動を加えた群は食事のみ群より、除脂肪量（体重から脂肪の重さを除いた量で、主に筋肉など）が保たれました。ただし犬を無作為に振り分けた研究ではありません。また、体重減少率そのものには群間差がありませんでした。痛みがある犬に運動を上乗せしないでください。","u":"guide/weight-management/","a":"b371","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"6. 到達後も測る","u":"guide/weight-management/","a":"b372","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"実際にどうするか","t":"減量成功後33頭の追跡では、48%が5%以上体重を戻しました。目標到達は終了ではなく、維持期への移行です。給餌量と測定間隔をもう一度決めます。","u":"guide/weight-management/","a":"b373","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"この章の減量を始める前","u":"guide/weight-management/","a":"b374","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"食事量を変えていないのに太ったうえ、元気低下、寒がる、脱毛や皮膚の変化がある","u":"guide/weight-management/","a":"b375","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"体重が予想外に急に減る、MCSが下がる、元気や食欲が変わる","u":"guide/weight-management/","a":"b376","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"計画どおり続けても体重が動かず、さらに食事を減らしたくなった","u":"guide/weight-management/","a":"b377","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"跛行や運動を嫌がる様子がある","u":"guide/weight-management/","a":"b378","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"こんなときは受診を","t":"呼吸が苦しそう、ぐったりして立てない場合は、減量の相談を待たず、今すぐ（夜間・休日でも）動物病院に連絡してください。","u":"guide/weight-management/","a":"b379","e":0},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"0. 開始前の受診","u":"guide/weight-management/","a":"b380","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"German AJ, Titcomb JM, Holden SL, et al. Cohort Study of the Success of Controlled Weight Loss Programs for Obese Dogs. J Vet Intern Med. 2015;29:1547-1555. doi:10.1111/jvim.13629.","u":"guide/weight-management/","a":"b381","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"開始前の受診そのものを比較した試験は確認できません。German 2015では、減量開始前に全血球計算、生化学、尿検査を行い、平衡透析法による遊離サイロキシン（遊離T4）で甲状腺状態も確認していました。4頭は甲状腺機能低下症を併存し、レボチロキシン治療を受けていました。したがって、この研究の減量成績は「原因評価をせず飼い主判断だけで食事を減らした犬」の成績ではありません。","u":"guide/weight-management/","a":"b382","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"O’Neill DG, Khoo JSP, Brodbelt DC, et al. Frequency, breed predispositions and other demographic risk factors for diagnosis of hypothyroidism in dogs under primary veterinary care in the UK. Canine Med Genet. 2022;9:11. doi:10.1186/s40575-022-00123-8.","u":"guide/weight-management/","a":"b383","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"英国の一次診療905,553頭のデータ。シェルティは1,248頭中24頭（1.92%）が甲状腺機能低下症と診断されました。他の要因を統計的に調整しても、雑種に対する診断のオッズ比（診断されやすさの比）は8.25（95%信頼区間5.38〜12.65）でした。ただしこれは「診断された」頻度であり、真の発症率ではありません。シェルティ症例も24頭と少なく、体重増加だけで甲状腺機能低下症を推定してはいけません。","u":"guide/weight-management/","a":"b384","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"1. 減量と跛行、中間目標","u":"guide/weight-management/","a":"b385","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"Marshall WG, Hazewinkel HAW, Mullen D, et al. The effect of weight loss on lameness in obese dogs with osteoarthritis. Vet Res Commun. 2010;34:241-253. doi:10.1007/s11259-010-9348-7.","u":"guide/weight-management/","a":"b386","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"OAの症状とX線所見をもつ肥満犬14頭を16週間追跡した前向き試験。人が見て判定した跛行は体重6.10%減から改善しました。床反力計（足が床を押す力を測る装置）による改善は、前肢に跛行があった7頭で8.85%減から確認されましたが、後肢に跛行があった7頭では有意な変化がありませんでした。対照群なし、14頭、評価者が介入内容を知る試験で、対象は理想体重より20%以上重い犬です。したがって本文の約6〜9%は、肥満してOAのある犬で観察された範囲を中間目標に使ったものであり、すべての過体重犬に共通する境目ではありません。","u":"guide/weight-management/","a":"b387","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"2. 家庭犬での減量速度と完遂","u":"guide/weight-management/","a":"b388","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"German AJ, et al. J Vet Intern Med. 2015;29:1547-1555.","u":"guide/weight-management/","a":"b389","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"143頭中87頭（61%）が目標体重に到達し、45頭（31%）が途中中断、11頭（8%）が到達前に死亡または安楽死となりました。全体の減量速度中央値は0.6%/週、完遂群0.7%/週、中断群0.4%/週で、群間差はP=0.001。他の要因を統計的に調整した解析では、減量速度が1%/週増すごとに完遂のオッズ比は10.66（95%信頼区間2.99〜38.00、P<0.001）でした。","u":"guide/weight-management/","a":"b390","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"都合の悪い結果として重要なのは、遅い進行を単なる安心材料にはできないことです。 一方、これは紹介診療の観察研究で、速い減量が成功を引き起こしたとは証明できません。著者も、速く減ったことで飼い主が継続しやすくなった可能性と、遵守度など別の要因が速さと成功の両方に影響した可能性を挙げています。","u":"guide/weight-management/","a":"b391","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"Flanagan J, Bissot T, Hours MA, et al. Success of a weight loss plan for overweight dogs: The results of an international weight loss study. PLoS One. 2017;12:e0184199. doi:10.1371/journal.pone.0184199.","u":"guide/weight-management/","a":"b392","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"27か国340施設の過体重犬926頭を3か月追跡し、896頭（97%）が減量、平均減量率は11.4%でした。活動性と生活の質は飼い主評価で改善しましたが、対照群がなく、評価は主観的です。研究はRoyal Caninの資金提供を受け、複数著者が同社に所属していました。","u":"guide/weight-management/","a":"b393","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"3. 大きな食事制限と栄養素","u":"guide/weight-management/","a":"b394","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"Gaylord L, Remillard R, Saker K. Risk of nutritional deficiencies for dogs on a weight loss plan. J Small Anim Pract. 2018;59:695-703. doi:10.1111/jsap.12913.","u":"guide/weight-management/","a":"b395","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"市販の非療法食を段階的にカロリー制限した理論計算で、コリン、メチオニン・システイン、セレン、魚油に含まれるn-3系脂肪酸、複数のビタミンなどが推奨量を下回りうるとされました。 実際の犬に欠乏症が起きた試験ではありません。 2021年AAHAガイドラインは、大きなカロリー制限時には栄養素を強化した減量用療法食を推奨しています。犬の健康状態を直接比較した根拠が乏しいため、良い方向に働くことの確かさは低としました。","u":"guide/weight-management/","a":"b396","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"4. 運動と筋肉量","u":"guide/weight-management/","a":"b397","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"Vitger AD, Stallknecht BM, Nielsen DH, Bjornvad CR. Integration of a physical training program in a weight loss plan for overweight pet dogs. J Am Vet Med Assoc. 2016;248:174-182. doi:10.2460/javma.248.2.174.","u":"guide/weight-management/","a":"b398","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"19頭の前向き非無作為化研究で、完遂は各群8頭。12週の体重減少率は運動＋食事群13.9%、食事のみ群12.9%で群間差なし（P=0.4）。一方、除脂肪量の変化は群間差があり、総量でP=0.01、減少体重に占める割合でP=0.03、年齢を調整した解析でも運動群で保持が良好でした（P=0.02）。","u":"guide/weight-management/","a":"b399","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"したがって「運動を足せばより痩せる」とは言えませんが、管理された運動が筋肉量保持に役立つ可能性は支持されます。対象数が少なく、犬を無作為に振り分けず、水中・陸上トレッドミルを週3回行う設定なので、家庭の散歩へそのまま当てはめることはできません。","u":"guide/weight-management/","a":"b400","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"5. 減量後の再増加","u":"guide/weight-management/","a":"b401","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"German AJ, Holden SL, Morris PJ, Biourge V. Long-term follow-up after weight management in obese dogs: the role of diet in preventing regain. Vet J. 2012;192:65-70. doi:10.1016/j.tvjl.2011.04.001.","u":"guide/weight-management/","a":"b402","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"減量成功後33頭を中央値640日追跡し、16頭（48%）が5%以上再増加しました。減量用食を続けた犬のほうが再増加は少なかったものの、食事は無作為に割り付けられていません。飼い主の行動差など、食事以外の要因の影響が残ります。","u":"guide/weight-management/","a":"b403","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"確実性のまとめ","u":"guide/weight-management/","a":"b404","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"計画的減量で体重を落とせる方向性は中。 計画を始めてから追跡する研究と診療記録を用いる研究が同方向ですが、犬を無作為に振り分けて比較した試験は少なく、紹介診療の集団や食事メーカーとの資金・雇用関係をもつ研究が目立ちます。","u":"guide/weight-management/","a":"b405","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"関節症状の改善は中、筋肉量保持は低、減量用食による栄養充足の利益は低。 関節は比較対象のない14頭の試験、筋肉は完遂16頭を無作為に振り分けていない研究、食事は主に理論計算とガイドラインに依存します。","u":"guide/weight-management/","a":"b406","e":1},{"c":"4-2","n":"太ってしまったときの減量","s":"根拠","t":"シェルティでどれだけ役立つかの確かさは低〜非常に低。 標準的な減量法の効果量をシェルティ単独で推定できる研究は確認できません。一方、甲状腺機能低下症についてはシェルティ自身の疫学データがあるため、開始前の評価には犬種特異的な根拠があります。","u":"guide/weight-management/","a":"b407","e":1},{"c":"5","n":"去勢・避妊の時期","s":"この章が扱う範囲","t":"この章は、繁殖に用いないシェルティの去勢・避妊を 何歳で行うか を扱います。手術をするかどうか、麻酔や術式が個々の犬に適するかは、診察した獣医師と別に相談してください。","u":"guide/neutering/","a":"b408","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章が扱う範囲","t":"去勢・避妊には、関節疾患、がん、乳腺腫瘍、子宮蓄膿症、尿失禁、行動、体重という別々の結果があります。利益と害の向きが同じではないため、推奨を分けます。","u":"guide/neutering/","a":"b409","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"推奨1 オスの手術時期","u":"guide/neutering/","a":"b410","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"健康上の利益だけを理由に、特定の月齢へ急いだり、反対に遅らせたりする根拠は十分ではありません。飼育上の事情と診察所見をもとに、かかりつけ医と時期を決めてください。","u":"guide/neutering/","a":"b411","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"推奨2 メスの手術時期","u":"guide/neutering/","a":"b412","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"生後6か月未満の避妊は原則として避けてください。6か月以降は、初回発情前に行う、初回または2回目の発情後まで待つ、尿失禁を特に避けたい場合は2歳以降まで待つ、という選択肢を、発情を安全に管理できるかも含めて相談してください。どれか一つがシェルティに最適だと断定できる根拠はありません。","u":"guide/neutering/","a":"b413","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"推奨3 手術後の体重管理","u":"guide/neutering/","a":"b414","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"手術後は月1回、同じ条件で体重とBCS（ボディコンディションスコア：犬の体型を9段階で評価する指標）を確認し、増加傾向があれば給餌量を見直してください。","u":"guide/neutering/","a":"b415","e":0},{"c":"5","n":"去勢・避妊の時期","s":"この章の推奨","t":"推奨3を強くした理由は、シェルティ固有の効果量が不明でも、手術後の体重増加は犬全体で一貫しており、定期測定の害が小さいからです。強さの根拠は研究の量ではなく、害の小ささと必要性です。","u":"guide/neutering/","a":"b416","e":0},{"c":"5","n":"去勢・避妊の時期","s":"なぜこれが重要か","t":"去勢・避妊の時期は「早いほどよい」「1歳まで待つべき」など、一つの数字で語られがちです。しかし、犬種と性別で結果が異なり、シェルティだけを十分な頭数で比較した研究はありません。","u":"guide/neutering/","a":"b417","e":0},{"c":"5","n":"去勢・避妊の時期","s":"なぜこれが重要か","t":"シェルティ133頭を含む研究では、オスの時期別に関節疾患や対象となった4種類のがんが明らかに増える所見はありませんでした。ただし、これは「差がない」と証明したのではなく、少数例のため差を検出できなかった可能性があります。メスでは、1歳台で避妊した群に尿失禁が多いという所見がありましたが、群が小さく、これだけで「2歳まで待つ」とは決められません。","u":"guide/neutering/","a":"b418","e":0},{"c":"5","n":"去勢・避妊の時期","s":"なぜこれが重要か","t":"一方、避妊は子宮蓄膿症を防ぎます。スウェーデンの保険データでは、避妊していないシェルティの23%が10歳までに子宮蓄膿症と診断されました。これは 避妊する利益 であり、必ずしも 早期に避妊する利益 ではありません。","u":"guide/neutering/","a":"b419","e":0},{"c":"5","n":"去勢・避妊の時期","s":"なぜこれが重要か","t":"乳腺腫瘍は早期避妊で減る可能性がありますが、よく引用される大きな予防効果は古い観察研究に依存し、系統的レビューでは根拠の弱さが指摘されています。逆に、遅らせれば尿失禁が減る可能性を示す犬全体の研究もあります。したがって、メスの時期は一つの病気だけで決められません。","u":"guide/neutering/","a":"b420","e":0},{"c":"5","n":"去勢・避妊の時期","s":"なぜこれが重要か","t":"※犬全体の尿失禁・乳腺腫瘍・体重の研究をシェルティへ外挿しています。シェルティで同じ効果量になるとは限りません。","u":"guide/neutering/","a":"b421","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"オス","u":"guide/neutering/","a":"b422","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"予定手術なら、健康状態、停留精巣の有無、同居犬、預け先の条件、交配事故を防げる環境かを獣医師に伝えて決めます。マーキングや犬同士の対立が必ず改善するとは限らず、去勢はしつけや行動診療の代わりにはなりません。","u":"guide/neutering/","a":"b423","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"メス","u":"guide/neutering/","a":"b424","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"生後6か月を過ぎたら、次の三つはいずれも選択肢です。","u":"guide/neutering/","a":"b425","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"初回発情前に行う","u":"guide/neutering/","a":"b426","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"初回または2回目の発情後に行う","u":"guide/neutering/","a":"b427","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"尿失禁を特に避けたい場合は、2歳以降まで待つ","u":"guide/neutering/","a":"b428","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"二つ目は世界小動物獣医師会（WSAVA）の2024年ガイドライン、三つ目はHartらのシェルティ固有データに沿う選択です。ただし、前者は犬種別の最適月齢を示しておらず、後者は少数例に基づく提案です。発情を経験させるなら、出血の開始日を記録し、未去勢のオスと確実に分けてください。庭に単独で出さず、散歩中も接触を避けます。 これは経験則です 。発情中と直後は手術時の出血が増えやすいため、具体的な日程は病院に確認してください。","u":"guide/neutering/","a":"b429","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"手術後","u":"guide/neutering/","a":"b430","e":0},{"c":"5","n":"去勢・避妊の時期","s":"実際にどうするか","t":"手術前の体重を記録し、術後は月1回測ります。同じ量を続けて体重やBCSが上がるなら、袋の表示だけで判断せず、 4-1章 の手順で給餌量を調整してください。傷をなめる、元気や食欲が戻らない、傷が開く・腫れる・液が出る場合は手術した病院へ連絡してください。","u":"guide/neutering/","a":"b431","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"今すぐ（夜間・休日でも）","u":"guide/neutering/","a":"b432","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"発情後1～2か月に、ぐったりして反応が鈍い、繰り返し吐く、腹部が張る、立てない","u":"guide/neutering/","a":"b433","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"手術後に呼吸が苦しそう、意識がはっきりしない、出血が続く","u":"guide/neutering/","a":"b434","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"その日のうちに連絡","u":"guide/neutering/","a":"b435","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"未避妊のメスで、発情後1～2か月に多飲、食欲低下、元気低下、陰部からの分泌物がある","u":"guide/neutering/","a":"b436","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"子宮蓄膿症などを含むため、元気が比較的保たれていてもその日のうちに連絡してください。分泌物がなくても起こりえます。上の「今すぐ」の所見が加われば、夜間・休日でも待たないでください。","u":"guide/neutering/","a":"b437","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"診療時間内に相談","u":"guide/neutering/","a":"b438","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"生後6か月を過ぎても精巣が陰嚢（いんのう：精巣が入る袋）に下りていない","u":"guide/neutering/","a":"b439","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"発情や出血が長く続く、時期が不規則、偽妊娠（妊娠していないのに乳房の張りや巣作りなどが出る状態）が強い","u":"guide/neutering/","a":"b440","e":0},{"c":"5","n":"去勢・避妊の時期","s":"こんなときは受診を","t":"手術後、寝床が繰り返し尿で濡れる","u":"guide/neutering/","a":"b441","e":0},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"国際ガイドライン","u":"guide/neutering/","a":"b442","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"Romagnoli S, et al. WSAVA Guidelines for the Control of Reproduction in Dogs and Cats . J Small Anim Pract. 2024;65:424-559.","u":"guide/neutering/","a":"b443","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"繁殖に用いない全個体への一律の不妊化は支持できず、個体ごとに利益と害を判断する立場です。飼い主のいるメス犬では、目的によるものの、理想的には初回または2回目の発情後としています。また、性成熟前の手術、尿失禁、関節疾患、肥満などの不利益を扱っています。ただし犬種別の推奨ではなく、シェルティにそのまま当てはまる保証はありません。本章はこれを選択肢として示し、一律の時期にはしていません。","u":"guide/neutering/","a":"b444","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"シェルティの時期別データ","u":"guide/neutering/","a":"b445","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"Hart BL, et al. Assisting Decision-Making on Age of Neutering for 35 Breeds of Dogs . Front Vet Sci. 2020;7:388.","u":"guide/neutering/","a":"b446","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"診療記録を用いた後ろ向き研究で、シェルティは計133頭（未去勢オス31、去勢オス30、未避妊メス20、避妊メス52）でした。未去勢オスの関節疾患は0頭、未避妊メスは1頭。去勢オスでは6か月未満群の1頭以外に関節疾患がなく、避妊メスでは観察されませんでした。対象の4種類のがんについて、去勢・避妊群で明らかな増加は観察されませんでした。","u":"guide/neutering/","a":"b447","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"都合の悪い結果として、避妊後の尿失禁は6～11か月群で6%、1歳台群で33%でした。Hartらは同論文の犬種別ガイドラインで、シェルティのメスについて、尿失禁の高い発生率を避けるため2歳以降の避妊を検討してもよいと明示しています。ただし、避妊メス52頭を複数群に分けた数字で、各群は小さく、未避妊群との安定した効果量を示せません。平均最終受診年齢もおよそ4.5～5.5歳で、遅く発症する乳腺腫瘍には追跡が短いという制約があります。","u":"guide/neutering/","a":"b448","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"子宮蓄膿症と乳腺腫瘍","u":"guide/neutering/","a":"b449","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"Jitpean S, et al. Breed Variations in the Incidence of Pyometra and Mammary Tumours in Swedish Dogs . Reprod Domest Anim. 2012;47 Suppl 6:347-350.","u":"guide/neutering/","a":"b450","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"未避妊犬が多いスウェーデンの保険データで、シェルティ雌3,372頭の10歳までの累積発生は、子宮蓄膿症23%、乳腺腫瘍7%でした。手術時期を比較した研究ではありません。23%は避妊の利益を支持しますが、6か月と12か月のどちらがよいかには答えません。乳腺腫瘍7%も、早期避妊の相対効果を示す数字ではありません。","u":"guide/neutering/","a":"b451","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"Beauvais W, et al. J Small Anim Pract. 2012;53:314-322、およびGuirguis P, Beggs DS. Animals. 2025;15:436は、早期避妊と乳腺腫瘍を扱った系統的レビューです。前者は証拠を弱いと評価し、後者でも13報中6報は予防効果を認めませんでした。これは「効果がない」という意味ではありません。WSAVAはリスク低減を認めており、根拠の評価には不一致が残ります。","u":"guide/neutering/","a":"b452","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"尿失禁","u":"guide/neutering/","a":"b453","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"Pegram C, et al. Later-age neutering causes lower risk of early-onset urinary incontinence than early neutering . PLoS One. 2024;19:e0305526.","u":"guide/neutering/","a":"b454","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"犬種混合集団1,500頭で、生後3～7か月未満群と7～18か月群を比較した観察研究です。遅い群の早発性尿失禁のオッズ比は0.80（95%信頼区間0.54～0.97）でした。交絡を調整した設計ですが無作為化試験ではなく、著者も未測定交絡で結果が変わりうるとしています。さらに、シェルティ固有研究では1歳台群のほうが高く、方向が一致しません。この不一致が、推奨2の確実性を低くした理由です。","u":"guide/neutering/","a":"b455","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"体重","u":"guide/neutering/","a":"b456","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"去勢・避妊後の肥満リスク上昇は複数の犬全体の観察研究とWSAVAガイドラインで支持されています。ただし、シェルティで必要カロリーが何％変わるかは分かりません。そのため一律の減量率を示さず、実測した体重とBCSの推移で調整します。","u":"guide/neutering/","a":"b457","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"確実性と推奨のまとめ","u":"guide/neutering/","a":"b458","e":1},{"c":"5","n":"去勢・避妊の時期","s":"根拠","t":"時期を直接比較したシェルティ研究は小さく、結果が偶然に左右されやすいため、推奨1・2はいずれも弱い提案です。「差が報告されなかった」ことを「安全性が証明された」とは扱いません。確実な利益である子宮蓄膿症予防は時期より手術の有無に関係し、乳腺腫瘍と尿失禁は時期に対して逆向きの可能性があります。したがって、メスは生後6か月未満を避けたうえで、一つの病気だけでなく管理可能性を含めて決める、という結論にしました。","u":"guide/neutering/","a":"b459","e":1},{"c":"6","n":"歯のケア","s":"この章が扱う範囲","t":"この章では、家庭での歯磨き、補助製品、硬い物による歯の破折、子犬の乳歯、動物病院での歯科検査・治療を扱います。歯周病の診断や、個々の犬に必要な処置を家庭で決めるための章ではありません。","u":"guide/dental-care/","a":"b460","e":0},{"c":"6","n":"歯のケア","s":"この章の推奨","t":"推奨1","u":"guide/dental-care/","a":"b461","e":0},{"c":"6","n":"歯のケア","s":"この章の推奨","t":"歯磨きは毎日を目標にしてください。毎日できない場合も、できる範囲で頻度を上げてください。","u":"guide/dental-care/","a":"b462","e":0},{"c":"6","n":"歯のケア","s":"この章の推奨","t":"推奨2","u":"guide/dental-care/","a":"b463","e":0},{"c":"6","n":"歯のケア","s":"この章の推奨","t":"麻酔をかけず、見える歯石だけを削り取る施術を、歯周病の検査や治療の代わりに選ばないでください。","u":"guide/dental-care/","a":"b464","e":0},{"c":"6","n":"歯のケア","s":"この章の推奨","t":"推奨を分けたのは、推奨1が家庭でプラーク（細菌を含む歯垢）を除く予防、推奨2がすでにある病変を見逃さず検査・治療するための選択だからです。いずれも強い推奨ですが、強さの根拠は研究の量ではなく、歯磨きの害が小さいことと、歯茎の下の病変を見逃さない必要性にあります。","u":"guide/dental-care/","a":"b465","e":0},{"c":"6","n":"歯のケア","s":"なぜこれが重要か","t":"歯の表面にはプラークが繰り返しできます。炎症が続くと、歯肉炎（歯茎の炎症）から歯周炎へ進み、歯を支える組織や骨が壊れて、歯のぐらつきや喪失につながります。プラークが唾液中の成分で固まったものが歯石です。歯石は歯ブラシでは落ちず、表面に新しいプラークが付着しやすくなります。","u":"guide/dental-care/","a":"b466","e":0},{"c":"6","n":"歯のケア","s":"なぜこれが重要か","t":"問題は、口を開けて見える部分より歯茎の下で進むことです。見える歯石が少なくても、歯周ポケット（歯と歯茎の間にできる溝）の奥や歯根に病変があることがあります。犬は口が痛くても食べ続けることがあるため、「食べているから大丈夫」とは判断できません。","u":"guide/dental-care/","a":"b467","e":0},{"c":"6","n":"歯のケア","s":"なぜこれが重要か","t":"米国の診療記録を用いた研究では、シェットランド・シープドッグの歯周病の診断有病率は30.6%で、調査された60犬種中2番目でした。ただし、未診断例を含む真の有病率ではなく、年齢などを調整した犬種固有の値でもありません。別の英国研究では高リスク犬種の上位に挙がっておらず、シェルティ固有の危険度は確定していません。それでも、口のケアを軽視しない理由にはなります。","u":"guide/dental-care/","a":"b468","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"嫌がらない練習から始める","u":"guide/dental-care/","a":"b469","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"口の周りに触れる、唇をめくる、指で歯茎に触れる、ガーゼ、歯ブラシの順に進めます。短時間で終え、嫌がる前にやめます。押さえ込んで続けると、その後の歯磨きが難しくなります。 これは経験則です が、シェルティでは特に無理をしないほうが実行しやすいと考えます。","u":"guide/dental-care/","a":"b470","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"毎日の磨き方","u":"guide/dental-care/","a":"b471","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"毛の柔らかい歯ブラシを使い、歯と歯茎の境目を軽く磨きます。","u":"guide/dental-care/","a":"b472","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"まず頬側（外側）を優先し、慣れたら内側にも広げます。","u":"guide/dental-care/","a":"b473","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"犬歯と上顎の大きな奥歯の周囲を丁寧に磨きます。","u":"guide/dental-care/","a":"b474","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"片側30秒程度、全体で1～2分を目安にします。","u":"guide/dental-care/","a":"b475","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"人用歯磨き剤は使わないでください。キシリトール入り製品は犬に中毒を起こします。犬用製品または水だけで構いません。","u":"guide/dental-care/","a":"b476","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"毎日できなかった日があっても、再開してください。短期間のビーグルの試験では、毎日または隔日の歯磨きは、週1回または隔週よりプラーク、歯石、歯肉炎の指標が良好でした。 これは他犬種での研究に基づく結果です。 また、毎日の歯磨きが長期的な抜歯をどれだけ減らすかは分かっていません。","u":"guide/dental-care/","a":"b477","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"補助製品と噛む物","u":"guide/dental-care/","a":"b478","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"デンタルガムやデンタルフードは補助であり、歯磨きの代わりではありません。製品選びでは、VOHC（米国獣医口腔衛生協議会）の認定が客観的な目安の一つです。認定がない製品に効果がないという意味ではありません。ガムのカロリーも1日の食事量に含めます。","u":"guide/dental-care/","a":"b479","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"蹄、鹿角、大きな骨、非常に硬いナイロン製玩具は歯を折ることがあります。爪で押しても跡がつかないほど硬い物は避けてください。床に落とすと硬い音がする物も避ける、という基準は 経験則です 。","u":"guide/dental-care/","a":"b480","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"子犬で確認すること","u":"guide/dental-care/","a":"b481","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"永久歯が生えているのに同じ位置の乳歯が残っていたら、年齢を待たず獣医師に相談してください。下顎の犬歯が上顎の歯茎や口蓋（上あごの天井）に当たっている場合も、早めの評価が必要です。","u":"guide/dental-care/","a":"b482","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"動物病院での歯科処置","u":"guide/dental-care/","a":"b483","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"必要なのは、見える歯石を取るだけではありません。麻酔下で口全体を診察し、歯周ポケットを測り、必要に応じて歯科用レントゲンを撮り、歯茎の上下を清掃し、保存できない歯を治療する一連の検査・処置です。間隔を一律に「年1回」と決める根拠は乏しいため、家庭でのケア、口の所見、既往歴、全身状態から獣医師と決めます。","u":"guide/dental-care/","a":"b484","e":0},{"c":"6","n":"歯のケア","s":"実際にどうするか","t":"麻酔には小さいながら実在する危険があります。一方、無麻酔では歯茎の下の十分な検査・清掃や歯科用レントゲン撮影ができません。どちらの危険を重くみるかは、現在の病変と全身状態によって異なります。ABCB1（一般にMDR1と呼ばれる薬剤感受性に関わる遺伝子）の検査結果があれば、麻酔前に獣医師へ提示してください。","u":"guide/dental-care/","a":"b485","e":0},{"c":"6","n":"歯のケア","s":"こんなときは受診を","t":"顔が急に腫れた、口から出血が続く、歯が折れて中に赤や黒い点が見える： その日のうちに連絡","u":"guide/dental-care/","a":"b486","e":0},{"c":"6","n":"歯のケア","s":"こんなときは受診を","t":"口臭が強くなった、歯茎が赤い・出血する、片側だけで噛む、硬い物を避ける、食べるのが遅い、顔を触られるのを嫌がる： 近日中に受診","u":"guide/dental-care/","a":"b487","e":0},{"c":"6","n":"歯のケア","s":"こんなときは受診を","t":"永久歯と乳歯が並んでいる、下顎の犬歯が上顎に当たる： 気づいた時点で相談","u":"guide/dental-care/","a":"b488","e":0},{"c":"6","n":"歯のケア","s":"こんなときは受診を","t":"顔の腫れは歯根の病変でも起こります。皮膚の問題と決めつけず、口の中も診てもらってください。食べられない、呼吸がおかしい、意識や全身状態に異常がある場合は、この章の区分ではなく 第11章 に従い、今すぐ連絡してください。","u":"guide/dental-care/","a":"b489","e":0},{"c":"6","n":"歯のケア","s":"全身の病気も防げるのか","t":"犬では歯周病の重症度と心臓病などの関連を示した観察研究があります。しかし、歯周病を治療すれば心臓病が減るという因果関係は確認されていません。年齢、体格、飼育環境などの影響が残るためです。歯磨きの主な目的は、口の痛みと歯を支える組織の破壊を減らすことです。全身疾患の予防効果を期待して推奨しているわけではありません。","u":"guide/dental-care/","a":"b490","e":0},{"c":"6","n":"歯のケア","s":"根拠","t":"歯磨きの頻度","u":"guide/dental-care/","a":"b491","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Harvey C, Serfilippi L, Barnvos D. Effect of frequency of brushing teeth on plaque and calculus accumulation, and gingivitis in dogs. J Vet Dent. 2015;32(1):16-21.","u":"guide/dental-care/","a":"b492","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"ビーグルを毎日、隔日、週1回、隔週、磨かない群に分けた28日間の無作為化比較試験です。毎日または隔日は、週1回または隔週よりプラーク、歯石、歯肉炎の指標が有意に良好でした。週1回が無処置と同じとは示していません。少数、短期間、単一犬種で、評価は代理指標です。歯の喪失や長期的な処置の減少は検証されていません。したがって良い方向に働くことの確かさは「中」、シェルティでどれだけ役立つかの確かさは「非常に低」としました。他犬種からの外挿ですが、プラーク除去の機序は犬種間で大きく異ならないと考えます。","u":"guide/dental-care/","a":"b493","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Gorrel C, Rawlings JM. The role of tooth-brushing and diet in the maintenance of periodontal health in dogs. J Vet Dent. 1996;13(4):139-143.","u":"guide/dental-care/","a":"b494","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"機械的な清掃が口腔内の指標を改善する方向は、複数の短期試験でおおむね一致しています。ただし、デンタル製品やペットフード関連企業の関与する研究が多く、効果量は慎重に解釈する必要があります。","u":"guide/dental-care/","a":"b495","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"シェルティでの診断有病率","u":"guide/dental-care/","a":"b496","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Wallis C, Saito EK, Salt C, Holcombe LJ, Desforges NG. Association of periodontal disease with breed size, breed, weight, and age in pure-bred client-owned dogs in the United States. Vet J. 2021;275:105717.","u":"guide/dental-care/","a":"b497","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"米国の動物病院チェーンの300万件超の記録では、全体の期間有病率は18.2%、シェルティは30.6%でした。ただし診療録上の診断であり、犬種別数値は交絡因子を調整した比較ではありません。資金元はペットフード企業の研究機関です。","u":"guide/dental-care/","a":"b498","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"O'Neill DG, Mitchell CE, Humphrey J, Church DB, Brodbelt DC, Pegram C. Epidemiology of periodontal disease in dogs in the UK primary-care veterinary setting. J Small Anim Pract. 2021;62(12):1051-1061.","u":"guide/dental-care/","a":"b499","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"英国の22,333頭では1年間の診断有病率は12.52%で、小型、低体重、高齢ほど診断されやすい結果でした。報告された高リスク犬種の上位にシェルティはなく、米国研究と同じ方向とは断定できません。「3歳以上の犬の80%」という広く引用される値は、歯肉炎を含む所見を調べた古い調査に由来し、診療録上の歯周病診断率とは測定対象が異なります。","u":"guide/dental-care/","a":"b500","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"麻酔下検査と無麻酔処置","u":"guide/dental-care/","a":"b501","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Verstraete FJM, Kass PH, Terpak CH. Diagnostic value of full-mouth radiography in dogs. Am J Vet Res. 1998;59(6):686-691.","u":"guide/dental-care/","a":"b502","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"全顎の歯科用レントゲン撮影では、視診で異常がない犬にも臨床的に意味のある所見が見つかりました。目で見える部分だけでは病変を除外できません。","u":"guide/dental-care/","a":"b503","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"無麻酔処置と麻酔下処置を無作為に比較し、歯の残存や歯周炎の進行を長期追跡した試験は確認できません。推奨2は、歯周病が歯茎の下で進むこと、無麻酔では歯周ポケットの検査・処置と歯科用レントゲン撮影ができないことに基づきます。見た目だけが改善し、必要な治療が遅れる可能性は理論上の害で、発生頻度は不明です。このため良い方向に働くことの確かさは「低」、シェルティでどれだけ役立つかの確かさは「非常に低」としました。","u":"guide/dental-care/","a":"b504","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Brodbelt DC, et al. The risk of death: the confidential enquiry into perioperative small animal fatalities. Vet Anaesth Analg. 2008;35(5):365-373.","u":"guide/dental-care/","a":"b505","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"2002～2004年の英国調査では、麻酔・鎮静関連の48時間以内死亡率は犬全体で約0.17%、全身状態が良好な犬で約0.05%でした。国、時代、施設、処置が異なるため、現在の日本の歯科処置へ直接適用できません。歯周病を放置する危険と麻酔の危険を直接比較した研究でもありません。","u":"guide/dental-care/","a":"b506","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"全身疾患との関連","u":"guide/dental-care/","a":"b507","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"Glickman LT, et al. Evaluation of the risk of endocarditis and other cardiovascular events on the basis of the severity of periodontal disease in dogs. J Am Vet Med Assoc. 2009;234(4):486-494.","u":"guide/dental-care/","a":"b508","e":1},{"c":"6","n":"歯のケア","s":"根拠","t":"歯周病の重症度と心血管疾患の関連を示した後ろ向き観察研究です。年齢や体格などの交絡があり、歯科治療によって心血管疾患が減ることは示していません。「歯科処置を受ける犬は長生きする」という観察結果も、日頃のケアや受診行動の違いを除けず、因果関係とは読めません。","u":"guide/dental-care/","a":"b509","e":1},{"c":"7-1","n":"予防薬の扱い","s":"この章が扱う範囲","t":"フィラリア（犬糸状虫）とノミ・マダニの予防薬を扱います。ワクチンは 7-2章 、遺伝子検査は 8章 です。MDR1（エムディーアールワン：薬を体外へ運ぶしくみに関わる遺伝子。正式名称ABCB1）は、薬の使い方に限って説明します。","u":"guide/parasite-prevention/","a":"b510","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"アウトカムが「感染症を防ぐ」と「中毒を避ける」の2つあり、根拠の性質も違うため、推奨を分けました。","u":"guide/parasite-prevention/","a":"b511","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"推奨1","u":"guide/parasite-prevention/","a":"b512","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"フィラリアとノミ・マダニの予防薬は、獣医師が示す期間、決められた用量で、欠かさず投与してください。","u":"guide/parasite-prevention/","a":"b513","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"3つを強い推奨とした根拠は、シェルティでの研究量ではなく、 承認された使い方を守る害が小さく、感染と中毒を避ける必要性が大きいこと です。","u":"guide/parasite-prevention/","a":"b514","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"推奨2","u":"guide/parasite-prevention/","a":"b515","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"犬用として承認された製品を、体重に応じた用量・間隔で使ってください。MDR1変異があっても予防用量で安全性が確認された薬剤がありますが、根拠は薬剤ごとに違います。自己判断で変更・流用しないでください。","u":"guide/parasite-prevention/","a":"b516","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"MDR1変異犬での安全性試験はコリーで行われたものです。外挿の扱いは根拠欄に記しました。","u":"guide/parasite-prevention/","a":"b517","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"推奨3","u":"guide/parasite-prevention/","a":"b518","e":0},{"c":"7-1","n":"予防薬の扱い","s":"この章の推奨","t":"家畜用・人用の製剤を、獣医師の指示なしに犬へ使わないでください。MDR1の遺伝子型にかかわらず当てはまります。","u":"guide/parasite-prevention/","a":"b519","e":0},{"c":"7-1","n":"予防薬の扱い","s":"なぜこれが重要か","t":"「シェルティはイベルメクチンに弱い」は半分正しいのですが、予防薬自体を避ける理由にしてはいけません。","u":"guide/parasite-prevention/","a":"b520","e":0},{"c":"7-1","n":"予防薬の扱い","s":"なぜこれが重要か","t":"MDR1は、脳に入ろうとする薬を血液脳関門（血液中の物質が脳へ入るのを制限するしくみ）で汲み出すP糖蛋白（ピーとうたんぱく）を作る遺伝子です。コリー系にはこれを作れない個体がいて、変異を2つ持つ犬（ホモ）では、血中濃度が同じでも脳内濃度が高くなりやすくなります。","u":"guide/parasite-prevention/","a":"b521","e":0},{"c":"7-1","n":"予防薬の扱い","s":"なぜこれが重要か","t":"対象は駆虫薬だけでなく、下痢止めのロペラミド、鎮静薬、一部の抗がん剤も含みます。 遺伝子型は手術や抗がん治療でも重要です。","u":"guide/parasite-prevention/","a":"b522","e":0},{"c":"7-1","n":"予防薬の扱い","s":"なぜこれが重要か","t":"変異の頻度は集団によって10倍以上ばらつくため、 頻度から個体は判断できません （根拠欄）。ヘテロ（変異を1つだけ持つ犬）は、 承認された予防用量では特別扱いが要りませんが、高用量の薬や抗がん治療では獣医師に伝えてください。","u":"guide/parasite-prevention/","a":"b523","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"フィラリア予防の期間","u":"guide/parasite-prevention/","a":"b524","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"日本では「蚊の発生後1か月から、発生終息の1か月後まで」が目安です。予防薬は蚊を防ぐ薬ではなく、 すでに入った幼虫を過去1か月分さかのぼって駆除する薬 です。そのため終息後の最後の1回を飛ばさないでください。","u":"guide/parasite-prevention/","a":"b525","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"期間の目安には気温から算出するHDU（犬糸状虫発育熱量単位）が使われますが、 あくまで推定です （根拠欄）。","u":"guide/parasite-prevention/","a":"b526","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"投薬を始める前の検査","u":"guide/parasite-prevention/","a":"b527","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"予防薬は成虫の感染を治す薬ではありません。 感染からおよそ6か月未満では検査が陰性になりうるため、投薬歴が不明な犬では再検査が要ることもあります。定期検査は獣医師の指示に従ってください。","u":"guide/parasite-prevention/","a":"b528","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"飲み忘れ、吐いた、体重が変わった","u":"guide/parasite-prevention/","a":"b529","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"気づいたら2回分をまとめず連絡する（何日空いたかで対応が変わります）","u":"guide/parasite-prevention/","a":"b530","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"投与後すぐ吐いたら連絡する（吸収されていない可能性があります）","u":"guide/parasite-prevention/","a":"b531","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"子犬期は体重が毎月変わります。 処方時の区分のまま続けると過小投与になります","u":"guide/parasite-prevention/","a":"b532","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"ノミ・マダニは、犬だけの問題ではありません","u":"guide/parasite-prevention/","a":"b533","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"マダニが媒介するSFTS（重症熱性血小板減少症候群）では、 感染した動物の血液や体液への接触で人が感染した例があります。 犬の損得だけで計算する話ではありません。ただし 「予防薬を使えばSFTSを防げる」と示した犬での試験はなく、 寄生を減らすことがリスクを下げる一要素になる、というのが上限です。","u":"guide/parasite-prevention/","a":"b534","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"散歩のあとは体を触って確認を。 被毛が厚いので、見るのではなく指で探します （ 経験則です ）。耳の縁、目のまわり、内股、指の間。見つけたら潰さず引きちぎらず、器具で取るか動物病院へ。 潰さない・素手で触らないことは、飼い主自身の感染リスクを下げる意味でも重要です。","u":"guide/parasite-prevention/","a":"b535","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"イソキサゾリン系の神経系有害事象","u":"guide/parasite-prevention/","a":"b536","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"主流のノミ・マダニ薬には、イソキサゾリン系（ノミやマダニの神経に作用する薬の系統）があります。 筋振戦（筋肉のふるえ）・運動失調（ふらつきや動きの不協和）・けいれんの報告があり、米国FDA（食品医薬品局）が2018年に注意喚起しました。同時に大多数の動物には安全かつ有効ともされ、頻度は不明です （根拠欄）。","u":"guide/parasite-prevention/","a":"b537","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"てんかんや原因不明のけいれんの既往がある犬は、投与前に申告してください","u":"guide/parasite-prevention/","a":"b538","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"既往がなくても、投与後に神経症状が出たら次回の投与前に伝えてください（ 発症まで数時間以上かかることがあります ）","u":"guide/parasite-prevention/","a":"b539","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"やってはいけないこと","u":"guide/parasite-prevention/","a":"b540","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"家畜用・馬用のイベルメクチン製剤を薄めて使う（濃度が桁違いで、死亡例が出ています）","u":"guide/parasite-prevention/","a":"b541","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"他の犬の残った薬を分けてもらう","u":"guide/parasite-prevention/","a":"b542","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"人用の駆虫薬を流用する","u":"guide/parasite-prevention/","a":"b543","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"獣医師の処方によらない高用量投与（疥癬〔かいせん〕や毛包虫症〔もうほうちゅうしょう〕の治療目的を含む）","u":"guide/parasite-prevention/","a":"b544","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"遺伝子型にかかわらず避けてください。 濃度、適応、投与経路、計算間違いも問題になります。","u":"guide/parasite-prevention/","a":"b545","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"MDR1検査を受けるかどうか","u":"guide/parasite-prevention/","a":"b546","e":0},{"c":"7-1","n":"予防薬の扱い","s":"実際にどうするか","t":"急ぎませんが、将来の手術・鎮静・抗がん治療のために受ける価値はあります。 結果はカルテと手元の両方に残してください。","u":"guide/parasite-prevention/","a":"b547","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"投薬後に次のいずれかが出たら、用量や製剤にかかわらず速やかに連絡してください。","u":"guide/parasite-prevention/","a":"b548","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"ふらつく、まっすぐ歩けない","u":"guide/parasite-prevention/","a":"b549","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"よだれが止まらない","u":"guide/parasite-prevention/","a":"b550","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"瞳孔が開いたまま、目が見えていないように見える","u":"guide/parasite-prevention/","a":"b551","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"震える、けいれんする","u":"guide/parasite-prevention/","a":"b552","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"反応が鈍い、呼びかけても起きない","u":"guide/parasite-prevention/","a":"b553","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"発症までの時間は薬剤・用量・個体で変わります。 時間が経っていることを「薬ではない」根拠にしないでください。","u":"guide/parasite-prevention/","a":"b554","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"そのほか：","u":"guide/parasite-prevention/","a":"b555","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"マダニがうまく取れない、口器が残った","u":"guide/parasite-prevention/","a":"b556","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"発熱、元気・食欲低下は速やかに相談。 歯ぐきが白い場合は今すぐ連絡 し、マダニ曝露の心当たりを伝えてください。","u":"guide/parasite-prevention/","a":"b557","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"咳が続く、運動を嫌がる、疲れやすい（フィラリア感染を疑う場面です）","u":"guide/parasite-prevention/","a":"b558","e":0},{"c":"7-1","n":"予防薬の扱い","s":"こんなときは受診を","t":"投薬期間中に、明らかに落とした月がある","u":"guide/parasite-prevention/","a":"b559","e":0},{"c":"7-1","n":"予防薬の扱い","s":"ヒトの研究から考える","t":"このコラムは推奨ではありません。犬のデータで確認されていない、考察のための話です。","u":"guide/parasite-prevention/","a":"b560","e":0},{"c":"7-1","n":"予防薬の扱い","s":"ヒトの研究から考える","t":"犬のMDR1とヒトのABCB1は、同じ遺伝子です。ヒトの血液脳関門にも同じP糖蛋白が並び、同じように薬を汲み出しています。","u":"guide/parasite-prevention/","a":"b561","e":0},{"c":"7-1","n":"予防薬の扱い","s":"ヒトの研究から考える","t":"面白いのは、ヒトでは精神科領域でこの遺伝子が問題になってきたことです。抗うつ薬の一部（シタロプラム、パロキセチン、アミトリプチリン、ベンラファキシンなど）はP糖蛋白の基質で、ミルタザピンのように基質でないものもあります。2008年にUhrらは、ABCB1の多型が「基質である抗うつ薬」の寛解率を予測し、基質でない薬では予測しなかったと報告しました。血中濃度ではなく、 脳に届く量が遺伝子型で変わる という話です。","u":"guide/parasite-prevention/","a":"b562","e":0},{"c":"7-1","n":"予防薬の扱い","s":"ヒトの研究から考える","t":"ただし再現は一致していません。メタ解析でも結論は割れており、遺伝子型で抗うつ薬を選ぶところまでは来ていません。","u":"guide/parasite-prevention/","a":"b563","e":0},{"c":"7-1","n":"予防薬の扱い","s":"ヒトの研究から考える","t":"犬とヒトの違いは、変異の質です。 犬の4塩基欠失は、ポンプそのものが作れなくなる全か無かの変異。ヒトの多型はもっと穏やかで、効きが少し変わる程度にとどまります。それでも両者は同じ仕組みを見ています。「同じ量を飲んでも、脳に届く量は個体で違う」という考え方が、犬では1つの遺伝子検査として実装され、ヒトではまだ研究段階にある。 薬理遺伝学が先に実用化されたのは、犬のほうでした。","u":"guide/parasite-prevention/","a":"b564","e":0},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"MDR1の機序と、ヘテロの扱い","u":"guide/parasite-prevention/","a":"b565","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"Mealey KL, Bentjen SA, Gay JM, Cantor GH. Pharmacogenetics. 2001;11:727-733. コリーのイベルメクチン感受性が、mdr1遺伝子の4塩基欠失（ABCB1-1Δ）によることを示した最初の報告。この欠失はフレームシフトを起こし、機能するP糖蛋白が産生されません。感受性を示したのは変異ホモの個体でした。 疫学的な関連ではなく、分子レベルで説明のついた因果です。 P糖蛋白を欠くノックアウトマウスでは、イベルメクチンの脳内濃度が野生型の90倍に達しています。","u":"guide/parasite-prevention/","a":"b566","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"Mealey KL, et al. J Vet Intern Med. 2008;22:996-1000. リンパ腫の犬34頭。ビンクリスチン投与後、 ヘテロまたはホモの犬は好中球減少（P=.0005）と血小板減少（P=.0001）を起こしやすい という結果。 この非対称性がヘテロの記述を決めています。 大環状ラクトンではヘテロの感受性増加が明確でない一方、抗がん剤では差が出た。34頭と小規模で、犬種構成にも偏りがあります。","u":"guide/parasite-prevention/","a":"b567","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"頻度","u":"guide/parasite-prevention/","a":"b568","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"Gramer I, et al. Vet J. 2011;189:67-71（ドイツ7,378頭。シェルティのアレル頻度30%）／Lerdkrai C, Phungphosop N. Vet World. 2021;14:3015-3020（タイ。シェルティ93頭でアレル頻度11.28%、ヘテロ16.13%、ホモ3.22%）／Kawabata A, et al. J Vet Med Sci. 2005;67:1103-1107（国内8犬種193頭。シェルティ1.2%）。","u":"guide/parasite-prevention/","a":"b569","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"日本の1.2%は、2005年に調査された集団の値です。 8犬種193頭のうちシェルティの頭数は限られ、現在の国内繁殖集団に当てはめることはできません。","u":"guide/parasite-prevention/","a":"b570","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"薬剤ごとの安全性の根拠","u":"guide/parasite-prevention/","a":"b571","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"「MDR1変異犬でも予防用量で安全」は、薬剤ごとに強さが違います。","u":"guide/parasite-prevention/","a":"b572","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"イベルメクチン（予防用量6µg/kg）","u":"guide/parasite-prevention/","a":"b573","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"分子機序と明確な用量反応。変異ホモの中毒閾値はおよそ100µg/kg で、予防用量の10倍以上","u":"guide/parasite-prevention/","a":"b574","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"ミルベマイシンオキシム","u":"guide/parasite-prevention/","a":"b575","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"変異ホモのコリーで最大推奨量の4.7倍を投与し、軽度・一過性の神経症状あり","u":"guide/parasite-prevention/","a":"b576","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"アフォキソラネル","u":"guide/parasite-prevention/","a":"b577","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"同、3.8〜4.7倍まで忍容","u":"guide/parasite-prevention/","a":"b578","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"中〜高","u":"guide/parasite-prevention/","a":"b579","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"フルララネル","u":"guide/parasite-prevention/","a":"b580","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"同、3倍まで忍容","u":"guide/parasite-prevention/","a":"b581","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"中〜高","u":"guide/parasite-prevention/","a":"b582","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"モキシデクチン（経口合剤）","u":"guide/parasite-prevention/","a":"b583","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"変異ホモのコリーで最大推奨量の1・3倍で忍容。5倍では一過性の神経症状あり","u":"guide/parasite-prevention/","a":"b584","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"サロラネル単剤","u":"guide/parasite-prevention/","a":"b585","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"変異ホモのコリーで推奨量の5倍を単回経口投与し、投与関連の臨床所見なし","u":"guide/parasite-prevention/","a":"b586","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"中〜高","u":"guide/parasite-prevention/","a":"b587","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"セラメクチン（外用）","u":"guide/parasite-prevention/","a":"b588","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"アバーメクチン感受性コリーで推奨量の1・3・5倍を外用。薬剤に特異的な用量依存性の有害事象なし","u":"guide/parasite-prevention/","a":"b589","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"Walther FM, et al. Parasit Vectors. 2014;7:86. doi:10.1186/1756-3305-7-86／Drag M, Tielemans E, Mitchell E. J Vet Pharmacol Ther. 2022;45:373-379. doi:10.1111/jvp.13064／Simparica EU Summary of Product Characteristics／Revolution Freedom of Information Summary, NADA 141-152。","u":"guide/parasite-prevention/","a":"b590","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"サロラネルは遺伝子型確認済みのMDR1（−/−）コリーですが、セラメクチンは遺伝子型ではなく、アバーメクチン感受性で選ばれた24頭のコリーです。 このため、セラメクチンの確実性は「中」に留めました。同試験の経口投与部分では、5 mg/kg後に1頭で一過性の運動失調がありましたが、10および15 mg/kgの後続投与では再現しませんでした。この経口試験は外用の安全性を直接示すものではありません。","u":"guide/parasite-prevention/","a":"b591","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"Dragらの試験は30頭と小規模で、製造企業が資金提供し、著者も同社員でした。 ミルベマイシンオキシム単独群では、最大推奨量の4.7倍で軽く一過性の神経症状がみられました。これらは結果を解釈する限界です。","u":"guide/parasite-prevention/","a":"b592","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"薬剤・投与経路・製品ごとに根拠は異なります。そのため推奨2は「予防用量ならすべて安全」ではなく、「承認された製品を承認された使い方で」としています。","u":"guide/parasite-prevention/","a":"b593","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"都合の悪い所見。 ノックアウトマウスでは、フルララネルの脳移行がP糖蛋白によって部分的に制御されていることが示されています。イベルメクチンよりはるかに小さい程度ですが、 「MDR1と完全に無関係」ではありません。","u":"guide/parasite-prevention/","a":"b594","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"神経系有害事象","u":"guide/parasite-prevention/","a":"b595","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"FDAは2018年9月20日に注意喚起を出し、2019年に対象製品を追加しました。 Bates N, et al. Vet Rec. 2024;194:e4149 （英国・オランダの中毒情報センター。転帰情報のある22例、ない57例）では、犬で治療用量でも過量でも神経症状が報告され、 転帰の分かった症例はすべて回復 しています。著者らは投与から発症までの時間差で関連が見逃されうること、頻度は不明であることを指摘しています。","u":"guide/parasite-prevention/","a":"b596","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"分母はどちらの方向からも分かりません。 中毒情報センターに来る症例は重症側に偏ります。逆に、インターネット調査で流通する「66.6%に有害事象」といった数字は自己選択サンプルで、頻度の推定には使えません。","u":"guide/parasite-prevention/","a":"b597","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"HDU","u":"guide/parasite-prevention/","a":"b598","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"HDUの算出（平均気温−14℃を積算し130超で感染開始、直近30日の合計が130未満で終了）と地域別の期間は、国内メーカーが毎年公表する実務資料です。 査読を経た学術文献ではありません。 運用実績は長いものの、根拠の性質が上記の研究群とは異なります。","u":"guide/parasite-prevention/","a":"b599","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"確実性と外挿の扱い","u":"guide/parasite-prevention/","a":"b600","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"良い方向に働くことの確かさが高い理由。 フィラリア予防薬の有効性は対照試験の蓄積があり、MDR1の毒性機序は分子レベルで説明がつきます。","u":"guide/parasite-prevention/","a":"b601","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"シェルティでどれだけ役立つかの確かさを「中」に留めた理由。 シェルティを対象にフィラリア予防やノミ・マダニ予防の効果を検証した研究は見当たりません。感染と薬理の機序は種レベルですが、実測がないため確定できません。","u":"guide/parasite-prevention/","a":"b602","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"推奨2の効果量だけが「中〜高」なのは、外挿の単位が犬種ではないためです。 MDR1変異ホモのコリーと変異ホモのシェルティは、この薬理に関する限り同じ欠損を持ちます。同じ遺伝子の同じ欠失、同じ蛋白の不在です。 したがって犬種の違いを理由とする外挿の不確実性は小さい。 ただし「劣化なし」とは書きません。遺伝子型が同じでも、薬物動態は年齢・体格・肝腎機能・併用薬に影響され、P糖蛋白以外の経路も残ります。 これは他犬種（コリー）からの外挿であり、犬種を理由とする劣化を課さないという判断です。 制作方針への追加提案として、「遺伝子型レベルの機序 → 犬種を理由とする劣化は課さない。他の外挿要因は個別に評価する」を挙げます。","u":"guide/parasite-prevention/","a":"b603","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"利益と害のバランス","u":"guide/parasite-prevention/","a":"b604","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"害は小さく、利益は大きい。加えて他章にない特徴が2つあります。ひとつは 予防の失敗が可逆でない こと。成虫が定着してからの治療は、体重管理のように「これから改善する」で済みません。もうひとつは 利益が犬だけに帰属しない こと。マダニ対策はSFTSを介して同居する人にも関わります。","u":"guide/parasite-prevention/","a":"b605","e":1},{"c":"7-1","n":"予防薬の扱い","s":"根拠","t":"したがって3つとも「強い」としました。 この章の最大の実務的リスクは、予防薬を使いすぎることではなく、MDR1への漠然とした不安から予防そのものを避けることだと考えています。","u":"guide/parasite-prevention/","a":"b606","e":1},{"c":"7-2","n":"ワクチン","s":"この章が扱う範囲","t":"この章は、健康なシェルティのワクチンを「混合ワクチンを毎年打つか」ではなく、 どの感染症を、いつ、どの間隔で予防するか に分けて考えます。病気や治療によって免疫の働きが弱っている犬、過去に重い副反応があった犬、妊娠中の犬は個別判断が必要です。","u":"guide/vaccination/","a":"b607","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"推奨1 すべての犬に必要なコアワクチン","u":"guide/vaccination/","a":"b608","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"犬ジステンパーウイルス、犬アデノウイルス、犬パルボウイルスを含むコアワクチンは、子犬では少なくとも16週齢以降まで接種を続け、26週齢以降に追加接種を受けてください。その後の間隔は、製品の承認内容を確認して、かかりつけ医と相談して決めてください。世界小動物獣医師会は、適切に免疫された成犬では3年より頻回に接種しないよう勧めています。","u":"guide/vaccination/","a":"b609","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"推奨2 狂犬病ワクチン","u":"guide/vaccination/","a":"b610","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"日本では、生後91日以上の犬に毎年1回、狂犬病予防注射を受けさせ、注射済票の交付を受けてください。2026年度分までは従来どおり4〜6月が接種期間です。2027年3月2日からこの期間指定はなくなりますが、毎年1回という義務は変わりません。","u":"guide/vaccination/","a":"b611","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"推奨3 レプトスピラワクチン","u":"guide/vaccination/","a":"b612","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"ネズミなどの野生動物がいる場所、水たまり、川、田畑に接する犬や、発生地域へ出かける犬では、レプトスピラ症のワクチンをかかりつけ医と相談してください。生活環境と地域の発生状況が変われば、毎年見直します。","u":"guide/vaccination/","a":"b613","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"推奨4 犬同士で広がる呼吸器感染症のワクチン","u":"guide/vaccination/","a":"b614","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"ペットホテル、保育園、ドッグショーなど、不特定多数の犬と近距離で接する予定がある場合は、ボルデテラや犬パラインフルエンザなどのワクチンを事前に相談してください。施設が求める「何種混合か」だけで決めず、必要な成分と接種時期を確認します。","u":"guide/vaccination/","a":"b615","e":0},{"c":"7-2","n":"ワクチン","s":"この章の推奨","t":"推奨を分けたのは、対象となる病気、必要性、接種間隔が異なるからです。コア感染症と狂犬病はすべての犬が対象ですが、レプトスピラ症と呼吸器感染症は暮らし方で利益が変わります。シェルティだけの有効性研究はほぼなく、効果量は他犬種からの外挿です。","u":"guide/vaccination/","a":"b616","e":0},{"c":"7-2","n":"ワクチン","s":"なぜこれが重要か","t":"ワクチンは、ひとまとめにすると過不足が生じます。コアワクチンは重い感染症を防ぐ土台ですが、子犬では母犬由来の抗体がワクチンの働きを妨げる時期に個体差があります。そのため「3回打ったか」より、 最後の1回が何週齢だったか が重要です。26週齢以降の追加接種は、16週齢の接種にも反応しなかった少数の犬を補います。","u":"guide/vaccination/","a":"b617","e":0},{"c":"7-2","n":"ワクチン","s":"なぜこれが重要か","t":"一方、成犬のコアワクチンを毎年繰り返す必要は通常ありません。レプトスピラや呼吸器病のワクチンは免疫の持続や感染機会が異なり、より短い間隔が必要になることがあります。「混合ワクチンは毎年／不要」という二択ではなく、成分別に判断します。","u":"guide/vaccination/","a":"b618","e":0},{"c":"7-2","n":"ワクチン","s":"なぜこれが重要か","t":"推奨1・2は、シェルティ固有の効果量が分からなくても強い推奨です。ワクチンの害は皆無ではなく、まれに重い有害事象もあります。しかし、対象と間隔を適切に選べば、害は予防利益に比べて小さいと判断されます。 強さの根拠は研究の量ではなく、この害の小ささと、重大な感染症を防ぐ必要性です。 狂犬病には法律上の義務もあります。","u":"guide/vaccination/","a":"b619","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"子犬","u":"guide/vaccination/","a":"b620","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"譲渡時の証明書で、接種日、製品名、対象成分、製造番号を確認し、かかりつけ医に見せます。コアワクチンは一般に6〜8週齢から始め、2〜4週間隔で少なくとも16週齢以降まで続けます。感染リスクが特に高い地域では、18〜20週齢まで続ける場合があります。さらに26週齢以降に1回追加します。","u":"guide/vaccination/","a":"b621","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"ワクチン完了まで家に閉じ込める必要はありません。感染症への曝露を避けながら、人、音、環境に慣らす社会化は並行します。不特定多数の犬が排泄する場所や、体調不明の犬との接触は避けてください。","u":"guide/vaccination/","a":"b622","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"成犬","u":"guide/vaccination/","a":"b623","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"毎年の健康診断で、接種記録と今後1年の予定を確認します。世界小動物獣医師会は、適切に免疫された成犬のコアワクチンを3年より頻回に接種しないよう勧めています。ただし、製品の添付文書とガイドラインで間隔が異なることがあります。飼い主だけで間隔を決めず、使用する製品とかかりつけ医の判断を確認してください。犬ジステンパー、犬アデノウイルス、犬パルボウイルスでは、血液中の抗体を測る検査を再接種判断に使える場合があります。ただし、狂犬病の法的義務の代わりにはなりません。","u":"guide/vaccination/","a":"b624","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"旅行、ホテル、競技会の予定は早めに伝えます。施設の条件と医学的な必要性は同じとは限らないため、必要な成分、接種期限、証明書を別々に確認してください。","u":"guide/vaccination/","a":"b625","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"接種当日","u":"guide/vaccination/","a":"b626","e":0},{"c":"7-2","n":"ワクチン","s":"実際にどうするか","t":"体調がいつもと違うときは接種前に伝えます。帰宅後は普段どおり観察し、接種日、製品名、接種部位を記録します。過去に副反応があった場合は、自己判断で中止・分割・前投薬をせず、前回の経過を伝えて計画を立てます。","u":"guide/vaccination/","a":"b627","e":0},{"c":"7-2","n":"ワクチン","s":"こんなときは受診を","t":"接種後に顔の腫れ、呼吸の異常、繰り返す嘔吐、ぐったりして反応が乏しい状態、倒れるなどがあれば、 すぐに動物病院へ連絡してください 。軽い元気低下や接種部位の痛みでも、強い、悪化する、長引く場合は相談します。","u":"guide/vaccination/","a":"b628","e":0},{"c":"7-2","n":"ワクチン","s":"こんなときは受診を","t":"接種後しばらくして皮膚の赤み、脱毛、かさぶたなどが続く場合も受診してください。見た目だけでワクチンとの因果関係やシェルティの皮膚筋炎と判断することはできません。","u":"guide/vaccination/","a":"b629","e":0},{"c":"7-2","n":"ワクチン","s":"根拠","t":"1. コアワクチンの範囲と子犬の接種時期","u":"guide/vaccination/","a":"b630","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"World Small Animal Veterinary Association（世界小動物獣医師会、WSAVA）の2024年ガイドラインは、犬ジステンパーウイルス（CDV）、犬アデノウイルス2型（CAV-2）、犬パルボウイルス2型（CPV-2）を世界的なコアワクチンとする。子犬では6〜8週齢から開始し、2〜4週間隔で16週齢以降まで続ける。同ガイドラインの犬用接種表は、特に高リスクの状況では20週齢まで続けるとしており、FAQも曝露リスクが特に高い地域では最終接種を18〜20週齢とする場合があると説明している。母犬由来抗体が残る期間に個体差があり、早い時期の接種回数だけでは免疫獲得を保証できないためである。","u":"guide/vaccination/","a":"b631","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"WSAVA 2024は、従来の「12か月齢の追加接種」を26週齢以降へ前倒しできるとした。16週齢時点でも母犬由来抗体に阻まれる少数例の感受性期間を短くする目的であり、26週齢より前に置き換える趣旨ではない。成犬では、適切に免疫された犬への改変生ワクチン（病原体を弱めて免疫をつけるワクチン）を3年より頻回に接種しないとしている。一方、製品の添付文書がより短い間隔を示す場合があることも認め、地域の規制を確認し、添付文書と異なる使用では飼い主への説明と同意を記録するよう述べている。未接種歴の成犬などでも製品の承認条件を確認する必要がある。","u":"guide/vaccination/","a":"b632","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"2. 抗体検査で分かることと分からないこと","u":"guide/vaccination/","a":"b633","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"CDV、CAV、CPVでは、血清抗体の存在が防御免疫とよく対応するため、コアワクチンの再接種判断に抗体検査を利用できる。陰性結果は必ずしも免疫記憶の欠如を意味しないが、WSAVAは陰性犬への再接種を勧める。一方、レプトスピラなどでは血清抗体価が防御を同じように示さず、検査を接種判断へ単純に置き換えられない。狂犬病も、日本国内の毎年1回の接種義務を抗体検査で代替できない。","u":"guide/vaccination/","a":"b634","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"3. 狂犬病予防法と2027年の制度変更","u":"guide/vaccination/","a":"b635","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"狂犬病予防法は、生後91日以上の犬の所有者に、登録と毎年1回の予防注射を義務づけている。2026年4月1日公布の厚生労働省令第73号は、施行規則にあった4月1日から6月30日までという接種期間を廃止し、2027年3月2日に施行される。通年接種になっても「毎年1回」と注射済票の交付は残る。","u":"guide/vaccination/","a":"b636","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"移行期には年度の扱いに注意が必要である。2027年3月2日から31日までの接種には2026年度の注射済票が交付され、原則として2027年度分とはならない。自治体の案内を確認する必要があるため、本章は制度施行後の2027年に再確認する。","u":"guide/vaccination/","a":"b637","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"4. レプトスピラ症と呼吸器感染症","u":"guide/vaccination/","a":"b638","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"WSAVA 2024は、レプトスピラ症が流行し適切な製品を利用できる地域では、同ワクチンをコアとして扱う方向へ更新した。ただし血清型（免疫反応の違いで分けた型）の分布、製品に含まれる型、曝露機会は地域で異なる。日本のすべての家庭犬に同じ製品を一律に勧める根拠にはならないため、本章では生活環境と地域情報による個別判断とした。これは国際指針を日本の飼育環境へ適用した提案であり、シェルティ固有の研究ではない。","u":"guide/vaccination/","a":"b639","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"ボルデテラ・ブロンキセプチカ、犬パラインフルエンザウイルスなどの呼吸器病ワクチンも、犬同士の密な接触がある場合に選ぶノンコアワクチン（暮らし方や地域に応じて選ぶワクチン）である。感染を完全に防ぐとは限らず、症状や病原体排出を減らすことが主な目的となる。施設要件は地域の疾病リスクとは別の要素である。","u":"guide/vaccination/","a":"b640","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"5. 有害事象とシェルティでの不確実性","u":"guide/vaccination/","a":"b641","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"Mooreら（2005）は米国の動物病院記録で、ワクチン接種後3日以内の有害事象を1万頭当たり38.2件と報告した。小型犬ほど、また1回の来院で接種するワクチン数が多いほど報告率が高かった。ただし診療記録を用いた観察研究であり、軽い事象の見逃し、接種との因果関係、現在の製品への一般化には限界がある。ワクチンを分日にすれば重い反応を防げると直接示した研究ではない。","u":"guide/vaccination/","a":"b642","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"この研究を含め、シェルティだけの利益と害を精度よく測った資料は乏しい。犬種名が有害事象の上位にないことや統計学的有意差が報告されないことから、「シェルティは低リスク」とは推定できない。一方、シェルティの皮膚筋炎と、接種後に報告される虚血性皮膚障害（血流の障害による皮膚の病変）は、似た外見があり得ても同一の病気として扱えない。接種後の皮膚症状は診断せず受診につなぐ。","u":"guide/vaccination/","a":"b643","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"6. 都合の悪い結果と限界","u":"guide/vaccination/","a":"b644","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"ワクチンはすべての接種犬で感染を完全に防ぐわけではない。呼吸器病ワクチンでは感染そのものを防げない場合があり、レプトスピラワクチンでは製品に含まれない血清型への防御を保証できない。抗体検査もすべてのワクチン成分に使える方法ではない。また、ワクチン有害事象の大規模研究は古い製品を含む海外データで、シェルティの現在の絶対リスクは分からない。害は皆無ではないが、対象と間隔を適切に選んだ接種では、予防できる感染症の重大さと比べて小さいと判断した。したがって、コア感染症と狂犬病では予防の必要性が不確実性を上回り、狂犬病では法的義務も強い推奨を支える。","u":"guide/vaccination/","a":"b645","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"主要資料","u":"guide/vaccination/","a":"b646","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"Squires RA, et al. 2024 guidelines for the vaccination of dogs and cats — compiled by the Vaccination Guidelines Group of the World Small Animal Veterinary Association. J Small Anim Pract. 2024;65:277-316. doi:10.1111/jsap.13718.","u":"guide/vaccination/","a":"b647","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"Moore GE, Guptill LF, Ward MP, et al. Adverse events diagnosed within three days of vaccine administration in dogs. J Am Vet Med Assoc. 2005;227:1102-1108. doi:10.2460/javma.2005.227.1102.","u":"guide/vaccination/","a":"b648","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"狂犬病予防法（昭和25年法律第247号）。","u":"guide/vaccination/","a":"b649","e":1},{"c":"7-2","n":"ワクチン","s":"根拠","t":"狂犬病予防法施行規則の一部を改正する省令（令和8年厚生労働省令第73号）および厚生労働省通知（令和8年4月1日、感発0401第1号）。","u":"guide/vaccination/","a":"b650","e":1},{"c":"8","n":"遺伝子検査について","s":"この章が扱う範囲","t":"譲渡時に受け取った遺伝子検査の結果を、どう読み、いつ動物病院へ伝えるかを扱います。繁殖の組み合わせや血統ごとの評価は扱いません。","u":"guide/genetic-tests/","a":"b651","e":0},{"c":"8","n":"遺伝子検査について","s":"この章が扱う範囲","t":"遺伝子検査で分かるのは、調べた遺伝的な変化に限られます。病気の診断や、将来の健康全体を保証する検査ではありません。","u":"guide/genetic-tests/","a":"b652","e":0},{"c":"8","n":"遺伝子検査について","s":"この章の推奨","t":"推奨1","u":"guide/genetic-tests/","a":"b653","e":0},{"c":"8","n":"遺伝子検査について","s":"この章の推奨","t":"譲渡時に受け取った結果表を保管し、初診時にかかりつけの動物病院へ渡してください。麻酔・手術・抜歯、新しい薬や抗がん剤を検討するとき、転院・夜間救急を受診するときにも、結果があることを伝えてください。","u":"guide/genetic-tests/","a":"b654","e":0},{"c":"8","n":"遺伝子検査について","s":"この章の推奨","t":"推奨2","u":"guide/genetic-tests/","a":"b655","e":0},{"c":"8","n":"遺伝子検査について","s":"この章の推奨","t":"市販の多項目パネル検査を、多くの家庭犬で追加購入する必要はありません。購入する場合は、結果だけで病気の有無を決めず、獣医師または検査内容を説明できる専門家と解釈してください。","u":"guide/genetic-tests/","a":"b656","e":0},{"c":"8","n":"遺伝子検査について","s":"この章の推奨","t":"2つを分けたのは、すでにある情報を診療に生かすことと、新たな検査を購入することでは、利益・害と根拠が異なるからです。推奨1を強くした根拠は研究の量ではなく、共有による害がほぼなく、薬剤によっては情報を見落とす不利益が大きいことです。","u":"guide/genetic-tests/","a":"b657","e":0},{"c":"8","n":"遺伝子検査について","s":"なぜこれが重要か","t":"遺伝子検査には、薬の使い方に関係するもの、単一の変異が発症に強く関係するもの、発症しやすさだけを示すものがあります。同じ結果表示でも意味は同じではありません。","u":"guide/genetic-tests/","a":"b658","e":0},{"c":"8","n":"遺伝子検査について","s":"なぜこれが重要か","t":"代表的なMDR1（エムディーアール・ワン。正式名ABCB1）は、一部の薬を脳から外へ運ぶなどの働きに関係します。変異がある犬では薬への反応が変わることがありますが、遺伝子型だけで使用禁止になるわけではありません。薬と用量を含めて獣医師が判断します。","u":"guide/genetic-tests/","a":"b659","e":0},{"c":"8","n":"遺伝子検査について","s":"なぜこれが重要か","t":"「クリア／ノーマル」は、検査対象の変異が見つからなかったという意味です。同じ症状を起こす別の原因や、検査項目にない病気までは否定しません。「高リスク」も診断ではなく、「低リスク」も発症しない保証ではありません。","u":"guide/genetic-tests/","a":"b660","e":0},{"c":"8","n":"遺伝子検査について","s":"なぜこれが重要か","t":"また、病気の原因ではなく、その近くの「目印」を調べる検査もあります。コリー眼異常ではシェルティとラフ・コリーで検査の一致度が異なりました。 他犬種の結果をシェルティへそのまま外挿（別の集団の結果を当てはめること）はできません。","u":"guide/genetic-tests/","a":"b661","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"1. 結果表を保管して共有する","u":"guide/genetic-tests/","a":"b662","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"紙とスマートフォンの両方に全ページを保存し、初診時にコピーを渡します。次の場面では、カルテに入っていても口頭で伝えてください。","u":"guide/genetic-tests/","a":"b663","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"麻酔、手術、抜歯の前","u":"guide/genetic-tests/","a":"b664","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"新しい薬や抗がん剤を検討するとき","u":"guide/genetic-tests/","a":"b665","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"転院、旅行先、夜間救急を受診するとき","u":"guide/genetic-tests/","a":"b666","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"2. 表示の意味を確認する","u":"guide/genetic-tests/","a":"b667","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"劣性遺伝の項目は、おおむね次の3区分です。","u":"guide/genetic-tests/","a":"b668","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"クリア／ノーマル ：対象の変異を持たない","u":"guide/genetic-tests/","a":"b669","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"キャリア／保因 ：対象の変異を1つ持つ","u":"guide/genetic-tests/","a":"b670","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"アフェクテッド／発症の可能性あり ：対象の変異を2つ持つ","u":"guide/genetic-tests/","a":"b671","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"多くの常染色体劣性疾患では、キャリアは発症しません。ただしMDR1では、変異を1つ持つ犬も一部の抗がん剤による副作用が増えた報告があります。この研究はシェルティだけを対象にしたものではありませんが、同じABCB1変異を持つ犬の薬剤反応として参照しています。これは抗がん剤や高用量薬の話であり、獣医師の指示どおりに使うフィラリア予防薬とは分けて考えます。","u":"guide/genetic-tests/","a":"b672","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"3. 目は遺伝子検査と眼科検査の役割を分ける","u":"guide/genetic-tests/","a":"b673","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"コリー眼異常（CEA。目の奥にある脈絡膜の発育が不十分になる病気）の遺伝子検査は、シェルティでは有用です。ただし所見の重さや視覚への影響までは分かりません。成長後には軽い所見が見えにくくなるため、子犬期の眼科検査にも別の価値があります。","u":"guide/genetic-tests/","a":"b674","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"4. 追加パネルは、解釈する相手を決めてから買う","u":"guide/genetic-tests/","a":"b675","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"多項目パネルには、シェルティで意味や浸透率（変異を持つ犬のうち発症する割合）が十分に確かめられていない項目があります。「アフェクテッド」も必ず発症するという意味ではありません。何を変えるために調べるのか、誰に相談するのかを先に決めてください。誤読が不要な不安や受診につながるという部分は、 これは経験則です 。","u":"guide/genetic-tests/","a":"b676","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"5. 別会社の結果は検査名だけで比べない","u":"guide/genetic-tests/","a":"b677","e":0},{"c":"8","n":"遺伝子検査について","s":"実際にどうするか","t":"同じ病名でも対象変異や判定基準が異なることがあります。結果が食い違うときは、対象変異と検査法を確認してもらってください。","u":"guide/genetic-tests/","a":"b678","e":0},{"c":"8","n":"遺伝子検査について","s":"こんなときは受診を","t":"検査結果にかかわらず、傷や抜歯のあとに出血が止まりにくい","u":"guide/genetic-tests/","a":"b679","e":0},{"c":"8","n":"遺伝子検査について","s":"こんなときは受診を","t":"顔、耳の先、足先などに、かさぶたや脱毛が現れた","u":"guide/genetic-tests/","a":"b680","e":0},{"c":"8","n":"遺伝子検査について","s":"こんなときは受診を","t":"見えにくそう、物にぶつかる、目の様子がいつもと違う","u":"guide/genetic-tests/","a":"b681","e":0},{"c":"8","n":"遺伝子検査について","s":"こんなときは受診を","t":"パネルで「発症の可能性あり」「高リスク」と出たが、意味が分からない","u":"guide/genetic-tests/","a":"b682","e":0},{"c":"8","n":"遺伝子検査について","s":"こんなときは受診を","t":"遺伝子検査だけで診断したり、薬を中止したりしないでください。","u":"guide/genetic-tests/","a":"b683","e":0},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"1. コリー眼異常","u":"guide/genetic-tests/","a":"b684","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Parkerら（2007）は、コリー眼異常に関連するNHEJ1領域の約7,800塩基の欠失を、シェルティを含む複数犬種で確認しました。Fredholmら（2016）は、デンマークのシェルティでは遺伝子型と脈絡膜低形成の眼底所見が一致した一方、ラフ・コリーでは一致しないと報告しました。後者は、検査対象が原因そのものではなく、原因と連鎖した目印である可能性を示します。","u":"guide/genetic-tests/","a":"b685","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"この結果は、シェルティで検査が有用であることを支持しますが、眼底所見の重さや視覚への影響まで予測するものではありません。コロボーマ（眼球の組織の一部が欠ける変化）との対応も完全ではなく、成長後に軽い所見が隠れることがあります。したがって、遺伝子検査と子犬期の眼科検査は役割が異なります。","u":"guide/genetic-tests/","a":"b686","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Marelliら（2022）がイタリアの検査提出犬74頭で報告した変異頻度は、一般の家庭犬を無作為に調べた値ではありません。国や集団で頻度が大きく異なるため、目の前の1頭の判断には用いません。","u":"guide/genetic-tests/","a":"b687","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"2. 皮膚筋炎のリスク検査","u":"guide/genetic-tests/","a":"b688","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Evansら（2017）は、コリーとシェルティの症例132頭、対照390頭を用い、3領域の組み合わせと皮膚筋炎の関連を報告しました。研究集団では低・中・高リスク群で発症割合が異なりましたが、症例対照研究内の割合を、日本のシェルティ1頭の発症確率としては使えません。リスクとされた配列は、皮膚筋炎を発症しない他犬種にも存在しました。","u":"guide/genetic-tests/","a":"b689","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"同論文は感染や環境変化などが発症の引き金になりうると論じていますが、因果関係を前向きに検証した研究ではありません。この結果から、ワクチンなど特定の医療を避けることは勧められません。","u":"guide/genetic-tests/","a":"b690","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"3. 変性性脊髄症","u":"guide/genetic-tests/","a":"b691","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Zengら（2014）は222犬種33,747頭を調べ、変性性脊髄症（後ろ足から進む神経の病気）に関連するSOD1変異が124犬種と雑種に広く分布することを示しました。変異を2つ持つ犬は高リスクですが、遺伝子型だけでは発症の有無や時期を確定できません。これは、多項目パネルの「アフェクテッド」を診断と同じに扱えない例です。","u":"guide/genetic-tests/","a":"b692","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"4. MDR1と薬剤反応","u":"guide/genetic-tests/","a":"b693","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Mealeyら（2008）は、リンパ腫の犬34頭を前向きに調べ、ABCB1変異を1つまたは2つ持つ犬では、ビンクリスチンによる好中球減少と血小板減少が、変異を持たない犬より多いと報告しました。小規模で犬種も限られますが、キャリアも薬剤選択時に共有すべきことを示す直接的な臨床データです。","u":"guide/genetic-tests/","a":"b694","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"一方、この知見を予防用量の駆虫薬へ一般化することはできません。薬剤と用量域を分ける必要があります。","u":"guide/genetic-tests/","a":"b695","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"5. フォン・ヴィレブランド病","u":"guide/genetic-tests/","a":"b696","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"シェルティの3型に関連するVWF遺伝子の1塩基欠失について、元稿で引用していたRiegerら（1998）は別犬種の別変異を扱った論文であり、シェルティの一次資料ではありません。シェルティの変異の初期資料は査読論文ではなく米国特許です。さらに、変異の表記は資料間で統一されていません。","u":"guide/genetic-tests/","a":"b697","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Raymondら（1990）は、検査施設へ提出された6,000頭超のシェルティで、より軽い量的低下型を報告しました。ただし選択された集団であり、一般集団の有病率とは読めません。3型の遺伝子検査がクリアでも、別の仕組みによる凝固因子低下を除外しない、という点を本文に反映しました。","u":"guide/genetic-tests/","a":"b698","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"6. 推奨の確実性と限界","u":"guide/genetic-tests/","a":"b699","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"結果表の共有が転帰を改善するかを直接比較した研究はありません。推奨1は、MDR1など診療判断を変えうる遺伝子型が存在するという直接的根拠と、低負担の情報共有を結びつけたものです。シェルティ固有の改善効果は測定されていないため、シェルティでどれだけ役立つかの確かさは低としました。","u":"guide/genetic-tests/","a":"b700","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"推奨2について、「パネルを買わないほうが健康転帰に優れる」という比較研究はありません。犬種をまたぐ解釈、発症率、検査会社間の精度も十分には検証されていません。したがって方向性は低、シェルティでどれだけ役立つかの確かさは非常に低としました。","u":"guide/genetic-tests/","a":"b701","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"都合の悪い結果として、コリー眼異常の検査はシェルティで眼底所見との一致が良好であり、追加検査がすべて無価値という根拠にはなりません。また、変性性脊髄症ではヘテロ接合でも発症例が報告され、「キャリアはすべて無関係」とも一般化できません。検査項目ごとに解釈する必要があります。","u":"guide/genetic-tests/","a":"b702","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"日本のシェルティ集団を対象とした頻度・予後データ、市販パネルを項目ごとに独立検証した資料、検査会社間の精度比較はいずれも不足しています。","u":"guide/genetic-tests/","a":"b703","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"参考文献","u":"guide/genetic-tests/","a":"b704","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Parker HG, et al. Genome Res. 2007;17:1562-1571.","u":"guide/genetic-tests/","a":"b705","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Fredholm M, et al. Anim Genet. 2016;47:250-252.","u":"guide/genetic-tests/","a":"b706","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Marelli SP, et al. Vet Rec Open. 2022;9:e26.","u":"guide/genetic-tests/","a":"b707","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Evans JM, et al. PLoS Genet. 2017;13:e1006604.","u":"guide/genetic-tests/","a":"b708","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Zeng R, et al. J Vet Intern Med. 2014;28:515-521.","u":"guide/genetic-tests/","a":"b709","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Mealey KL, et al. J Vet Intern Med. 2008;22:996-1000.","u":"guide/genetic-tests/","a":"b710","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"Raymond SL, Jones DW, Brooks MB, Dodds WJ. J Am Vet Med Assoc. 1990;197(10):1342-1346.","u":"guide/genetic-tests/","a":"b711","e":1},{"c":"8","n":"遺伝子検査について","s":"根拠","t":"World Small Animal Veterinary Association Hereditary Disease Committee / PennGen database.","u":"guide/genetic-tests/","a":"b712","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"この章が扱う範囲","t":"シェルティで注意したい目、甲状腺、皮膚の病気を扱います。飼い主が診断するための章ではありません。「暗い場所で動きにくい」「毛や皮膚が変わった」と気づいたとき、何を記録し、いつ受診するかを示します。","u":"guide/eyes-thyroid-skin/","a":"b713","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"推奨1 甲状腺","u":"guide/eyes-thyroid-skin/","a":"b714","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"症状のない犬に、甲状腺機能低下症を探すためだけの血液検査を勧めません。症状があって検査する場合も、総サイロキシン（甲状腺ホルモンの一種。以下、総T4）が低いという結果だけで治療を始めないでください。","u":"guide/eyes-thyroid-skin/","a":"b715","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"推奨2 若い犬の皮膚","u":"guide/eyes-thyroid-skin/","a":"b716","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"特に1歳未満で、顔、耳の縁、尾の先、脚の骨が出っ張った部分に、フケ、かさぶた、脱毛が出たら、写真を撮って受診してください。","u":"guide/eyes-thyroid-skin/","a":"b717","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"推奨3 目","u":"guide/eyes-thyroid-skin/","a":"b718","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"迎えて落ち着いた頃に一度、瞳孔を薬で広げる検査を含め、眼底（眼球の奥）まで診られる獣医師による眼科検査を受け、結果を残しておくことを提案します。","u":"guide/eyes-thyroid-skin/","a":"b719","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"この章の推奨","t":"推奨を分けたのは、目では無症状のうちに見つけても対応が変わらない病気がある一方、甲状腺では過剰診断を避けること、皮膚では変化を見逃さず受診することが主な目的だからです。推奨1と2を強くした根拠は研究の量ではなく、不要な長期治療や戻らない病変を避ける必要性と、推奨する行動の害の小ささです。","u":"guide/eyes-thyroid-skin/","a":"b720","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"コリー眼異常は、眼球の奥の組織が十分に育たない生まれつきの病気です。基本の病変は進行しませんが、重い型では網膜剥離や眼内出血により視覚を失うことがあります。軽い所見は、成長とともに眼底の色素に隠れて見えにくくなることがあります。","u":"guide/eyes-thyroid-skin/","a":"b721","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"進行性網膜萎縮は、光を感じる網膜の細胞が徐々に壊れる病気です。初期には暗い場所で見えにくくなります。シェルティではCNGA1という遺伝子の変異が報告されていますが、別の原因による病気もあるため、この変異が陰性でもすべての進行性網膜萎縮を否定できません。","u":"guide/eyes-thyroid-skin/","a":"b722","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"遺伝子検査は眼科検査の代わりにはなりません。一方、これらの遺伝性疾患は、無症状の段階で発見しても治療が変わらないことがあります。このため、健康な家庭犬の眼科検査は強い推奨ではなく提案としました。","u":"guide/eyes-thyroid-skin/","a":"b723","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"甲状腺","u":"guide/eyes-thyroid-skin/","a":"b724","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"甲状腺機能低下症では、左右対称の脱毛、毛づやの低下、体重増加、寒がる、動きたがらないなどが組み合わさって現れます。ただし、どれも単独では別の原因でも起こります。","u":"guide/eyes-thyroid-skin/","a":"b725","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"英国の一次診療データでは、診断された割合は全犬種で0.23%、シェルティで1.92%でした。ただしシェルティは24例で、この数字は真の発症率ではなく、過剰診断を含む可能性があります。","u":"guide/eyes-thyroid-skin/","a":"b726","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"総T4は、甲状腺以外の病気や薬の影響でも低下します。治療中の犬102頭を専門医3人が再評価した研究では、投薬が適切でないと判断された割合は45.1～58.8%でした。ただし評価者間の一致は十分ではなく、個々の犬の投薬が不要だったと証明した研究ではありません。それでも、総T4だけで診断しない理由になります。","u":"guide/eyes-thyroid-skin/","a":"b727","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"診断では、症状、総T4、遊離T4、甲状腺刺激ホルモン、併存する病気、薬を合わせて判断します。検査を増やしても一つの値だけでは確定できません。","u":"guide/eyes-thyroid-skin/","a":"b728","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"この診断手順は、シェルティだけを対象にした研究ではなく、犬全体のガイドラインと複数犬種の研究に基づきます。","u":"guide/eyes-thyroid-skin/","a":"b729","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"皮膚","u":"guide/eyes-thyroid-skin/","a":"b730","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"皮膚筋炎（皮膚や筋肉の細い血管に炎症が起こる病気）は、コリーとシェルティで知られています。若い時期に、顔、耳、尾の先、脚の骨が出っ張った部分へフケ、かさぶた、脱毛が出るのが典型です。筋肉にも及ぶと、食べにくい、飲み込みにくい、歩き方がおかしいといった変化が出ます。","u":"guide/eyes-thyroid-skin/","a":"b731","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"摩擦、紫外線、発情、ワクチン接種、感染、環境変化がきっかけとして挙げられますが、これは症例報告と臨床経験に基づく推測です。 これは経験則です 。 症状のない犬で、紫外線や摩擦を避ければ発症を防げると示した比較研究はありません。","u":"guide/eyes-thyroid-skin/","a":"b732","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"成犬では、水疱性皮膚エリテマトーデスという免疫の病気も報告されています。夏に始まることが多く、脇、下腹部、脚の付け根など毛の薄い場所に、痛みを伴うただれができます。発症後は紫外線を避けることが管理の一部ですが、発症予防の効果は確認されていません。","u":"guide/eyes-thyroid-skin/","a":"b733","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"なぜこれが重要か","t":"ブルーマールは、黒や茶の色素が全身で薄くなる「希釈毛色」とは別の仕組みです。ブルーマールであること自体は、希釈毛色に伴う脱毛症の危険を意味しません。","u":"guide/eyes-thyroid-skin/","a":"b734","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"実際にどうするか","t":"月1回の体重測定に合わせ、顔、耳の縁、脇、腹、尾の先、脚の骨ばった部分を見ます。","u":"guide/eyes-thyroid-skin/","a":"b735","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"実際にどうするか","t":"変化を見つけたら、日付が分かる形で、全体と近接の写真を同じ明るさ・角度で撮ります。","u":"guide/eyes-thyroid-skin/","a":"b736","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"実際にどうするか","t":"夜の散歩や薄暗い部屋で、ぶつかる、段差を嫌がる、動きたがらない変化がないか見ます。","u":"guide/eyes-thyroid-skin/","a":"b737","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"実際にどうするか","t":"ワクチンの日付と接種部位を記録し、その場所の脱毛や色の変化を受診時に伝えます。これは接種を避けるという意味ではありません。","u":"guide/eyes-thyroid-skin/","a":"b738","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"実際にどうするか","t":"甲状腺の検査では、症状、服薬、ほかの病気を獣医師に伝え、総T4だけで判断されていないか確認します。","u":"guide/eyes-thyroid-skin/","a":"b739","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"こんなときは受診を","t":"今すぐ（夜間・休日でも）連絡： 急に見えなくなった、眼を強く痛がる、眼が急に濁った、白目が強く赤い。","u":"guide/eyes-thyroid-skin/","a":"b740","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"こんなときは受診を","t":"その日のうちに連絡： 食べ物や水を飲み込みにくい、食後にむせる、急に歩きにくくなった。","u":"guide/eyes-thyroid-skin/","a":"b741","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"こんなときは受診を","t":"早めに予約： 暗い場所でぶつかる、左右対称の脱毛、かゆみの乏しい脱毛、若い犬の顔・耳・尾・脚のかさぶた、夏に脇や腹へ痛そうなただれが出た、ワクチン接種部位の脱毛や色の変化が続く。","u":"guide/eyes-thyroid-skin/","a":"b742","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"こんなときは受診を","t":"緊急時は撮影より連絡を優先してください。","u":"guide/eyes-thyroid-skin/","a":"b743","e":0},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Parker HG, et al. Genome Res. 2007;17:1562-1571. コリー眼異常に関連するNHEJ1遺伝子領域の欠失を、シェルティを含む複数犬種で同定した。関連変異であり、眼科所見の重さを直接示す検査ではない。","u":"guide/eyes-thyroid-skin/","a":"b744","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Fredholm M, et al. Anim Genet. 2016;47:250-252. デンマークのシェルティでは遺伝子型と脈絡膜低形成の眼科所見が一致した一方、ラフコリーでは一致しなかった。限られた集団の結果であり、他集団への一般化には注意が要る。","u":"guide/eyes-thyroid-skin/","a":"b745","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Wiik AC, et al. Anim Genet. 2015;46:515-521. 発症15頭、対照14頭から、進行性網膜萎縮に関連するCNGA1変異を同定した。論文自身が一部の家系には別の原因がある可能性を述べている。症例数も小さい。","u":"guide/eyes-thyroid-skin/","a":"b746","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Karlstam L, et al. Vet Ophthalmol. 2011;14:227-238. スウェーデンの罹患シェルティ40頭と健常シェルティ6頭を調べ、ゆっくり進む別型の網膜症を報告した。単一の遺伝子検査ですべての網膜疾患を除外できない、シェルティでの直接的な根拠とした。","u":"guide/eyes-thyroid-skin/","a":"b747","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"コリー眼異常関連変異の頻度は、イタリア74頭で保因50%、発症型ホモ接合10.8%だった一方、タイでは保因3.3%、ホモ接合1.1%だった。集団差が大きく、海外の数字を日本の個体へ直接当てはめられない。古いオランダの120頭では眼科所見が48%超だったが、1979年の集団であり現在の頻度には使えない。","u":"guide/eyes-thyroid-skin/","a":"b748","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"無症状犬の眼科検査によって、家庭犬の視覚や生活の質が改善するかを比較したシェルティの研究は確認できなかった。検査で白内障、緑内障など対応が変わる別の所見を見つける可能性と、基準点を残す利益はあるが、犬種別の効果量は不明である。このため提案にとどめた。","u":"guide/eyes-thyroid-skin/","a":"b749","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"甲状腺","u":"guide/eyes-thyroid-skin/","a":"b750","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"American Animal Hospital Association. 2023 AAHA Selected Endocrinopathies of Dogs and Cats Guidelines. J Am Anim Hosp Assoc. 2023;59:113-135. 総T4低値だけを診断根拠にせず、症状の有無、遊離T4、甲状腺刺激ホルモン、非甲状腺疾患、薬剤を合わせて判断するよう求める。甲状腺機能低下症でも約20～40%は甲状腺刺激ホルモンが基準内にあるため、追加検査一つでも白黒はつかない。合意に基づくガイドラインで、系統的レビューではない。","u":"guide/eyes-thyroid-skin/","a":"b751","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"O'Neill DG, et al. Canine Med Genet. 2022;9:11. 英国の一次診療905,553頭における2016年の診断有病率は全体0.23%。シェルティは1.92%、雑種犬に対する多変量オッズ比8.25だった。ただしシェルティは24例で、診断有病率は真の有病率ではない。","u":"guide/eyes-thyroid-skin/","a":"b752","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Travail V, et al. J Vet Intern Med. 2024;38:931-941. 治療中102頭を専門医3人が独立再評価し、投薬不適切との判定は45.1%、52.9%、58.8%。3人の完全一致は65.7%で、評価者間一致は低～中程度だった。不要な治療の可能性を示すが、各症例の誤診を証明しない。","u":"guide/eyes-thyroid-skin/","a":"b753","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"総T4の感度は89～100%、特異度は73～82%と報告され、非甲状腺疾患や薬剤でも低下する。薬剤影響の総説は Bolton TA, Panciera DL. J Vet Intern Med. 2023;37:1626-1640. を参照した。","u":"guide/eyes-thyroid-skin/","a":"b754","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Hegstad-Davies RL, et al. J Vet Diagn Invest. 2015;27:716-727. 7犬種693頭で犬種別の基準範囲の違いを示したが、シェルティは対象外だった。近縁のコリーからシェルティへの外挿であり、シェルティ固有の基準値の根拠にはしていない。","u":"guide/eyes-thyroid-skin/","a":"b755","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"行動との関係は一致しない。家族への攻撃行動の有無で甲状腺指標に差がなかった研究、境界値の犬への短期間の無作為化試験で攻撃行動が減った研究、診断された20頭を6か月追跡して行動指標に有意差がなかった研究がある。陽性結果も落とさず記載したが、吠えや怖がりだけを理由に検査・投薬する根拠としては不足すると判断した。","u":"guide/eyes-thyroid-skin/","a":"b756","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"皮膚","u":"guide/eyes-thyroid-skin/","a":"b757","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Evans JM, et al. PLoS Genet. 2017;13:e1006604. コリーとシェルティの症例・対照研究で、PAN2、MAP3K7CL、犬白血球抗原の型の組合せと皮膚筋炎リスクの関連を示した。高リスクの組合せで発症が多かったが、遺伝子型だけで個体の発症を確定できず、誘因を避ける効果も検証していない。","u":"guide/eyes-thyroid-skin/","a":"b758","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Ferguson EA, et al. Vet Rec. 2000;146:214-217. 英国のシェルティ5頭の症例集積。犬種での臨床像を支えるが、早期受診の効果量は示さない。","u":"guide/eyes-thyroid-skin/","a":"b759","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Backel KA, et al. Vet Dermatol. 2019;30:403-e122. 家族性皮膚筋炎を除外した虚血性皮膚症177例の48.3%で、ワクチンとの関連が「ありそう」と判定された。ただし多かったのはトイ犬種で、シェルティの頻度や因果関係を示す研究ではない。","u":"guide/eyes-thyroid-skin/","a":"b760","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Jackson HA, Olivry T. Vet Dermatol. 2001;12:19-27. シェルティとラフコリーにみられる潰瘍性皮膚疾患を、水疱性皮膚エリテマトーデスとして整理した報告。","u":"guide/eyes-thyroid-skin/","a":"b761","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"Jackson HA. Vet Dermatol. 2004;15:37-41. 11頭中8頭が夏に発症し、8頭は治療で75～100%管理できた一方、3頭は重い転帰をたどった。11例の後ろ向き報告であり、頻度・予後・治療効果を一般化できない。紫外線回避で発症や再燃が減るかを検証した比較研究は確認できなかった。","u":"guide/eyes-thyroid-skin/","a":"b762","e":1},{"c":"9","n":"目・甲状腺・皮膚","s":"根拠","t":"皮膚筋炎を早く発見することで予後が改善するかを示す比較研究も確認できなかった。推奨2を強くしたのは、病変が続けば傷あとや脱毛が残り、飲み込みに関わる筋肉へ及ぶことがある一方、写真記録と受診の害が小さいためである。","u":"guide/eyes-thyroid-skin/","a":"b763","e":1},{"c":"10","n":"跛行が出たときの見方","s":"この章が扱う範囲","t":"跛行（はこう。足をかばったり、着き方が左右で違ったりする歩き方）に気づいたとき、家で何を観察し、何をしないで、いつ受診するかを扱います。","u":"guide/limping/","a":"b764","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章が扱う範囲","t":"病名を当てる章ではありません。跛行には整形外科だけでなく神経の病気も含まれ、見た目だけで原因部位や病名を決めることはできません。","u":"guide/limping/","a":"b765","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"推奨1","u":"guide/limping/","a":"b766","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"跛行に気づいたら、原因や重症度を見た目だけで決めず、いつ始まったか・どう変化したかを記録し、歩ける範囲で自然な歩行を動画に残してください。","u":"guide/limping/","a":"b767","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"推奨2","u":"guide/limping/","a":"b768","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"家で原因部位を探したり、跛行を再現するために走らせたりしないでください。外傷後や急に立てない場合は、夜間・休日でも今すぐ動物病院へ連絡してください。足をほとんど着かない、強く痛がる、腫れを伴う場合は、その日のうちに連絡してください。軽くても繰り返す場合は、数日のうちに予約してください。","u":"guide/limping/","a":"b769","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"この2つを分けたのは、診察に役立つ情報を残すことと、自己判断による悪化や受診の遅れを避けることが別のアウトカムだからです。どちらも強い推奨ですが、強さの根拠は研究の量ではなく、害の小ささと必要性です。","u":"guide/limping/","a":"b770","e":0},{"c":"10","n":"跛行が出たときの見方","s":"この章の推奨","t":"この章の研究のほとんどはシェルティ以外の犬で行われています。 見た目による跛行評価の限界は犬種をまたいで成り立つと考えますが、これらの行動でシェルティの診断や予後がどれだけ改善するかは分かりません。","u":"guide/limping/","a":"b771","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"「どのくらい跛行しているか」は、見た目ほど簡単ではない","u":"guide/limping/","a":"b772","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"跛行を動画で見た獣医師どうしでも、軽い跛行の評価はかなりずれます。フォースプレート（足が地面に加える力を測る装置）と比べると、主観的な点数との一致は低く、特に軽い跛行では不一致が大きくなりました。","u":"guide/limping/","a":"b773","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"「少ししか引きずっていないから軽い」と考えて、受診を遅らせる根拠にはしないでください。","u":"guide/limping/","a":"b774","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"動画は「診断」ではなく「そのときの状態を持っていく」ため","u":"guide/limping/","a":"b775","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"跛行は診察時に再現しないことがあります。動画の役割は、家で起きていた状態を獣医師に見せることです。","u":"guide/limping/","a":"b776","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"ただし、動画をスロー再生すれば診断精度が上がるわけではありません。経験のある獣医師3人が犬30頭の歩行・速歩動画を判定した研究では、50%のスロー再生にしても、跛行の程度や患肢を判断する正確さ・一致度は改善しませんでした。動画だけで病変部位を決めないことも同じくらい重要です。","u":"guide/limping/","a":"b777","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"X線の変化と「いまどれだけ使えているか」は同じではない","u":"guide/limping/","a":"b778","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"変形性関節症（OA。関節の変性に伴って痛みや動きにくさが出る病気）では、画像の変化と歩行機能が一致しないことがあります。膝のOAがある41頭では、X線上のOAスコアとフォースプレートで測った肢の機能に有意な関係がありませんでした。","u":"guide/limping/","a":"b779","e":0},{"c":"10","n":"跛行が出たときの見方","s":"なぜこれが重要か","t":"したがって、 「X線が軽いから痛くない」「X線がひどいからこの跛行の原因はそこ」とは決められません。 画像は診察所見と合わせて読みます。","u":"guide/limping/","a":"b780","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"1. まず止めて、状況を記録する","u":"guide/limping/","a":"b781","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"激しい運動は中止し、次をメモしてください。","u":"guide/limping/","a":"b782","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"外傷後や急に立てない場合は、記録より連絡を優先してください。","u":"guide/limping/","a":"b783","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"いつ始まったか。突然か、徐々にか","u":"guide/limping/","a":"b784","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"直前に走った、跳んだ、滑った、ぶつかったなどがあったか","u":"guide/limping/","a":"b785","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"ずっと同じか、良くなったり悪くなったりするか","u":"guide/limping/","a":"b786","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"起床直後、運動後など、出やすい時間があるか","u":"guide/limping/","a":"b787","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"1本の肢だけか、左右が入れ替わるように見えるか","u":"guide/limping/","a":"b788","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"食欲、元気、発熱感など、歩行以外の変化があるか","u":"guide/limping/","a":"b789","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"病名を絞るためではなく、診察時に伝えるための記録です。","u":"guide/limping/","a":"b790","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"2. 動画は「普通に歩いているところ」を撮る","u":"guide/limping/","a":"b791","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"平坦で滑りにくい場所を普段の速度で歩かせ、横・前・後ろから全身を撮ります。","u":"guide/limping/","a":"b792","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"速く歩かせたり、走らせたりしないでください。 足をほとんど着けない、強く痛がる、歩くのがつらそうなら撮影は不要です。外傷後や立てない場合は、撮影より連絡を優先してください。","u":"guide/limping/","a":"b793","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"3. 家で「診察」をしない","u":"guide/limping/","a":"b794","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"左右の足先に傷や異物がないかを目で確認する程度にとどめてください。関節を強く曲げ伸ばしする、腫れている場所を押す、何度も歩かせて再現させることは勧めません。 これは経験則です 。 診断に必要な整形外科的な操作は、反応を見ながら獣医師が行います。","u":"guide/limping/","a":"b795","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"人用の鎮痛薬や、以前ほかの犬に処方された薬を自己判断で与えないでください。薬の扱いは 11章 「受診の目安」に譲ります。","u":"guide/limping/","a":"b796","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"4. 「治った」も記録する","u":"guide/limping/","a":"b797","e":0},{"c":"10","n":"跛行が出たときの見方","s":"実際にどうするか","t":"普通に戻っても、繰り返すなら動画と日時を残してください。","u":"guide/limping/","a":"b798","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"以下の区分は、臨床で使うための実務的な整理であり、時間の境界を比較試験で決めたものではありません。 これは経験則です 。","u":"guide/limping/","a":"b799","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"今すぐ連絡（夜間・休日でも）","u":"guide/limping/","a":"b800","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"交通事故、転落、強い衝突のあと","u":"guide/limping/","a":"b801","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"急に立てない、後肢が動かない","u":"guide/limping/","a":"b802","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"その日のうちに連絡","u":"guide/limping/","a":"b803","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"足をほとんど着かない","u":"guide/limping/","a":"b804","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"急に強く痛がる、鳴く","u":"guide/limping/","a":"b805","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"急に腫れ、跛行を伴う","u":"guide/limping/","a":"b806","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"歩様の異常に加えて、ふらつく、足先を引きずるなどがある","u":"guide/limping/","a":"b807","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"跛行に加えて、元気や食欲がない、熱っぽい","u":"guide/limping/","a":"b808","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"数日のうちに予約","u":"guide/limping/","a":"b809","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"軽くても跛行が繰り返す","u":"guide/limping/","a":"b810","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"歩き方、座り方、立ち上がり方の変化が続く","u":"guide/limping/","a":"b811","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"一度は良くなるが、運動のたびに再発する","u":"guide/limping/","a":"b812","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"複数の肢が悪そうに見える、または日によって場所が変わる","u":"guide/limping/","a":"b813","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"飛節周囲の腫れを伴った跛行が、いったん治まった","u":"guide/limping/","a":"b814","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"シェルティで知っておきたい所見","u":"guide/limping/","a":"b815","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"飛節（ホック。後肢のかかとにあたる部分）の後ろを通る浅指屈筋腱（せんしくっきんけん）の脱臼は、シェルティで繰り返し報告されています。古い症例集積では10肢中4肢がシェルティで、別の手術症例集積では19頭中14頭がシェルティでした。","u":"guide/limping/","a":"b816","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"ただし、これらは受診した症例の集積で、シェルティ全体の発症率を示す数字ではありません。「シェルティだからこの病気」と診断することはできません。","u":"guide/limping/","a":"b817","e":0},{"c":"10","n":"跛行が出たときの見方","s":"こんなときは受診を","t":"急な後肢跛行に飛節周囲の腫れが伴う、または強い跛行がいったん治まって繰り返す場合は、受診時にその経過を伝えてください。 自分で腱を動かして確かめないでください。","u":"guide/limping/","a":"b818","e":0},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"1. 見た目による跛行評価の限界","u":"guide/limping/","a":"b819","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Quinn MM, Keuler NS, Lu Y, Faria MLE, Muir P, Markel MD. Evaluation of agreement between numerical rating scales, visual analogue scoring scales, and force plate gait analysis in dogs. Vet Surg. 2007;36:360-367. doi:10.1111/j.1532-950X.2007.00276.x.","u":"guide/limping/","a":"b820","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"脛骨骨切り術後の雑種犬21頭を、整形外科の訓練を受けた獣医師3人が評価。主観的な跛行スコアの観察者間一致は概して低く、非常に強い跛行を除くとフォースプレートとの関係も乏しくなりました。 「獣医師でも見た目だけでは軽い跛行を安定して定量できない」 ことの根拠です。","u":"guide/limping/","a":"b821","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Waxman AS, Robinson DA, Evans RB, Hulse DA, Innes JF, Conzemius MG. Relationship between objective and subjective assessment of limb function in normal dogs with an experimentally induced lameness. Vet Surg. 2008;37:241-246. doi:10.1111/j.1532-950X.2008.00372.x.","u":"guide/limping/","a":"b822","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"実験的に跛行を作った犬24頭の動画60試行を、整形外科医3人と獣医学生3人が評価。主観評価とフォースプレートの一致は低く、正常歩行と完全な非荷重歩行を除くとさらに低下しました。整形外科医は学生より再評価時の再現性は高かったものの、客観評価との一致が良いわけではありませんでした。","u":"guide/limping/","a":"b823","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"2. 動画の限界","u":"guide/limping/","a":"b824","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Lane DM, Hill SA, Huntingford JL, Lafuente P, Wall R, Jones KA. Effectiveness of slow motion video compared to real time video in improving the accuracy and consistency of subjective gait analysis in dogs. Open Vet J. 2015;5:158-165.","u":"guide/limping/","a":"b825","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"犬30頭（跛行15頭、対照15頭）の歩行と速歩を、経験のある獣医師3人が通常速度と50%スローで評価。 スロー再生にしても、跛行の程度・患肢を判断する正確さや一致度は有意に改善しませんでした。 動画撮影そのものが診断成績を改善するかを検証した研究ではない点が重要です。本章で動画を勧める根拠は、診察時に消えている所見を記録として持参できるという実用性であり、診断精度を上げることが実証されたからではありません。","u":"guide/limping/","a":"b826","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"3. 画像所見と機能","u":"guide/limping/","a":"b827","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Gordon WJ, Conzemius MG, Riedesel E, et al. The relationship between limb function and radiographic osteoarthrosis in dogs with stifle osteoarthrosis. Vet Surg. 2003;32:451-454. doi:10.1053/jvet.2003.50051.","u":"guide/limping/","a":"b828","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"跛行と膝OAのX線所見をもつ41頭で、X線のOAスコアとフォースプレートによる肢機能に有意な関係はありませんでした。画像上の変化を、そのまま痛みや機能低下の大きさとして読めないことを示します。","u":"guide/limping/","a":"b829","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"都合の悪い結果。 Rhee B, et al. Lab Anim Res. 2023;39:34では、前十字靱帯を切離してOAを作ったビーグルの実験モデルで、X線・CTの重症度と触診・歩様評価に強い正の相関が報告されています。自然発症の臨床例ではないこと、独自の画像評価基準を検証する研究であることからGordonらと条件が違います。したがって本章は「画像と症状は一致しない」と一般化せず、一致しないことがあるとしています。","u":"guide/limping/","a":"b830","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"4. シェルティの浅指屈筋腱脱臼","u":"guide/limping/","a":"b831","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Mauterer JV Jr, Prata RG, Carberry CA, Schrader SC. Displacement of the tendon of the superficial digital flexor muscle in dogs: 10 cases (1983-1991). J Am Vet Med Assoc. 1993;203:1162-1165.","u":"guide/limping/","a":"b832","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"9頭10飛節の症例集積で、4肢がシェルティ。全例が急性の跛行と踵骨隆起付近の腫脹で受診し、保存治療を試みた5頭では有効ではありませんでした。症例数が少なく、犬種別発症率は算出できません。","u":"guide/limping/","a":"b833","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"Jury A. Surgical repair for luxation of the superficial digital flexor tendon using a temporary restraining pin. J Small Anim Pract. 2021;62:272-278. doi:10.1111/jsap.13288.","u":"guide/limping/","a":"b834","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"1施設の後ろ向き症例集積で19頭23手術、14頭がシェルティ。最終的には全例が受傷前の活動レベルに戻りましたが、軽度合併症35%、予定外の再手術を要する重大な合併症13%が報告されています。治療成績の研究であり、シェルティの発症頻度を示す研究ではありません。","u":"guide/limping/","a":"b835","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"確実性の評価","u":"guide/limping/","a":"b836","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"推奨1の良い方向に働くことの確かさを「低」としたのは、主観的歩様評価の限界は複数研究で確認されている一方、飼い主が動画と経過を記録することで診断や予後が改善するかを直接比較した研究がないためです。","u":"guide/limping/","a":"b837","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"推奨2も「低」です。自宅での関節操作を避けることや、受診時期の区分を直接検証した研究はありません。強い推奨にしたのは、軽い跛行を見た目だけで安全と判断する利益が乏しい一方、診察に返すことの害が小さいためです。","u":"guide/limping/","a":"b838","e":1},{"c":"10","n":"跛行が出たときの見方","s":"根拠","t":"シェルティでどれだけ役立つかの確かさはいずれも「非常に低」。 浅指屈筋腱脱臼を除けば、本章の行動介入をシェルティで検証した研究はありません。浅指屈筋腱の症例集積も、犬種内の発症率や、早期受診が治療成績をどれだけ変えるかは示していません。","u":"guide/limping/","a":"b839","e":1},{"c":"11","n":"受診の目安","s":"この章で扱う範囲","t":"この章では、犬の様子がいつもと違うときの緊急度の判断と、動物病院への伝え方を扱います。病名を推測したり、家庭で診断・治療したりするための章ではありません。","u":"guide/when-to-call/","a":"b840","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"推奨1","u":"guide/when-to-call/","a":"b841","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"何の病気かを言い当てようとせず、「いつ診てもらうか」だけを決めてください。判断に迷ったら、様子を見る前に、かかりつけの動物病院へ電話してください。","u":"guide/when-to-call/","a":"b842","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"推奨2","u":"guide/when-to-call/","a":"b843","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"熱中症が疑われるときは、その場で水をかけて風を当てる冷却を始め、冷やしながら動物病院へ連絡し、搬送してください。","u":"guide/when-to-call/","a":"b844","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"2つに分けたのは、通常は電話で緊急度を確認することが先ですが、熱中症では冷却開始の遅れ自体が害になりうるからです。どちらも強い推奨ですが、 強さの根拠は研究の量ではなく、害の小ささと必要性です。","u":"guide/when-to-call/","a":"b845","e":0},{"c":"11","n":"受診の目安","s":"この章の推奨","t":"飼い主の受診判断や熱中症の研究は、ほぼすべてシェルティ以外を含む犬全体のデータです。 方向性は犬種をまたいで成り立つと考えますが、シェルティで結果がどれほど改善するかは分かりません。","u":"guide/when-to-call/","a":"b846","e":0},{"c":"11","n":"受診の目安","s":"なぜこれが重要か","t":"英国の飼い主1,772人に、診療記録から作った30の症例文を示した研究では、獣医師より緊急度を低く判断した回答が28.4%ありました。病名を正しく答えることと、適切な時間内に受診しようとすることには明確な相関がありませんでした。","u":"guide/when-to-call/","a":"b847","e":0},{"c":"11","n":"受診の目安","s":"なぜこれが重要か","t":"つまり、病名が分かることと、急ぎ具合を正しく決めることは別です。検索を続けて病名を絞るより、見たままを伝えて動物病院に判断を返すほうが安全です。","u":"guide/when-to-call/","a":"b848","e":0},{"c":"11","n":"受診の目安","s":"なぜこれが重要か","t":"一方、何でも夜間救急へ行けばよいわけではありません。過剰受診には、費用、犬の通院ストレス、夜間救急の負担があります。この章がまず勧めるのは「受診」ではなく「電話」です。","u":"guide/when-to-call/","a":"b849","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"1. 3つの区分で考える","u":"guide/when-to-call/","a":"b850","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"以下は比較試験から作られた基準ではなく、臨床上の 経験則です 。 境界では安全側に考え、迷ったら電話してください。","u":"guide/when-to-call/","a":"b851","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"今すぐ連絡（夜間・休日でも）","u":"guide/when-to-call/","a":"b852","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"呼吸が苦しそうで、休んでも戻らない。舌や歯ぐきの色が普段と明らかに違う","u":"guide/when-to-call/","a":"b853","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"意識がはっきりしない、反応が鈍い、急に立てない","u":"guide/when-to-call/","a":"b854","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"けいれんが5分以上続く、または短いけいれんを繰り返す","u":"guide/when-to-call/","a":"b855","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"暑い環境のあと、ぐったりして荒い呼吸が止まらない","u":"guide/when-to-call/","a":"b856","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"何度も吐こうとするのに出ず、腹部が張り、落ち着かない","u":"guide/when-to-call/","a":"b857","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"排尿姿勢を繰り返すのに尿が出ない","u":"guide/when-to-call/","a":"b858","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"出血が止まらない。交通事故、転落、強い衝突のあと","u":"guide/when-to-call/","a":"b859","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"急に目を痛がる、開けられない、濁る、瞳孔の左右差が出た","u":"guide/when-to-call/","a":"b860","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"人の薬、殺虫剤、殺鼠剤、キシリトール、チョコレート、ネギ類、ブドウなどを口にした可能性がある。症状がなくても相談する","u":"guide/when-to-call/","a":"b861","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"その日のうちに連絡","u":"guide/when-to-call/","a":"b862","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"半日以上、水も飲まない","u":"guide/when-to-call/","a":"b863","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"初めてのけいれんが短時間で治まり、その後は意識・呼吸・歩行が普段どおりに戻った","u":"guide/when-to-call/","a":"b864","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"嘔吐や下痢が続き、元気がない、または血が混じる","u":"guide/when-to-call/","a":"b865","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"足をほとんど着かない、強く痛がる、腫れがある","u":"guide/when-to-call/","a":"b866","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"白目、歯ぐき、耳の内側が黄色い","u":"guide/when-to-call/","a":"b867","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"未避妊のメスで、発情後1〜2か月に多飲、食欲低下、元気低下、陰部からの分泌物がある。 ぐったりして反応が鈍い、繰り返し吐く、腹部が張る、立てない場合は今すぐ","u":"guide/when-to-call/","a":"b868","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"寝ているときの呼吸が、普段より明らかに速い状態が続く","u":"guide/when-to-call/","a":"b869","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"数日のうちに予約","u":"guide/when-to-call/","a":"b870","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"食欲や元気の低下が続く","u":"guide/when-to-call/","a":"b871","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"意図しない体重変化がある","u":"guide/when-to-call/","a":"b872","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"耳を気にする、においが変わる、首を振る","u":"guide/when-to-call/","a":"b873","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"新しいできもの、または大きさや形が変わるできものがある","u":"guide/when-to-call/","a":"b874","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"咳、くしゃみ、歩き方の変化、多飲・多尿が続く","u":"guide/when-to-call/","a":"b875","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"「数日のうち」は放置してよいという意味ではありません。様子を見るなら、 いつまで見るか と、 何が起きたら中止して連絡するか を先に決めます。この方法は犬で検証されておらず、 経験則です 。","u":"guide/when-to-call/","a":"b876","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"2. 電話では見たままを伝える","u":"guide/when-to-call/","a":"b877","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"年齢、性別と避妊去勢の有無、体重、始まった時刻、悪化の速さ、食事・飲水・排尿・排便、口にした可能性のある物、薬・サプリメント、既往歴を伝えます。「元気がない」だけでなく、「呼んでも起き上がらない」のように動作で説明してください。","u":"guide/when-to-call/","a":"b878","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"けいれん、失神、変な動きや歩き方は、連絡や搬送を遅らせない範囲で全身を動画に残すと診察の材料になります。ただし、動画だけで病名は決まりません。","u":"guide/when-to-call/","a":"b879","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"3. 自己判断で治療しない","u":"guide/when-to-call/","a":"b880","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"人用の解熱鎮痛薬や下痢止めを与えないでください。ロペラミドは、薬を脳から排出する働きに関わるMDR1遺伝子に変異がある犬で、重い神経症状を起こしえます。シェルティにはこの変異がありますが、変異の有無にかかわらず人用薬は与えません。","u":"guide/when-to-call/","a":"b881","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"塩やオキシドールで吐かせないでください。飲んだ物によっては吐かせることが危険で、方法自体でも害が出ます。まず動物病院へ電話し、製品の包装を手元に置きます。","u":"guide/when-to-call/","a":"b882","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"4. 熱中症では冷却を先に始める","u":"guide/when-to-call/","a":"b883","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"暑い場所から移し、 犬の体温より冷たい水を全身にかけ続け、同時に風を当てます。 濡れタオルをかぶせたままにせず、水をかけ続けるか、タオルを頻繁に交換します。準備のために出発を遅らせず、冷やしながら連絡・搬送してください。","u":"guide/when-to-call/","a":"b884","e":0},{"c":"11","n":"受診の目安","s":"実際にどうするか","t":"これは「冷却開始を遅らせない」という推奨であり、氷水でいつまでも冷やすという意味ではありません。中止時期は電話先の獣医師の指示に従ってください。","u":"guide/when-to-call/","a":"b885","e":0},{"c":"11","n":"受診の目安","s":"こんなときは受診を","t":"シェルティでは、胆嚢に粘液がたまる胆嚢粘液嚢腫との関連が報告されています。繰り返す嘔吐に食欲低下や元気消失が伴う、腹部を触られるのを嫌がる、白目や歯ぐきが黄色いときは、その日のうちに連絡してください。これらの症状だけで病名を決めることはできません。","u":"guide/when-to-call/","a":"b886","e":0},{"c":"11","n":"受診の目安","s":"こんなときは受診を","t":"症状のないシェルティ全頭に定期的な腹部超音波検査を勧められる根拠はありません。早期発見が転帰を改善する比較試験がなく、偶然見つかった所見が不要な検査や処置につながる害もあるためです。","u":"guide/when-to-call/","a":"b887","e":0},{"c":"11","n":"受診の目安","s":"こんなときは受診を","t":"一度「様子を見ましょう」と言われたあとでも、予想より速く悪化した、新しい症状が加わった、決めた期限までに改善しない場合は、もう一度連絡してください。","u":"guide/when-to-call/","a":"b888","e":0},{"c":"11","n":"受診の目安","s":"根拠","t":"1. 飼い主による受診判断","u":"guide/when-to-call/","a":"b889","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Farrow M, O'Neill DG, Packer RMA. To see or not to see the vet: A vignette-based study of decision-making by UK dog owners regarding seeking veterinary care for commonly presenting conditions. PLoS One. 2026;21:e0339723.","u":"guide/when-to-call/","a":"b890","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"英国の飼い主1,772人、5,316回答を解析したオンラインの症例文研究です。30疾患の症例文と、一般診療獣医師14人が合意した受診時間枠を比較し、緊急度を過小評価した回答は28.4%でした。病名の正答と緊急度判断に明確な相関はありませんでした（Spearmanの順位相関係数0.13、p=0.482）。","u":"guide/when-to-call/","a":"b891","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"日常的にかかりつけへ連絡する習慣は過小評価の低下と関連しました（オッズ比0.70、95%信頼区間0.61–0.81）。「犬の健康」に関するオンライン集団の参照も低下と関連した一方（0.50、0.33–0.76）、犬種・ドッグスポーツなど一般的な犬のオンライン集団を日常の情報源にすることは、わずかな上昇と関連しました（1.30、1.01–1.66）。原著も相反する結果としており、オンライン集団全般の利益または害は結論できません。","u":"guide/when-to-call/","a":"b892","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"都合の悪い結果と限界。 インターネット検索は病名の正答率をわずかに上げましたが、適切な受診時期とは関連しませんでした。仮想場面への回答で実際の行動ではなく、参加者は自己選択で94.3%が女性でした。英国と日本では診療体制も異なります。","u":"guide/when-to-call/","a":"b893","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"2. 熱中症","u":"guide/when-to-call/","a":"b894","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Thawley VJ, Mandell DC, Burkitt-Creedon JM, et al. RECOVER Guidelines: First Aid in Dogs and Cats. Evidence and Knowledge Gap Analysis With Treatment Recommendations. J Vet Emerg Crit Care. 2026;36(Suppl 1):S3–S35. doi:10.1111/vec.70139.","u":"guide/when-to-call/","a":"b895","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Mandell DC, Thawley VJ, Burkitt-Creedon JM, et al. RECOVER Guidelines: First Aid for Dogs and Cats. Clinical Guidelines. J Vet Emerg Crit Care. 2026;36(Suppl 1):S36–S62. doi:10.1111/vec.70138.","u":"guide/when-to-call/","a":"b896","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"犬猫の病院到着前の応急処置について、GRADE（研究結果の確かさと推奨度を系統的に評価する方法）を用いたガイドラインです。熱中症が疑われる犬猫を涼しい場所へ移し、病院へ運ぶ前に積極的に冷却することを強く推奨しています。ただし、冷却の根拠の質は「非常に低い」と評価されています。冷たい流水を被毛の薄い腹部を中心に皮膚まで届かせる方法と、直腸温39.7〜40.0℃（およそ40℃）で冷却を止める目安は、いずれも専門家意見に基づく弱い推奨です。同ガイドラインは38.6℃未満まで冷やすことを勧めていません。Evidenceペーパーは、浴槽や流し台での冷水浸漬（冷たい水に体を浸す方法）を、意図しない溺水と救助者への危険から提案していません。一方、付属のClinical GuidelinesのFigure 5では、顔を水につけない尾側の部分浸漬を実践例として示しています。","u":"guide/when-to-call/","a":"b897","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Bruchim Y, et al. Heat stroke in dogs: a retrospective study of 54 cases and analysis of risk factors for death. J Vet Intern Med. 2006;20:38–46.","u":"guide/when-to-call/","a":"b898","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"自然発生54例の後ろ向き研究で、発症から来院まで90分を超えたことが死亡と関連しました。ただし観察研究であり、来院の遅れそのものの効果と重症度などの交絡を分けられません。","u":"guide/when-to-call/","a":"b899","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Hall EJ, et al. Cooling Methods Used to Manage Heat-Related Illness in Dogs Presented to Primary Care Veterinary Practices during 2016–2018 in the UK. Vet Sci. 2023;10:465.","u":"guide/when-to-call/","a":"b900","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"英国の一次診療記録623件のうち、冷却記録があった341件を解析し、搬送前に冷却されていたのは74件（21.7%）でした。最も多かったのは濡れタオルでしたが、この研究は冷却法を無作為に比較したものではありません。本文で濡れタオルを断定的に無効としていないのはこのためです。","u":"guide/when-to-call/","a":"b901","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"都合の悪い結果。 来院時の低体温は予後不良と関連した報告があります。過剰冷却の影響か、重症な犬ほど体温を保てなかったのかは分離できません。実験的研究では氷水への浸漬直後の死亡も報告されており、氷水による無制限の冷却は勧めません。","u":"guide/when-to-call/","a":"b902","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"熱中症の研究は犬全体が対象です。シェルティの厚い被毛が独立した危険因子であることを直接示す犬の研究は確認できません。もっともらしい機序から犬種固有の危険性を推定しません。","u":"guide/when-to-call/","a":"b903","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"3. 家庭で吐かせること","u":"guide/when-to-call/","a":"b904","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"上記RECOVERガイドラインは、急性中毒後に家庭で一律に吐かせることに強く反対しています（根拠の質は低い）。犬猫で転帰を改善する直接の研究がなく、受診を遅らせる可能性があり、オキシドールは犬猫の消化管を傷つけた報告があるためです。ただし、すぐに動物病院へ行けず、獣医師または動物の中毒相談窓口が個別に指示した場合の催吐は、専門家意見に基づく弱い提案としています。本章の「自分で吐かせない」は、この条件付き例外を否定するものではありません。","u":"guide/when-to-call/","a":"b905","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"4. 動画と睡眠時呼吸数","u":"guide/when-to-call/","a":"b906","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Packer RMA, et al. Inter-observer agreement of canine and feline paroxysmal event semiology and classification. BMC Vet Res. 2015;11:39.","u":"guide/when-to-call/","a":"b907","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"発作様動画100本の分類では、獣医師間の一致は十分ではありませんでした。動画は診断を確定する道具ではなく、診察時に消えている所見を伝える補助資料です。","u":"guide/when-to-call/","a":"b908","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Rishniw M, et al. Sleeping respiratory rates in apparently healthy adult dogs. Res Vet Sci. 2012;93:965–969.","u":"guide/when-to-call/","a":"b909","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"健康な成犬114頭を家庭で反復測定し、犬ごとの平均は約13回／分でした。ただし異常の閾値を検証した研究ではありません。本章は一律の基準値を示さず、その犬の普段の値からの持続的な上昇を電話で伝える材料としています。健康犬の急変全般を検出できるかは未検証です。","u":"guide/when-to-call/","a":"b910","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"5. シェルティと胆嚢粘液嚢腫","u":"guide/when-to-call/","a":"b911","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Kutsunai M, et al. The association between gall bladder mucoceles and hyperlipidaemia in dogs. Vet J. 2014;199:76–79.","u":"guide/when-to-call/","a":"b912","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"単一施設の症例対照研究58頭で、シェルティと胆嚢粘液嚢腫の関連が報告されました（オッズ比6.21）。施設を受診した集団の比であり、シェルティの発症率は示しません。","u":"guide/when-to-call/","a":"b913","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"Aguirre AL, et al. Gallbladder disease in Shetland Sheepdogs: 38 cases. J Am Vet Med Assoc. 2007;231:79–88.","u":"guide/when-to-call/","a":"b914","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"シェルティ38例の症例集積です。対照群がなく、無症状犬のスクリーニングが転帰を改善するかは分かりません。胆嚢摘出術の入院中死亡率は報告間で幅があり、施設、重症度、緊急手術か予定手術かの違いを含みます。したがって、無症状の全頭検査は推奨していません。","u":"guide/when-to-call/","a":"b915","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"6. 確実性と、直接の根拠がない部分","u":"guide/when-to-call/","a":"b916","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"推奨1の良い方向に働くことの確かさを「低」としたのは、中心となる研究が英国の仮想症例研究1件で、実際の受診行動や転帰を測っていないためです。推奨2は、犬の症例集積、体温が高い時間を短くする生理学的妥当性、他種の知見が同じ方向を示すため「中」としましたが、犬での無作為化試験はありません。","u":"guide/when-to-call/","a":"b917","e":1},{"c":"11","n":"受診の目安","s":"根拠","t":"シェルティで各行動の効果量を調べた研究はなく、両推奨とも「非常に低」です。A・B・Cの症状割り当て（初回の短いけいれんを含む）、「その日のうち」「数日のうち」という境界、電話で伝える項目、様子を見る期限と中止条件には直接の検証がなく、 経験則です 。","u":"guide/when-to-call/","a":"b918","e":1},{"c":"12","n":"災害・緊急時","s":"この章が扱う範囲","t":"地震・水害などで自宅を離れるときの準備と、避難生活中の犬の健康管理を扱います。災害の種類や地域によって安全な行動は変わるため、自治体のハザードマップと避難所の受け入れ条件も確認してください。","u":"guide/disaster-preparation/","a":"b919","e":0},{"c":"12","n":"災害・緊急時","s":"この章が扱う範囲","t":"ここでいう 同行避難 は、飼い主が犬を連れて安全な場所まで避難する行動です。避難所で同じ部屋に入れるという意味ではありません。犬と避難所で過ごす 同伴避難 でも、飼育場所は同室、別室、屋外など施設ごとに異なります。","u":"guide/disaster-preparation/","a":"b920","e":0},{"c":"12","n":"災害・緊急時","s":"この章の推奨","t":"推奨1 犬を連れて避難できる状態を作る","u":"guide/disaster-preparation/","a":"b921","e":0},{"c":"12","n":"災害・緊急時","s":"この章の推奨","t":"クレート（犬を安全に運び、休ませる箱）に自分から入り、扉を閉めても落ち着いて待てるようにしてください。マイクロチップの登録情報を最新に保ち、連絡先を書いた迷子札も付けてください。","u":"guide/disaster-preparation/","a":"b922","e":0},{"c":"12","n":"災害・緊急時","s":"この章の推奨","t":"推奨2 避難先と備蓄を一つに頼らない","u":"guide/disaster-preparation/","a":"b923","e":0},{"c":"12","n":"災害・緊急時","s":"この章の推奨","t":"指定避難所で犬と同室に入れることだけを前提にしないでください。安全な親戚・知人宅、ペット可の宿泊施設、在宅避難などを含め、使える避難先を複数確認してください。犬のフード、水、薬、衛生用品は少なくとも5日分、できれば7日分以上を持ち出せる形で備えてください。","u":"guide/disaster-preparation/","a":"b924","e":0},{"c":"12","n":"災害・緊急時","s":"この章の推奨","t":"二つに分けたのは、推奨1が安全な移動と逸走後の帰還、推奨2が避難先の不一致と物資不足に備えるものだからです。いずれも強い推奨ですが、 強さの根拠は研究の多さではなく、適切に準備した場合の害が小さく、災害時に初めて用意できないという必要性にあります。","u":"guide/disaster-preparation/","a":"b925","e":0},{"c":"12","n":"災害・緊急時","s":"なぜこれが重要か","t":"犬を連れて動く準備がないと、犬だけでなく飼い主の避難も遅れます。米国の洪水後調査では、多頭飼育、屋外飼育、猫用キャリーがないことなどが、ペットを含む避難の失敗と関連しました。一方、別のハリケーン後調査では、ペット飼育自体は避難失敗の統計的な要因になりませんでした。したがって「犬がいると避難できない」のではなく、個別の準備不足が障害になり得る、と読むのが妥当です。","u":"guide/disaster-preparation/","a":"b926","e":0},{"c":"12","n":"災害・緊急時","s":"なぜこれが重要か","t":"シェルティは、フィンランドの大規模な飼い主調査で、見知らぬ人・犬・状況への恐怖が強い犬種群に入りました。ただし、災害時の逸走や避難所での問題を直接調べた研究ではありません。 恐怖傾向が強い犬では、混乱した環境で逸走防止と落ち着ける場所が特に重要になる、という部分は推論です。","u":"guide/disaster-preparation/","a":"b927","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"1．避難前に整える","u":"guide/disaster-preparation/","a":"b928","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"クレートは短時間から練習し、食べ物や休息と結びつけます。押し込む、罰に使う、急に長時間閉じ込める方法は避けます。","u":"guide/disaster-preparation/","a":"b929","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"首輪、ハーネス、リードが、後ずさりしても抜けないか点検します。予備のリードも用意します。","u":"guide/disaster-preparation/","a":"b930","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"マイクロチップの氏名・住所・電話番号を最新にし、外から読める迷子札を併用します。鑑札と狂犬病予防注射済票も確認します。","u":"guide/disaster-preparation/","a":"b931","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"自治体に、犬を受け入れる避難所、飼育場所、必要なクレートや証明書を確認します。災害時には条件が変わり得ます。","u":"guide/disaster-preparation/","a":"b932","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"家具を固定し、クレートを落下物や倒れる家具から離します。","u":"guide/disaster-preparation/","a":"b933","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"2．持ち出し品をまとめる","u":"guide/disaster-preparation/","a":"b934","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"フードと水、食器、常用薬、ペットシーツ、排泄物用の袋、タオル、予備の首輪・リード、犬と飼い主が一緒に写った写真を一つにします。フードは古いものから使って補充します。","u":"guide/disaster-preparation/","a":"b935","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"薬を毎日使う犬では、薬剤名、1回量、回数、持病、かかりつけ動物病院の連絡先を紙にも残してください。ワクチン歴、マイクロチップ番号、遺伝子検査結果もあると診療に役立ちます。避難中に薬が切れそうなら、切れる前に相談します。","u":"guide/disaster-preparation/","a":"b936","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"備蓄の「5日、できれば7日以上」は行政上の実務的な目安で、7日あれば安全と証明した研究はありません。療法食や入手しにくい薬が必要なら、獣医師と相談してより長く備えます。","u":"guide/disaster-preparation/","a":"b937","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"3．避難先を複数確認する","u":"guide/disaster-preparation/","a":"b938","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"指定避難所のほか、安全が確認できる自宅、親戚・知人宅、ペット可の宿泊施設、動物病院や預かり施設を候補にします。「二つ以上」は研究で決まった数ではなく、 一か所が使えない場合に備える 経験則です 。 事前に受け入れの可否、費用、連絡方法を確認してください。","u":"guide/disaster-preparation/","a":"b939","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"車内は短時間の待機場所にはなっても、気温、換気、排気、浸水などの危険があります。特に犬だけを残す計画は避け、車内を安全に保てないときは別の場所へ移します。","u":"guide/disaster-preparation/","a":"b940","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"4．避難中に観察する","u":"guide/disaster-preparation/","a":"b941","e":0},{"c":"12","n":"災害・緊急時","s":"実際にどうするか","t":"食欲、飲水、尿と便、呼吸、歩き方、服薬の有無を毎日確認します。大きな音や見知らぬ人に反応する犬では、クレートを人通りから離し、布で一部を覆うなど刺激を減らします。暑い時期は被毛を理由に安心せず、日陰、換気、水を確保してください。","u":"guide/disaster-preparation/","a":"b942","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"次の場合は、夜間・休日でも動物病院へ連絡してください。 避難場所が危険なら、まず人と犬を安全な場所へ移します。","u":"guide/disaster-preparation/","a":"b943","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"呼びかけへの反応が鈍い、倒れる、けいれんする","u":"guide/disaster-preparation/","a":"b944","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"呼吸が苦しそう、舌や歯ぐきの色がおかしい","u":"guide/disaster-preparation/","a":"b945","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"暑い環境のあとに激しい呼吸、ふらつき、嘔吐・下痢、意識の変化がある","u":"guide/disaster-preparation/","a":"b946","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"大きなけが、止まらない出血、交通事故、落下物による受傷がある","u":"guide/disaster-preparation/","a":"b947","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"何度も吐く、水も保てない、腹部が急に張る","u":"guide/disaster-preparation/","a":"b948","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"常用薬が切れ、その中断が危険になり得る","u":"guide/disaster-preparation/","a":"b949","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"熱中症が疑われるときは、連絡と搬送の準備をしながら日陰や冷房のある場所へ移し、 体温より低い水（冷たい水でよく、氷水である必要はありません） を体にかけて送風します。意識があり、若く健康な犬を安全に扱える場合は、冷たい水に体を浸す方法も選択肢です。意識が悪い犬に水を飲ませないでください。濡れたタオルで全身を包み続けると放熱を妨げることがあります。改善しても臓器障害が遅れて現れることがあるため、受診が必要です。","u":"guide/disaster-preparation/","a":"b950","e":0},{"c":"12","n":"災害・緊急時","s":"こんなときは受診を","t":"軽い軟便や食欲低下でも、24時間ほどで改善しない、子犬・高齢犬・持病のある犬、飲水や排尿が明らかに減る場合は早めに相談してください。","u":"guide/disaster-preparation/","a":"b951","e":0},{"c":"12","n":"災害・緊急時","s":"「犬と一緒に逃げる」と「同じ部屋で暮らす」は別です","t":"国が基本としている同行避難は、犬を連れて危険な場所から逃げる行動です。避難所で飼い主と犬が同室で過ごせることを保証する制度ではありません。この違いを知らないと、現地の条件が想定と違い、避難をためらう原因になります。","u":"guide/disaster-preparation/","a":"b952","e":0},{"c":"12","n":"災害・緊急時","s":"「犬と一緒に逃げる」と「同じ部屋で暮らす」は別です","t":"避難所を使わないことを勧めているわけでもありません。避難所は情報や物資を得る拠点になります。大切なのは、自治体の条件を事前に確認し、そこが使えない場合の行き先も持つことです。","u":"guide/disaster-preparation/","a":"b953","e":0},{"c":"12","n":"災害・緊急時","s":"根拠","t":"行政文書と制度","u":"guide/disaster-preparation/","a":"b954","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"環境省「人とペットの災害対策ガイドライン」（2018年）は、飼い主自身の安全を確保したうえで、ペットと同行避難することを基本としています。「受け入れ可能な避難所へ必ず入れる」「飼い主と同室に入れる」という意味ではなく、受け入れ方は自治体と施設によって異なります。環境省の災害対策ページには、2026年9月確認時点でも2018年版と2020年の飼い主向け資料が掲載されています。2026年に示された改訂案の正式反映は次回確認事項とします。","u":"guide/disaster-preparation/","a":"b955","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"同ガイドラインは、フードと水を少なくとも5日分、できれば7日分以上、療法食や薬はさらに長期間用意するよう示しています。これは介入試験による閾値ではなく、救援物資が届くまでの自助を想定した実務上の目安です。","u":"guide/disaster-preparation/","a":"b956","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"避難行動の研究","u":"guide/disaster-preparation/","a":"b957","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"Heathら（Am J Epidemiol. 2001;153:659-665）は、1997年のカリフォルニア州洪水で避難指示を受けた397世帯を調査しました。避難しなかった世帯は19.4%でした。子どものいないペット飼育世帯では、飼育頭数の増加が避難失敗と関連し、多頭飼育、屋外飼育、猫用キャリーがないことも障害として挙げられました。災害後の観察研究であり、日本の制度や地震災害へそのまま当てはめることはできません。","u":"guide/disaster-preparation/","a":"b958","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"推奨に都合の悪い結果として、Huntら（Animals. 2012;2:529-539）のハリケーン・アイリーン後の調査では、ペット飼育は避難失敗の統計的な要因ではありませんでした。「準備すれば避難成功率が上がる」という介入効果は確定していません。","u":"guide/disaster-preparation/","a":"b959","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"シェルティの恐怖傾向","u":"guide/disaster-preparation/","a":"b960","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"Salonenら（Sci Rep. 2020;10:2962）は、フィンランドの飼い犬13,715頭を対象としたオンライン質問紙で、犬種ごとの不安関連行動を比較しました。シェットランド・シープドッグは、見知らぬ人・犬・状況に対する恐怖が強い群に入りました。一方、音への過敏さが最上位の犬種ではありませんでした。飼い主の自己申告で選択バイアスがあり、災害時の行動を調べた研究でもありません。避難時の逸走対策へ結びつける部分は推論です。","u":"guide/disaster-preparation/","a":"b961","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"熱中症の初期対応","u":"guide/disaster-preparation/","a":"b962","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"Hallら（Sci Rep. 2020;10:9128）は、英国の一次診療記録905,543頭から395件の熱関連疾患を特定し、受診例の致死率は14.18%でした。シェルティは高リスク犬種として特定されませんでしたが、非記載から低リスクとは判断できません。","u":"guide/disaster-preparation/","a":"b963","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"Hallら（Vet Sci. 2023;10:465）は、搬送前に冷却された犬が21.7%にとどまり、濡れたタオルが多く使われていたと報告しました。獣医救急領域では、搬送を不必要に遅らせず、冷水浸漬または注水＋送風で早く冷却を始めることが勧められています。「ぬるい水でなければならない」という根拠はなく、体温より低い水を使います。意識があり、若く健康な犬では冷水浸漬が第一選択とされていますが、高齢犬や基礎疾患のある犬での最適な方法は確定していません。このため本文では、幅広い犬に実行しやすい注水＋送風を基本に置き、条件を満たす犬では冷水浸漬も選択肢として示しました。","u":"guide/disaster-preparation/","a":"b964","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"確実性と利益・害","u":"guide/disaster-preparation/","a":"b965","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"二つの推奨を直接検証した介入研究はありません。避難行動の根拠は主に米国の災害後調査で、日本への非直接性があります。犬種別の効果量も測定されていないため、シェルティでどれだけ役立つかの確かさは「非常に低」としました。","u":"guide/disaster-preparation/","a":"b966","e":1},{"c":"12","n":"災害・緊急時","s":"根拠","t":"良い方向に働くことの確かさは、避難を妨げた具体的要因と行政の災害対応から支持されるため「中」としました。適切なクレート練習、所有者明示、備蓄、避難先の確認には平常時の利点もあり、害は小さいと考えられます。ただし、強制的なクレート収容は恐怖を悪化させ、「避難所では犬を受け入れない」と思い込むと利用できる支援を逃す可能性があります。推奨は、段階的な練習と地域条件の確認を含めて初めて成立します。","u":"guide/disaster-preparation/","a":"b967","e":1}];